# ================================================================
# FreeLang v4 Core - Scanner (Character-level Lexer Engine)
# Responsible for character-by-character source scanning
# with lookahead, position tracking, and error recovery
# ================================================================

# ---- Scanner State ----

fn create_scanner(source: string) -> any {
  return {
    "source": source,
    "source_len": length(source),
    "pos": 0,
    "line": 1,
    "col": 1,
    "start_pos": 0,
    "start_line": 1,
    "start_col": 1,
    "errors": [],
    "error_count": 0,
    "tab_width": 4
  }
}

# ---- Position Management ----

fn scanner_mark_start(s: any) -> any {
  s["start_pos"] = s["pos"]
  s["start_line"] = s["line"]
  s["start_col"] = s["col"]
  return s
}

fn scanner_at_end(s: any) -> bool {
  return s["pos"] >= s["source_len"]
}

fn scanner_remaining(s: any) -> i32 {
  return s["source_len"] - s["pos"]
}

# ---- Character Access ----

fn scanner_peek(s: any) -> string {
  if scanner_at_end(s) {
    return ""
  }
  return s["source"][s["pos"]]
}

fn scanner_peek_next(s: any) -> string {
  next_pos = s["pos"] + 1
  if next_pos >= s["source_len"] {
    return ""
  }
  return s["source"][next_pos]
}

fn scanner_peek_at(s: any, offset: i32) -> string {
  target = s["pos"] + offset
  if target >= s["source_len"] or target < 0 {
    return ""
  }
  return s["source"][target]
}

fn scanner_advance(s: any) -> string {
  if scanner_at_end(s) {
    return ""
  }
  ch = s["source"][s["pos"]]
  s["pos"] = s["pos"] + 1
  if ch == "\n" {
    s["line"] = s["line"] + 1
    s["col"] = 1
  } else if ch == "\t" {
    s["col"] = s["col"] + s["tab_width"]
  } else {
    s["col"] = s["col"] + 1
  }
  return ch
}

fn scanner_advance_n(s: any, n: i32) -> string {
  result = ""
  i = 0
  while i < n {
    ch = scanner_advance(s)
    result = result + ch
    i = i + 1
  }
  return result
}

# ---- Matching ----

fn scanner_match(s: any, expected: string) -> bool {
  if scanner_at_end(s) {
    return false
  }
  if s["source"][s["pos"]] != expected {
    return false
  }
  scanner_advance(s)
  return true
}

fn scanner_match_sequence(s: any, seq: string) -> bool {
  seq_len = length(seq)
  if scanner_remaining(s) < seq_len {
    return false
  }
  i = 0
  while i < seq_len {
    if s["source"][s["pos"] + i] != seq[i] {
      return false
    }
    i = i + 1
  }
  scanner_advance_n(s, seq_len)
  return true
}

# ---- Character Classification ----

fn is_digit(ch: string) -> bool {
  return ch >= "0" and ch <= "9"
}

fn is_hex_digit(ch: string) -> bool {
  return is_digit(ch) or
         (ch >= "a" and ch <= "f") or
         (ch >= "A" and ch <= "F")
}

fn is_octal_digit(ch: string) -> bool {
  return ch >= "0" and ch <= "7"
}

fn is_binary_digit(ch: string) -> bool {
  return ch == "0" or ch == "1"
}

fn is_alpha(ch: string) -> bool {
  return (ch >= "a" and ch <= "z") or
         (ch >= "A" and ch <= "Z") or
         ch == "_"
}

fn is_alphanumeric(ch: string) -> bool {
  return is_alpha(ch) or is_digit(ch)
}

fn is_whitespace(ch: string) -> bool {
  return ch == " " or ch == "\t" or ch == "\r"
}

fn is_newline(ch: string) -> bool {
  return ch == "\n"
}

fn is_upper(ch: string) -> bool {
  return ch >= "A" and ch <= "Z"
}

fn is_lower(ch: string) -> bool {
  return ch >= "a" and ch <= "z"
}

fn is_operator_char(ch: string) -> bool {
  return ch == "+" or ch == "-" or ch == "*" or ch == "/" or
         ch == "%" or ch == "=" or ch == "<" or ch == ">" or
         ch == "!" or ch == "&" or ch == "|" or ch == "^" or
         ch == "~"
}

fn is_delimiter(ch: string) -> bool {
  return ch == "(" or ch == ")" or ch == "{" or ch == "}" or
         ch == "[" or ch == "]"
}

fn is_punctuation(ch: string) -> bool {
  return ch == "," or ch == "." or ch == ":" or ch == ";" or
         ch == "#" or ch == "@" or ch == "?" or ch == "_"
}

# ---- Whitespace and Comment Skipping ----

fn scanner_skip_whitespace(s: any) -> any {
  while not scanner_at_end(s) {
    ch = scanner_peek(s)
    if is_whitespace(ch) {
      scanner_advance(s)
    } else {
      break
    }
  }
  return s
}

fn scanner_skip_line_comment(s: any) -> any {
  # Skip until end of line (# comment)
  while not scanner_at_end(s) and scanner_peek(s) != "\n" {
    scanner_advance(s)
  }
  return s
}

fn scanner_skip_block_comment(s: any) -> any {
  # Skip /* ... */ block comment with nesting support
  depth = 1
  scanner_advance(s)  # skip *
  scanner_advance(s)  # skip /... actually skip the opening

  while not scanner_at_end(s) and depth > 0 {
    ch = scanner_peek(s)
    next = scanner_peek_next(s)

    if ch == "/" and next == "*" {
      depth = depth + 1
      scanner_advance(s)
      scanner_advance(s)
    } else if ch == "*" and next == "/" {
      depth = depth - 1
      scanner_advance(s)
      scanner_advance(s)
    } else {
      scanner_advance(s)
    }
  }

  if depth > 0 {
    scanner_add_error(s, "Unterminated block comment")
  }

  return s
}

fn scanner_skip_trivia(s: any) -> any {
  # Skip all whitespace, newlines, and comments
  while not scanner_at_end(s) {
    ch = scanner_peek(s)

    if is_whitespace(ch) or is_newline(ch) {
      scanner_advance(s)
    } else if ch == "#" {
      scanner_skip_line_comment(s)
    } else if ch == "/" and scanner_peek_next(s) == "*" {
      scanner_skip_block_comment(s)
    } else if ch == "/" and scanner_peek_next(s) == "/" {
      scanner_skip_line_comment(s)
    } else {
      break
    }
  }
  return s
}

# ---- Error Handling ----

fn scanner_add_error(s: any, message: string) -> any {
  err = {
    "message": message,
    "line": s["line"],
    "col": s["col"],
    "pos": s["pos"]
  }
  push(s["errors"], err)
  s["error_count"] = s["error_count"] + 1
  return s
}

fn scanner_add_error_at(s: any, message: string, line: i32, col: i32) -> any {
  err = {
    "message": message,
    "line": line,
    "col": col,
    "pos": s["pos"]
  }
  push(s["errors"], err)
  s["error_count"] = s["error_count"] + 1
  return s
}

fn scanner_has_errors(s: any) -> bool {
  return s["error_count"] > 0
}

fn scanner_get_errors(s: any) -> array {
  return s["errors"]
}

# ---- Text Extraction ----

fn scanner_extract_from_start(s: any) -> string {
  # Extract text from the marked start position to current position
  result = ""
  i = s["start_pos"]
  while i < s["pos"] {
    result = result + s["source"][i]
    i = i + 1
  }
  return result
}

fn scanner_extract_range(s: any, from: i32, to: i32) -> string {
  result = ""
  i = from
  while i < to and i < s["source_len"] {
    result = result + s["source"][i]
    i = i + 1
  }
  return result
}

# ---- Lexeme Scanning Helpers ----

fn scanner_scan_while(s: any, predicate: any) -> string {
  result = ""
  while not scanner_at_end(s) {
    ch = scanner_peek(s)
    if predicate(ch) {
      result = result + ch
      scanner_advance(s)
    } else {
      break
    }
  }
  return result
}

fn scanner_scan_digits(s: any) -> string {
  return scanner_scan_while(s, is_digit)
}

fn scanner_scan_hex_digits(s: any) -> string {
  return scanner_scan_while(s, is_hex_digit)
}

fn scanner_scan_identifier_chars(s: any) -> string {
  return scanner_scan_while(s, is_alphanumeric)
}

# ---- String Scanning ----

fn scanner_scan_string(s: any, quote: string) -> string {
  # Advance past opening quote
  scanner_advance(s)
  result = ""

  while not scanner_at_end(s) {
    ch = scanner_peek(s)

    if ch == quote {
      scanner_advance(s)  # closing quote
      return result
    }

    if ch == "\n" {
      scanner_add_error(s, "Unterminated string literal")
      return result
    }

    # Escape sequences
    if ch == "\\" {
      scanner_advance(s)
      esc = scanner_peek(s)
      match esc {
        "n"  => { result = result + "\n"; scanner_advance(s) },
        "t"  => { result = result + "\t"; scanner_advance(s) },
        "r"  => { result = result + "\r"; scanner_advance(s) },
        "\\" => { result = result + "\\"; scanner_advance(s) },
        "'"  => { result = result + "'"; scanner_advance(s) },
        "\"" => { result = result + "\""; scanner_advance(s) },
        "0"  => { result = result + "\0"; scanner_advance(s) },
        "x"  => {
          scanner_advance(s)
          hex = scanner_scan_hex_digits(s)
          if length(hex) != 2 {
            scanner_add_error(s, "Invalid hex escape: expected 2 digits")
          }
          result = result + "\\x" + hex
        },
        "u"  => {
          scanner_advance(s)
          if scanner_peek(s) == "{" {
            scanner_advance(s)
            unicode = scanner_scan_hex_digits(s)
            if scanner_peek(s) != "}" {
              scanner_add_error(s, "Missing closing brace in unicode escape")
            } else {
              scanner_advance(s)
            }
            result = result + "\\u{" + unicode + "}"
          } else {
            scanner_add_error(s, "Expected { after \\u")
          }
        },
        _ => {
          scanner_add_error(s, "Unknown escape sequence: \\" + esc)
          result = result + esc
          scanner_advance(s)
        }
      }
    } else {
      result = result + ch
      scanner_advance(s)
    }
  }

  scanner_add_error(s, "Unterminated string literal")
  return result
}

# ---- Raw String Scanning ----

fn scanner_scan_raw_string(s: any) -> string {
  # r"..." or r#"..."#
  scanner_advance(s)  # skip 'r'

  # Count hash marks
  hash_count = 0
  while not scanner_at_end(s) and scanner_peek(s) == "#" {
    hash_count = hash_count + 1
    scanner_advance(s)
  }

  if scanner_peek(s) != "\"" {
    scanner_add_error(s, "Expected '\"' after 'r' and hashes")
    return ""
  }
  scanner_advance(s)  # skip opening "

  result = ""
  while not scanner_at_end(s) {
    ch = scanner_peek(s)

    if ch == "\"" {
      # Check for matching hash count
      saved_pos = s["pos"]
      scanner_advance(s)
      matched_hashes = 0
      while not scanner_at_end(s) and scanner_peek(s) == "#" and matched_hashes < hash_count {
        matched_hashes = matched_hashes + 1
        scanner_advance(s)
      }
      if matched_hashes == hash_count {
        return result
      }
      # Not enough hashes, include as literal
      result = result + "\""
      i = 0
      while i < matched_hashes {
        result = result + "#"
        i = i + 1
      }
    } else {
      result = result + ch
      scanner_advance(s)
    }
  }

  scanner_add_error(s, "Unterminated raw string")
  return result
}

# ---- Multi-line String Scanning ----

fn scanner_scan_multiline_string(s: any) -> string {
  # """...""" triple-quoted string
  scanner_advance(s)  # skip first "
  scanner_advance(s)  # skip second "
  scanner_advance(s)  # skip third "

  result = ""
  while not scanner_at_end(s) {
    ch = scanner_peek(s)

    if ch == "\"" and scanner_peek_next(s) == "\"" and scanner_peek_at(s, 2) == "\"" {
      scanner_advance(s)
      scanner_advance(s)
      scanner_advance(s)
      return result
    }

    result = result + ch
    scanner_advance(s)
  }

  scanner_add_error(s, "Unterminated multi-line string")
  return result
}

# ---- Number Scanning ----

fn scanner_scan_number(s: any) -> any {
  # Returns { "type": "INTEGER"|"FLOAT"|"HEX"|"OCTAL"|"BINARY", "value": string }
  start = s["pos"]

  # Check for hex/octal/binary prefix
  if scanner_peek(s) == "0" {
    next = scanner_peek_next(s)

    if next == "x" or next == "X" {
      scanner_advance(s)  # skip 0
      scanner_advance(s)  # skip x
      hex_val = "0x" + scanner_scan_hex_digits(s)
      if length(hex_val) <= 2 {
        scanner_add_error(s, "Invalid hex literal: expected digits after 0x")
      }
      return { "type": "HEX", "value": hex_val }
    }

    if next == "o" or next == "O" {
      scanner_advance(s)  # skip 0
      scanner_advance(s)  # skip o
      oct_val = "0o" + scanner_scan_while(s, is_octal_digit)
      if length(oct_val) <= 2 {
        scanner_add_error(s, "Invalid octal literal: expected digits after 0o")
      }
      return { "type": "OCTAL", "value": oct_val }
    }

    if next == "b" or next == "B" {
      scanner_advance(s)  # skip 0
      scanner_advance(s)  # skip b
      bin_val = "0b" + scanner_scan_while(s, is_binary_digit)
      if length(bin_val) <= 2 {
        scanner_add_error(s, "Invalid binary literal: expected digits after 0b")
      }
      return { "type": "BINARY", "value": bin_val }
    }
  }

  # Integer part (with underscore separators)
  int_part = ""
  while not scanner_at_end(s) {
    ch = scanner_peek(s)
    if is_digit(ch) {
      int_part = int_part + ch
      scanner_advance(s)
    } else if ch == "_" and is_digit(scanner_peek_next(s)) {
      scanner_advance(s)  # skip underscore separator
    } else {
      break
    }
  }

  # Check for float
  is_float = false

  if not scanner_at_end(s) and scanner_peek(s) == "." {
    # Ensure it's not a method call (e.g., 42.to_string)
    next_ch = scanner_peek_next(s)
    if is_digit(next_ch) {
      is_float = true
      int_part = int_part + "."
      scanner_advance(s)  # skip .

      # Fractional part
      while not scanner_at_end(s) {
        ch = scanner_peek(s)
        if is_digit(ch) {
          int_part = int_part + ch
          scanner_advance(s)
        } else if ch == "_" and is_digit(scanner_peek_next(s)) {
          scanner_advance(s)
        } else {
          break
        }
      }
    }
  }

  # Scientific notation
  if not scanner_at_end(s) {
    ch = scanner_peek(s)
    if ch == "e" or ch == "E" {
      is_float = true
      int_part = int_part + ch
      scanner_advance(s)

      # Optional sign
      if not scanner_at_end(s) {
        sign = scanner_peek(s)
        if sign == "+" or sign == "-" {
          int_part = int_part + sign
          scanner_advance(s)
        }
      }

      exp_digits = scanner_scan_digits(s)
      if length(exp_digits) == 0 {
        scanner_add_error(s, "Expected digits in exponent")
      }
      int_part = int_part + exp_digits
    }
  }

  # Type suffix (i32, f64, etc.)
  if not scanner_at_end(s) and is_alpha(scanner_peek(s)) {
    suffix = scanner_scan_identifier_chars(s)
    int_part = int_part + suffix
  }

  if is_float {
    return { "type": "FLOAT", "value": int_part }
  }
  return { "type": "INTEGER", "value": int_part }
}

# ---- String Interpolation ----

fn scanner_scan_interpolated_string(s: any) -> array {
  # f"Hello {name}, your score is {score}"
  # Returns array of token-like segments
  scanner_advance(s)  # skip 'f'
  scanner_advance(s)  # skip '"'

  segments = []
  current_text = ""

  while not scanner_at_end(s) {
    ch = scanner_peek(s)

    if ch == "\"" {
      if length(current_text) > 0 {
        push(segments, { "type": "TEXT", "value": current_text })
      }
      scanner_advance(s)
      return segments
    }

    if ch == "{" {
      if scanner_peek_next(s) == "{" {
        # Escaped brace
        current_text = current_text + "{"
        scanner_advance(s)
        scanner_advance(s)
      } else {
        # Start interpolation
        if length(current_text) > 0 {
          push(segments, { "type": "TEXT", "value": current_text })
          current_text = ""
        }
        scanner_advance(s)  # skip {

        # Scan expression until }
        expr = ""
        brace_depth = 1
        while not scanner_at_end(s) and brace_depth > 0 {
          ech = scanner_peek(s)
          if ech == "{" {
            brace_depth = brace_depth + 1
            expr = expr + ech
          } else if ech == "}" {
            brace_depth = brace_depth - 1
            if brace_depth > 0 {
              expr = expr + ech
            }
          } else {
            expr = expr + ech
          }
          scanner_advance(s)
        }

        push(segments, { "type": "EXPR", "value": expr })
      }
    } else if ch == "}" and scanner_peek_next(s) == "}" {
      current_text = current_text + "}"
      scanner_advance(s)
      scanner_advance(s)
    } else if ch == "\\" {
      scanner_advance(s)
      esc = scanner_peek(s)
      match esc {
        "n" => { current_text = current_text + "\n" },
        "t" => { current_text = current_text + "\t" },
        "\\" => { current_text = current_text + "\\" },
        "\"" => { current_text = current_text + "\"" },
        _ => { current_text = current_text + "\\" + esc }
      }
      scanner_advance(s)
    } else {
      current_text = current_text + ch
      scanner_advance(s)
    }
  }

  scanner_add_error(s, "Unterminated interpolated string")
  if length(current_text) > 0 {
    push(segments, { "type": "TEXT", "value": current_text })
  }
  return segments
}

# ---- Snapshot / Restore (for parser backtracking) ----

fn scanner_snapshot(s: any) -> any {
  return {
    "pos": s["pos"],
    "line": s["line"],
    "col": s["col"],
    "error_count": s["error_count"]
  }
}

fn scanner_restore(s: any, snapshot: any) -> any {
  s["pos"] = snapshot["pos"]
  s["line"] = snapshot["line"]
  s["col"] = snapshot["col"]
  # Trim errors added after snapshot
  while s["error_count"] > snapshot["error_count"] {
    pop(s["errors"])
    s["error_count"] = s["error_count"] - 1
  }
  return s
}

# ================================================================
# FreeLang v4 Core - Main Lexer
# Converts source code into a token stream
# Performance target: R1 < 50ms for 1,000 tokens
# ================================================================

# ---- Lexer State ----

fn create_lexer(source: string) -> any {
  scanner = create_scanner(source)
  keyword_map = build_keyword_map()

  return {
    "scanner": scanner,
    "keyword_map": keyword_map,
    "tokens": [],
    "token_count": 0,
    "start_time": 0,
    "elapsed_ms": 0,
    "mode": "NORMAL",
    "interpolation_depth": 0,
    "paren_depth": 0,
    "brace_depth": 0,
    "bracket_depth": 0
  }
}

# ---- Main Tokenize Function ----

fn tokenize(source: string) -> any {
  lex = create_lexer(source)
  lex["start_time"] = time_now()

  while not scanner_at_end(lex["scanner"]) {
    scanner_skip_trivia(lex["scanner"])

    if scanner_at_end(lex["scanner"]) {
      break
    }

    scanner_mark_start(lex["scanner"])
    token = lex_next_token(lex)

    if token != nil {
      push(lex["tokens"], token)
      lex["token_count"] = lex["token_count"] + 1
    }
  }

  # Add EOF token
  eof = create_token(
    TOKEN_EOF, "",
    lex["scanner"]["line"],
    lex["scanner"]["col"],
    lex["scanner"]["pos"]
  )
  push(lex["tokens"], eof)
  lex["token_count"] = lex["token_count"] + 1

  lex["elapsed_ms"] = time_now() - lex["start_time"]

  return {
    "tokens": lex["tokens"],
    "token_count": lex["token_count"],
    "errors": scanner_get_errors(lex["scanner"]),
    "error_count": lex["scanner"]["error_count"],
    "elapsed_ms": lex["elapsed_ms"]
  }
}

# ---- Token Dispatch ----

fn lex_next_token(lex: any) -> any {
  s = lex["scanner"]
  ch = scanner_peek(s)

  # Number literals
  if is_digit(ch) {
    return lex_number(lex)
  }

  # Identifiers and keywords
  if is_alpha(ch) {
    return lex_identifier_or_keyword(lex)
  }

  # String literals
  if ch == "\"" {
    # Check for multi-line string
    if scanner_peek_next(s) == "\"" and scanner_peek_at(s, 2) == "\"" {
      return lex_multiline_string(lex)
    }
    return lex_string(lex, "\"")
  }

  if ch == "'" {
    return lex_char_or_lifetime(lex)
  }

  # Operators and punctuation
  return lex_operator_or_punct(lex)
}

# ---- Number Lexing ----

fn lex_number(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  num_result = scanner_scan_number(s)

  return create_token(
    num_result["type"],
    num_result["value"],
    line, col, offset
  )
}

# ---- Identifier / Keyword Lexing ----

fn lex_identifier_or_keyword(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  # Check for string prefix (f"...", r"...", b"...")
  ch = scanner_peek(s)
  next = scanner_peek_next(s)

  if ch == "f" and next == "\"" {
    return lex_interpolated_string(lex)
  }
  if ch == "r" and (next == "\"" or next == "#") {
    return lex_raw_string(lex)
  }
  if ch == "b" and next == "\"" {
    return lex_byte_string(lex)
  }

  # Regular identifier
  ident = scanner_scan_identifier_chars(s)

  # Check keyword map
  kw_type = lex["keyword_map"][ident]
  if kw_type != nil {
    return create_token(kw_type, ident, line, col, offset)
  }

  # Check if type identifier (starts with uppercase)
  if is_upper(ident[0]) {
    return create_token(TOKEN_TYPE_IDENT, ident, line, col, offset)
  }

  return create_token(TOKEN_IDENT, ident, line, col, offset)
}

# ---- String Lexing ----

fn lex_string(lex: any, quote: string) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  value = scanner_scan_string(s, quote)

  return create_token(TOKEN_STRING, value, line, col, offset)
}

fn lex_multiline_string(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  value = scanner_scan_multiline_string(s)

  return create_token(TOKEN_STRING, value, line, col, offset)
}

fn lex_raw_string(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  value = scanner_scan_raw_string(s)

  return create_token(TOKEN_STRING, value, line, col, offset)
}

fn lex_byte_string(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  scanner_advance(s)  # skip 'b'
  value = scanner_scan_string(s, "\"")

  return create_token(TOKEN_STRING, "b\"" + value + "\"", line, col, offset)
}

fn lex_interpolated_string(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  segments = scanner_scan_interpolated_string(s)

  # Encode as special string token with segments metadata
  combined = ""
  i = 0
  while i < length(segments) {
    seg = segments[i]
    if seg["type"] == "TEXT" {
      combined = combined + seg["value"]
    } else {
      combined = combined + "${" + seg["value"] + "}"
    }
    i = i + 1
  }

  token = create_token(TOKEN_STRING, combined, line, col, offset)
  token["interpolated"] = true
  token["segments"] = segments
  return token
}

# ---- Character / Lifetime Lexing ----

fn lex_char_or_lifetime(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]

  scanner_advance(s)  # skip '

  # Check for lifetime ('a, 'static, etc.)
  ch = scanner_peek(s)
  if is_alpha(ch) {
    name = scanner_scan_identifier_chars(s)
    if scanner_peek(s) != "'" {
      # It's a lifetime: 'a, 'static
      return create_token(TOKEN_IDENT, "'" + name, line, col, offset)
    }
    # It's a char: 'a'
    scanner_advance(s)  # skip closing '
    return create_token(TOKEN_CHAR, name, line, col, offset)
  }

  # Escape character: '\n'
  if ch == "\\" {
    scanner_advance(s)
    esc = scanner_advance(s)
    if scanner_peek(s) != "'" {
      scanner_add_error(s, "Unterminated character literal")
    } else {
      scanner_advance(s)
    }
    return create_token(TOKEN_CHAR, "\\" + esc, line, col, offset)
  }

  # Regular character: 'x'
  value = scanner_advance(s)
  if scanner_peek(s) != "'" {
    scanner_add_error(s, "Unterminated character literal")
  } else {
    scanner_advance(s)
  }
  return create_token(TOKEN_CHAR, value, line, col, offset)
}

# ---- Operator / Punctuation Lexing ----

fn lex_operator_or_punct(lex: any) -> any {
  s = lex["scanner"]
  line = s["line"]
  col = s["col"]
  offset = s["pos"]
  ch = scanner_advance(s)

  match ch {
    # Arithmetic
    "+" => {
      if scanner_match(s, "=") { return create_token(TOKEN_PLUS_ASSIGN, "+=", line, col, offset) }
      return create_token(TOKEN_PLUS, "+", line, col, offset)
    },
    "-" => {
      if scanner_match(s, ">") { return create_token(TOKEN_ARROW, "->", line, col, offset) }
      if scanner_match(s, "=") { return create_token(TOKEN_MINUS_ASSIGN, "-=", line, col, offset) }
      return create_token(TOKEN_MINUS, "-", line, col, offset)
    },
    "*" => {
      if scanner_match(s, "*") { return create_token(TOKEN_POWER, "**", line, col, offset) }
      if scanner_match(s, "=") { return create_token(TOKEN_STAR_ASSIGN, "*=", line, col, offset) }
      return create_token(TOKEN_STAR, "*", line, col, offset)
    },
    "/" => {
      if scanner_match(s, "=") { return create_token(TOKEN_SLASH_ASSIGN, "/=", line, col, offset) }
      return create_token(TOKEN_SLASH, "/", line, col, offset)
    },
    "%" => {
      if scanner_match(s, "=") { return create_token(TOKEN_PERCENT_ASSIGN, "%=", line, col, offset) }
      return create_token(TOKEN_PERCENT, "%", line, col, offset)
    },

    # Comparison and Assignment
    "=" => {
      if scanner_match(s, "=") { return create_token(TOKEN_EQ, "==", line, col, offset) }
      if scanner_match(s, ">") { return create_token(TOKEN_FAT_ARROW, "=>", line, col, offset) }
      return create_token(TOKEN_ASSIGN, "=", line, col, offset)
    },
    "!" => {
      if scanner_match(s, "=") { return create_token(TOKEN_NEQ, "!=", line, col, offset) }
      return create_token(TOKEN_NOT, "!", line, col, offset)
    },
    "<" => {
      if scanner_match(s, "=") { return create_token(TOKEN_LTE, "<=", line, col, offset) }
      if scanner_match(s, "<") { return create_token(TOKEN_SHL, "<<", line, col, offset) }
      return create_token(TOKEN_LT, "<", line, col, offset)
    },
    ">" => {
      if scanner_match(s, "=") { return create_token(TOKEN_GTE, ">=", line, col, offset) }
      if scanner_match(s, ">") { return create_token(TOKEN_SHR, ">>", line, col, offset) }
      return create_token(TOKEN_GT, ">", line, col, offset)
    },

    # Logical and Bitwise
    "&" => {
      if scanner_match(s, "&") { return create_token(TOKEN_AND, "&&", line, col, offset) }
      return create_token(TOKEN_BAND, "&", line, col, offset)
    },
    "|" => {
      if scanner_match(s, "|") { return create_token(TOKEN_OR, "||", line, col, offset) }
      return create_token(TOKEN_PIPE, "|", line, col, offset)
    },
    "^" => {
      return create_token(TOKEN_BXOR, "^", line, col, offset)
    },
    "~" => {
      return create_token(TOKEN_BNOT, "~", line, col, offset)
    },

    # Delimiters
    "(" => {
      lex["paren_depth"] = lex["paren_depth"] + 1
      return create_token(TOKEN_LPAREN, "(", line, col, offset)
    },
    ")" => {
      lex["paren_depth"] = lex["paren_depth"] - 1
      return create_token(TOKEN_RPAREN, ")", line, col, offset)
    },
    "{" => {
      lex["brace_depth"] = lex["brace_depth"] + 1
      return create_token(TOKEN_LBRACE, "{", line, col, offset)
    },
    "}" => {
      lex["brace_depth"] = lex["brace_depth"] - 1
      return create_token(TOKEN_RBRACE, "}", line, col, offset)
    },
    "[" => {
      lex["bracket_depth"] = lex["bracket_depth"] + 1
      return create_token(TOKEN_LBRACKET, "[", line, col, offset)
    },
    "]" => {
      lex["bracket_depth"] = lex["bracket_depth"] - 1
      return create_token(TOKEN_RBRACKET, "]", line, col, offset)
    },

    # Punctuation
    "," => { return create_token(TOKEN_COMMA, ",", line, col, offset) },
    "." => {
      if scanner_match(s, ".") {
        if scanner_match(s, ".") {
          return create_token(TOKEN_DOTDOTDOT, "...", line, col, offset)
        }
        return create_token(TOKEN_DOTDOT, "..", line, col, offset)
      }
      return create_token(TOKEN_DOT, ".", line, col, offset)
    },
    ":" => {
      if scanner_match(s, ":") { return create_token(TOKEN_COLONCOLON, "::", line, col, offset) }
      return create_token(TOKEN_COLON, ":", line, col, offset)
    },
    ";" => { return create_token(TOKEN_SEMICOLON, ";", line, col, offset) },
    "#" => { return create_token(TOKEN_HASH, "#", line, col, offset) },
    "@" => { return create_token(TOKEN_AT, "@", line, col, offset) },
    "?" => { return create_token(TOKEN_QUESTION, "?", line, col, offset) },
    "_" => {
      # Could be wildcard or start of identifier
      if is_alphanumeric(scanner_peek(s)) {
        ident = "_" + scanner_scan_identifier_chars(s)
        return create_token(TOKEN_IDENT, ident, line, col, offset)
      }
      return create_token(TOKEN_UNDERSCORE, "_", line, col, offset)
    },
    "\n" => {
      return create_token(TOKEN_NEWLINE, "\\n", line, col, offset)
    },

    # Unknown character
    _ => {
      scanner_add_error(s, "Unexpected character: '" + ch + "'")
      return create_token(TOKEN_ERROR, ch, line, col, offset)
    }
  }
}

# ---- Lexer Utilities ----

fn lex_count_tokens_by_type(result: any, token_type: string) -> i32 {
  count = 0
  i = 0
  while i < length(result["tokens"]) {
    if result["tokens"][i]["type"] == token_type {
      count = count + 1
    }
    i = i + 1
  }
  return count
}

fn lex_get_token_at(result: any, index: i32) -> any {
  if index < 0 or index >= length(result["tokens"]) {
    return nil
  }
  return result["tokens"][index]
}

fn lex_filter_tokens(result: any, include_newlines: bool) -> array {
  filtered = []
  i = 0
  while i < length(result["tokens"]) {
    token = result["tokens"][i]
    if token["type"] != TOKEN_NEWLINE or include_newlines {
      if token["type"] != TOKEN_ERROR {
        push(filtered, token)
      }
    }
    i = i + 1
  }
  return filtered
}

fn lex_pretty_print(result: any) -> string {
  output = ""
  i = 0
  while i < length(result["tokens"]) {
    t = result["tokens"][i]
    output = output + "[" + t["type"] + " '" + t["value"] + "' L" + to_string(t["line"]) + ":" + to_string(t["col"]) + "]\n"
    i = i + 1
  }
  return output
}

# ---- Performance Metrics ----

fn lex_performance_report(result: any) -> any {
  return {
    "token_count": result["token_count"],
    "error_count": result["error_count"],
    "elapsed_ms": result["elapsed_ms"],
    "tokens_per_ms": result["token_count"] / max(result["elapsed_ms"], 1),
    "has_errors": result["error_count"] > 0,
    "r1_pass": result["elapsed_ms"] < 50  # R1: < 50ms for 1000 tokens
  }
}

