# ---- AST Node Kind Constants ----

# Program
AST_PROGRAM          = "Program"
AST_MODULE           = "Module"

# Declarations
AST_FN_DECL          = "FnDecl"
AST_LET_DECL         = "LetDecl"
AST_CONST_DECL       = "ConstDecl"
AST_STRUCT_DECL      = "StructDecl"
AST_ENUM_DECL        = "EnumDecl"
AST_TRAIT_DECL       = "TraitDecl"
AST_IMPL_DECL        = "ImplDecl"
AST_TYPE_ALIAS       = "TypeAlias"
AST_USE_DECL         = "UseDecl"
AST_MOD_DECL         = "ModDecl"

# Statements
AST_EXPR_STMT        = "ExprStmt"
AST_RETURN_STMT      = "ReturnStmt"
AST_BREAK_STMT       = "BreakStmt"
AST_CONTINUE_STMT    = "ContinueStmt"
AST_ASSIGNMENT       = "Assignment"
AST_COMPOUND_ASSIGN  = "CompoundAssign"

# Expressions
AST_LITERAL          = "Literal"
AST_IDENT            = "Ident"
AST_BINARY           = "Binary"
AST_UNARY            = "Unary"
AST_CALL             = "Call"
AST_METHOD_CALL      = "MethodCall"
AST_FIELD_ACCESS     = "FieldAccess"
AST_INDEX            = "Index"
AST_ARRAY_LITERAL    = "ArrayLiteral"
AST_DICT_LITERAL     = "DictLiteral"
AST_STRUCT_LITERAL   = "StructLiteral"
AST_TUPLE_LITERAL    = "TupleLiteral"
AST_RANGE            = "Range"
AST_CLOSURE          = "Closure"
AST_IF_EXPR          = "IfExpr"
AST_MATCH_EXPR       = "MatchExpr"
AST_BLOCK            = "Block"
AST_WHILE_EXPR       = "WhileExpr"
AST_FOR_EXPR         = "ForExpr"
AST_LOOP_EXPR        = "LoopExpr"
AST_ASYNC_EXPR       = "AsyncExpr"
