AST_TRY_EXPR         = "TryExpr"
AST_CAST_EXPR        = "CastExpr"
AST_INTERPOLATION    = "Interpolation"
AST_PIPE_EXPR        = "PipeExpr"

# Type expressions
AST_TYPE_NAMED       = "TypeNamed"
AST_TYPE_GENERIC     = "TypeGeneric"
AST_TYPE_ARRAY       = "TypeArray"
AST_TYPE_TUPLE       = "TypeTuple"
AST_TYPE_FN          = "TypeFn"
AST_TYPE_REF         = "TypeRef"
