AST_PAT_REST         = "PatRest"
AST_PAT_RANGE        = "PatRange"
AST_PAT_OR           = "PatOr"
AST_PAT_GUARD        = "PatGuard"

# ---- AST Node Constructors ----

fn ast_node(kind: string, span: any) -> any {
  return {
    "kind": kind,
    "span": span,
    "type_info": nil,
    "id": 0
  }
}

fn ast_span(line: i32, col: i32, offset: i32, end_offset: i32) -> any {
  return {
    "line": line,
    "col": col,
    "offset": offset,
    "end_offset": end_offset
  }
}

fn ast_span_from_token(token: any) -> any {
  return ast_span(token["line"], token["col"], token["offset"], token["offset"] + token["length"])
}

# ---- Program ----

fn ast_program(declarations: array, span: any) -> any {
  node = ast_node(AST_PROGRAM, span)
  node["declarations"] = declarations
  return node
}

fn ast_module(name: string, declarations: array, span: any) -> any {
  node = ast_node(AST_MODULE, span)
  node["name"] = name
  node["declarations"] = declarations
  node["is_pub"] = false
  return node
}

# ---- Declarations ----

fn ast_fn_decl(name: string, params: array, return_type: any, body: any, span: any) -> any {
  node = ast_node(AST_FN_DECL, span)
  node["name"] = name
  node["params"] = params
  node["return_type"] = return_type
  node["body"] = body
  node["is_pub"] = false
  node["is_async"] = false
  node["is_unsafe"] = false
  node["generic_params"] = []
  node["where_clause"] = nil
  return node
}

fn ast_param(name: string, type_ann: any, is_mut: bool, default_val: any) -> any {
  return {
    "name": name,
    "type_ann": type_ann,
    "is_mut": is_mut,
    "default_val": default_val,
    "is_variadic": false
  }
}

fn ast_let_decl(name: string, type_ann: any, value: any, is_mut: bool, span: any) -> any {
  node = ast_node(AST_LET_DECL, span)
  node["name"] = name
  node["type_ann"] = type_ann
  node["value"] = value
  node["is_mut"] = is_mut
  node["is_pub"] = false
  return node
}

fn ast_const_decl(name: string, type_ann: any, value: any, span: any) -> any {
  node = ast_node(AST_CONST_DECL, span)
  node["name"] = name
  node["type_ann"] = type_ann
  node["value"] = value
  node["is_pub"] = false
  return node
}

fn ast_struct_decl(name: string, fields: array, span: any) -> any {
  node = ast_node(AST_STRUCT_DECL, span)
  node["name"] = name
  node["fields"] = fields
  node["is_pub"] = false
  node["generic_params"] = []
  node["where_clause"] = nil
  return node
}

fn ast_struct_field(name: string, type_ann: any, is_pub: bool, default_val: any) -> any {
  return {
    "name": name,
    "type_ann": type_ann,
    "is_pub": is_pub,
    "default_val": default_val
  }
}

fn ast_enum_decl(name: string, variants: array, span: any) -> any {
  node = ast_node(AST_ENUM_DECL, span)
  node["name"] = name
  node["variants"] = variants
  node["is_pub"] = false
  node["generic_params"] = []
  return node
}

fn ast_enum_variant(name: string, fields: array, discriminant: any) -> any {
  return {
    "name": name,
    "fields": fields,
    "discriminant": discriminant,
    "kind": "tuple"  # "tuple", "struct", or "unit"
  }
}

fn ast_trait_decl(name: string, methods: array, span: any) -> any {
  node = ast_node(AST_TRAIT_DECL, span)
  node["name"] = name
  node["methods"] = methods
  node["is_pub"] = false
  node["generic_params"] = []
  node["super_traits"] = []
  return node
}

fn ast_impl_decl(type_name: string, trait_name: any, methods: array, span: any) -> any {
  node = ast_node(AST_IMPL_DECL, span)
  node["type_name"] = type_name
  node["trait_name"] = trait_name
  node["methods"] = methods
  node["generic_params"] = []
  node["where_clause"] = nil
  return node
}

fn ast_type_alias(name: string, type_expr: any, span: any) -> any {
  node = ast_node(AST_TYPE_ALIAS, span)
  node["name"] = name
  node["type_expr"] = type_expr
  node["is_pub"] = false
  node["generic_params"] = []
  return node
}

fn ast_use_decl(path: array, alias: any, span: any) -> any {
  node = ast_node(AST_USE_DECL, span)
  node["path"] = path
  node["alias"] = alias
  node["is_glob"] = false
  node["is_pub"] = false
  return node
}

# ---- Statements ----

fn ast_expr_stmt(expr: any, span: any) -> any {
  node = ast_node(AST_EXPR_STMT, span)
  node["expr"] = expr
  return node
}

fn ast_return_stmt(value: any, span: any) -> any {
  node = ast_node(AST_RETURN_STMT, span)
  node["value"] = value
  return node
}

fn ast_break_stmt(label: any, value: any, span: any) -> any {
  node = ast_node(AST_BREAK_STMT, span)
  node["label"] = label
  node["value"] = value
  return node
}

fn ast_continue_stmt(label: any, span: any) -> any {
  node = ast_node(AST_CONTINUE_STMT, span)
  node["label"] = label
  return node
}

fn ast_assignment(target: any, value: any, span: any) -> any {
  node = ast_node(AST_ASSIGNMENT, span)
  node["target"] = target
  node["value"] = value
  return node
}

fn ast_compound_assign(target: any, op: string, value: any, span: any) -> any {
  node = ast_node(AST_COMPOUND_ASSIGN, span)
  node["target"] = target
  node["op"] = op
  node["value"] = value
  return node
}

# ---- Expressions ----

fn ast_literal(value: any, lit_type: string, span: any) -> any {
  node = ast_node(AST_LITERAL, span)
  node["value"] = value
  node["lit_type"] = lit_type  # "integer", "float", "string", "char", "bool", "nil"
  return node
}

fn ast_ident(name: string, span: any) -> any {
  node = ast_node(AST_IDENT, span)
  node["name"] = name
  return node
}

fn ast_binary(left: any, op: string, right: any, span: any) -> any {
  node = ast_node(AST_BINARY, span)
  node["left"] = left
  node["op"] = op
  node["right"] = right
  return node
}

fn ast_unary(op: string, operand: any, is_prefix: bool, span: any) -> any {
  node = ast_node(AST_UNARY, span)
  node["op"] = op
  node["operand"] = operand
  node["is_prefix"] = is_prefix
  return node
}

fn ast_call(callee: any, args: array, span: any) -> any {
  node = ast_node(AST_CALL, span)
  node["callee"] = callee
  node["args"] = args
