# ---- AST Utilities ----

fn ast_node_count(node: any) -> i32 {
  if node == nil {
    return 0
  }
  count = 1

  kind = node["kind"]

  if kind == AST_PROGRAM or kind == AST_MODULE {
    i = 0
    while i < length(node["declarations"]) {
      count = count + ast_node_count(node["declarations"][i])
      i = i + 1
    }
  } else if kind == AST_BLOCK {
    i = 0
    while i < length(node["statements"]) {
      count = count + ast_node_count(node["statements"][i])
      i = i + 1
    }
  } else if kind == AST_FN_DECL {
    count = count + ast_node_count(node["body"])
  } else if kind == AST_BINARY {
    count = count + ast_node_count(node["left"]) + ast_node_count(node["right"])
  } else if kind == AST_UNARY {
    count = count + ast_node_count(node["operand"])
  } else if kind == AST_CALL {
    count = count + ast_node_count(node["callee"])
    i = 0
    while i < length(node["args"]) {
      count = count + ast_node_count(node["args"][i])
      i = i + 1
    }
  } else if kind == AST_IF_EXPR {
    count = count + ast_node_count(node["condition"])
    count = count + ast_node_count(node["then_block"])
    count = count + ast_node_count(node["else_block"])
  } else if kind == AST_WHILE_EXPR {
    count = count + ast_node_count(node["condition"])
    count = count + ast_node_count(node["body"])
  } else if kind == AST_FOR_EXPR {
    count = count + ast_node_count(node["iterable"])
    count = count + ast_node_count(node["body"])
  } else if kind == AST_MATCH_EXPR {
    count = count + ast_node_count(node["subject"])
    i = 0
    while i < length(node["arms"]) {
      count = count + ast_node_count(node["arms"][i]["body"])
      i = i + 1
    }
  } else if kind == AST_RETURN_STMT {
    count = count + ast_node_count(node["value"])
  } else if kind == AST_LET_DECL {
    count = count + ast_node_count(node["value"])
  } else if kind == AST_ASSIGNMENT {
    count = count + ast_node_count(node["target"])
    count = count + ast_node_count(node["value"])
  }

  return count
}

fn ast_depth(node: any) -> i32 {
  if node == nil {
    return 0
  }

  max_child_depth = 0
  kind = node["kind"]

  if kind == AST_BINARY {
    left_d = ast_depth(node["left"])
    right_d = ast_depth(node["right"])
    if left_d > right_d {
      max_child_depth = left_d
    } else {
      max_child_depth = right_d
    }
  } else if kind == AST_BLOCK {
    i = 0
    while i < length(node["statements"]) {
      d = ast_depth(node["statements"][i])
      if d > max_child_depth {
        max_child_depth = d
      }
      i = i + 1
    }
  } else if kind == AST_FN_DECL {
    max_child_depth = ast_depth(node["body"])
  } else if kind == AST_IF_EXPR {
    d1 = ast_depth(node["then_block"])
    d2 = ast_depth(node["else_block"])
    if d1 > d2 {
      max_child_depth = d1
    } else {
      max_child_depth = d2
    }
  }

  return 1 + max_child_depth
}

# ================================================================
# FreeLang v4 Core - Recursive Descent Parser
# with Pratt precedence climbing for expressions
# Performance target: R2 > 99% accuracy on complex AST
# ================================================================

# ---- Operator Precedence Table ----

PREC_NONE       = 0
PREC_ASSIGNMENT = 1   # =, +=, -=, *=, /=
PREC_PIPE       = 2   # |>
PREC_OR         = 3   # ||
PREC_AND        = 4   # &&
PREC_BIT_OR     = 5   # |
PREC_BIT_XOR    = 6   # ^
PREC_BIT_AND    = 7   # &
PREC_EQUALITY   = 8   # ==, !=
PREC_COMPARISON = 9   # <, >, <=, >=
PREC_SHIFT      = 10  # <<, >>
PREC_RANGE      = 11  # .., ..=
PREC_TERM       = 12  # +, -
PREC_FACTOR     = 13  # *, /, %
PREC_UNARY      = 14  # !, -, ~
PREC_POWER      = 15  # **
PREC_POSTFIX    = 16  # (), [], ., ::, ?, as, await
PREC_PRIMARY    = 17

# ---- Parser State ----

fn create_parser(tokens: array) -> any {
  return {
    "tokens": tokens,
    "pos": 0,
    "token_count": length(tokens),
    "errors": [],
    "error_count": 0,
    "ast_node_counter": 0,
    "max_errors": 50,
    "panic_mode": false,
    "start_time": 0,
    "elapsed_ms": 0
  }
}

# ---- Token Access ----

fn parser_peek(p: any) -> any {
  if p["pos"] >= p["token_count"] {
    return { "type": TOKEN_EOF, "value": "", "line": 0, "col": 0, "offset": 0 }
  }
  return p["tokens"][p["pos"]]
}

fn parser_peek_next(p: any) -> any {
  next_pos = p["pos"] + 1
  if next_pos >= p["token_count"] {
    return { "type": TOKEN_EOF, "value": "", "line": 0, "col": 0, "offset": 0 }
  }
  return p["tokens"][next_pos]
}

fn parser_advance(p: any) -> any {
  token = parser_peek(p)
  if token["type"] != TOKEN_EOF {
    p["pos"] = p["pos"] + 1
  }
  return token
}

fn parser_check(p: any, token_type: string) -> bool {
  return parser_peek(p)["type"] == token_type
}

fn parser_match(p: any, token_type: string) -> bool {
  if parser_check(p, token_type) {
    parser_advance(p)
    return true
  }
  return false
}

fn parser_expect(p: any, token_type: string) -> any {
  if parser_check(p, token_type) {
    return parser_advance(p)
  }
  token = parser_peek(p)
  parser_error(p, "Expected " + token_type_name(token_type) + ", got " + token_type_name(token["type"]) + " '" + token["value"] + "'")
  return token
}

fn parser_at_end(p: any) -> bool {
  return parser_peek(p)["type"] == TOKEN_EOF
}

# ---- Error Handling ----

fn parser_error(p: any, message: string) -> any {
  if p["panic_mode"] {
    return p
  }
  token = parser_peek(p)
  err = {
    "message": message,
    "line": token["line"],
    "col": token["col"],
    "token": token
  }
  push(p["errors"], err)
  p["error_count"] = p["error_count"] + 1

  if p["error_count"] >= p["max_errors"] {
    p["panic_mode"] = true
  }
  return p
}

fn parser_synchronize(p: any) -> any {
  # Error recovery: skip to next statement boundary
  p["panic_mode"] = false

  while not parser_at_end(p) {
    tt = parser_peek(p)["type"]
    if tt == TOKEN_FN or tt == TOKEN_LET or tt == TOKEN_CONST or
       tt == TOKEN_STRUCT or tt == TOKEN_ENUM or tt == TOKEN_TRAIT or
       tt == TOKEN_IMPL or tt == TOKEN_IF or tt == TOKEN_WHILE or
       tt == TOKEN_FOR or tt == TOKEN_RETURN or tt == TOKEN_MOD or
       tt == TOKEN_USE or tt == TOKEN_PUB {
      return p
    }
    parser_advance(p)
  }
  return p
}

# ---- Next AST ID ----

fn parser_next_id(p: any) -> i32 {
  p["ast_node_counter"] = p["ast_node_counter"] + 1
  return p["ast_node_counter"]
}

# ---- Skip Newlines ----

fn parser_skip_newlines(p: any) -> any {
  while parser_check(p, TOKEN_NEWLINE) {
    parser_advance(p)
  }
  return p
}

# ================================================================
# Top-Level Parsing
# ================================================================

fn parse(tokens: array) -> any {
  p = create_parser(tokens)
  p["start_time"] = time_now()

  declarations = []

  parser_skip_newlines(p)

  while not parser_at_end(p) {
    if p["panic_mode"] {
      parser_synchronize(p)
      if parser_at_end(p) {
        break
      }
    }

    decl = parse_declaration(p)
    if decl != nil {
      decl["id"] = parser_next_id(p)
      push(declarations, decl)
    }
    parser_skip_newlines(p)
  }

  span = ast_span(1, 1, 0, parser_peek(p)["offset"])
  program = ast_program(declarations, span)

  p["elapsed_ms"] = time_now() - p["start_time"]

  return {
    "ast": program,
    "errors": p["errors"],
    "error_count": p["error_count"],
    "node_count": p["ast_node_counter"],
    "elapsed_ms": p["elapsed_ms"]
  }
}

# ---- Declaration Parsing ----

fn parse_declaration(p: any) -> any {
  parser_skip_newlines(p)

  # Check for pub modifier
  is_pub = false
  if parser_check(p, TOKEN_PUB) {
    is_pub = true
    parser_advance(p)
    parser_skip_newlines(p)
  }

  tt = parser_peek(p)["type"]

  match tt {
    TOKEN_FN     => { decl = parse_fn_decl(p); if decl != nil { decl["is_pub"] = is_pub }; return decl },
    TOKEN_LET    => { return parse_let_decl(p) },
    TOKEN_CONST  => { return parse_const_decl(p) },
    TOKEN_STRUCT => { decl = parse_struct_decl(p); if decl != nil { decl["is_pub"] = is_pub }; return decl },
    TOKEN_ENUM   => { decl = parse_enum_decl(p); if decl != nil { decl["is_pub"] = is_pub }; return decl },
    TOKEN_TRAIT  => { decl = parse_trait_decl(p); if decl != nil { decl["is_pub"] = is_pub }; return decl },
    TOKEN_IMPL   => { return parse_impl_decl(p) },
    TOKEN_TYPE   => { decl = parse_type_alias(p); if decl != nil { decl["is_pub"] = is_pub }; return decl },
    TOKEN_USE    => { return parse_use_decl(p) },
    TOKEN_MOD    => { return parse_mod_decl(p) },
    TOKEN_ASYNC  => { return parse_async_fn_decl(p) },
    TOKEN_UNSAFE => { return parse_unsafe_fn_decl(p) },
    _ => { return parse_statement(p) }
  }
}

# ---- Function Declaration ----

fn parse_fn_decl(p: any) -> any {
  token = parser_expect(p, TOKEN_FN)
  span = ast_span_from_token(token)

  name_token = parser_expect(p, TOKEN_IDENT)
  name = name_token["value"]

  # Optional generic parameters <T, U>
  generic_params = []
  if parser_check(p, TOKEN_LT) {
    generic_params = parse_generic_params(p)
  }

  # Parameters
  parser_expect(p, TOKEN_LPAREN)
  params = parse_fn_params(p)
  parser_expect(p, TOKEN_RPAREN)

  # Optional return type
  return_type = nil
  if parser_match(p, TOKEN_ARROW) {
    return_type = parse_type(p)
  }

  # Optional where clause
  where_clause = nil
  if parser_check(p, TOKEN_WHERE) {
    where_clause = parse_where_clause(p)
  }

  # Body
  body = parse_block(p)

  fn_node = ast_fn_decl(name, params, return_type, body, span)
  fn_node["generic_params"] = generic_params
  fn_node["where_clause"] = where_clause
  return fn_node
}

fn parse_fn_params(p: any) -> array {
  params = []
  parser_skip_newlines(p)

  if parser_check(p, TOKEN_RPAREN) {
    return params
  }

  # First param
  push(params, parse_fn_param(p))

  while parser_match(p, TOKEN_COMMA) {
    parser_skip_newlines(p)
    if parser_check(p, TOKEN_RPAREN) {
      break  # trailing comma
    }
    push(params, parse_fn_param(p))
  }

  return params
}

fn parse_fn_param(p: any) -> any {
  parser_skip_newlines(p)

  # Check for self
  if parser_check(p, TOKEN_SELF) {
    parser_advance(p)
    return ast_param("self", nil, false, nil)
  }

  # Check for &self or &mut self
  if parser_check(p, TOKEN_BAND) {
    parser_advance(p)
    is_mut = parser_match(p, TOKEN_MUT)
    if parser_check(p, TOKEN_SELF) {
      parser_advance(p)
      param = ast_param("self", nil, is_mut, nil)
      param["is_ref"] = true
      return param
    }
  }

  # Check for mut
  is_mut = parser_match(p, TOKEN_MUT)

  # Variadic: ...args
  is_variadic = false
  if parser_check(p, TOKEN_DOTDOTDOT) {
    parser_advance(p)
    is_variadic = true
  }

  name = parser_expect(p, TOKEN_IDENT)["value"]

  # Optional type annotation
  type_ann = nil
  if parser_match(p, TOKEN_COLON) {
    type_ann = parse_type(p)
  }

  # Optional default value
  default_val = nil
  if parser_match(p, TOKEN_ASSIGN) {
    default_val = parse_expression(p, PREC_ASSIGNMENT)
  }

  param = ast_param(name, type_ann, is_mut, default_val)
  param["is_variadic"] = is_variadic
  return param
}

fn parse_async_fn_decl(p: any) -> any {
  parser_advance(p)  # skip async
  fn_node = parse_fn_decl(p)
  fn_node["is_async"] = true
  return fn_node
}

fn parse_unsafe_fn_decl(p: any) -> any {
  parser_advance(p)  # skip unsafe
  fn_node = parse_fn_decl(p)
  fn_node["is_unsafe"] = true
  return fn_node
}

# ---- Let / Const Declaration ----

fn parse_let_decl(p: any) -> any {
  token = parser_advance(p)  # skip let
  span = ast_span_from_token(token)

  is_mut = parser_match(p, TOKEN_MUT)

  name = parser_expect(p, TOKEN_IDENT)["value"]

  # Optional type annotation
  type_ann = nil
  if parser_match(p, TOKEN_COLON) {
    type_ann = parse_type(p)
  }

  # Initializer
  value = nil
  if parser_match(p, TOKEN_ASSIGN) {
    value = parse_expression(p, PREC_ASSIGNMENT)
  }

  return ast_let_decl(name, type_ann, value, is_mut, span)
}

fn parse_const_decl(p: any) -> any {
  token = parser_advance(p)  # skip const
  span = ast_span_from_token(token)

  name = parser_expect(p, TOKEN_IDENT)["value"]

  type_ann = nil
  if parser_match(p, TOKEN_COLON) {
    type_ann = parse_type(p)
  }

  parser_expect(p, TOKEN_ASSIGN)
  value = parse_expression(p, PREC_ASSIGNMENT)

  return ast_const_decl(name, type_ann, value, span)
}

# ---- Struct Declaration ----

fn parse_struct_decl(p: any) -> any {
  token = parser_advance(p)  # skip struct
  span = ast_span_from_token(token)

  name = parser_expect(p, TOKEN_TYPE_IDENT)["value"]

  # If not type ident, try regular ident
  if name == nil or name == "" {
    name = parser_peek(p)["value"]
    parser_advance(p)
  }

  generic_params = []
  if parser_check(p, TOKEN_LT) {
    generic_params = parse_generic_params(p)
  }

  parser_expect(p, TOKEN_LBRACE)
  fields = []

  parser_skip_newlines(p)
  while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
    is_pub = parser_match(p, TOKEN_PUB)

    field_name = parser_expect(p, TOKEN_IDENT)["value"]
    parser_expect(p, TOKEN_COLON)
    field_type = parse_type(p)

    default_val = nil
    if parser_match(p, TOKEN_ASSIGN) {
      default_val = parse_expression(p, PREC_ASSIGNMENT)
    }

    push(fields, ast_struct_field(field_name, field_type, is_pub, default_val))
    parser_match(p, TOKEN_COMMA)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACE)

  struct_node = ast_struct_decl(name, fields, span)
  struct_node["generic_params"] = generic_params
  return struct_node
}

# ---- Enum Declaration ----

fn parse_enum_decl(p: any) -> any {
  token = parser_advance(p)  # skip enum
  span = ast_span_from_token(token)

  name = parser_expect(p, TOKEN_TYPE_IDENT)["value"]
  if name == nil or name == "" {
    name = parser_peek(p)["value"]
    parser_advance(p)
  }

  generic_params = []
  if parser_check(p, TOKEN_LT) {
    generic_params = parse_generic_params(p)
  }

  parser_expect(p, TOKEN_LBRACE)
  variants = []

  parser_skip_newlines(p)
  while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
    variant_name = parser_advance(p)["value"]

    variant_fields = []
    variant_kind = "unit"

    if parser_check(p, TOKEN_LPAREN) {
      # Tuple variant: Variant(Type1, Type2)
      parser_advance(p)
      variant_kind = "tuple"
      while not parser_check(p, TOKEN_RPAREN) and not parser_at_end(p) {
        push(variant_fields, parse_type(p))
        parser_match(p, TOKEN_COMMA)
      }
      parser_expect(p, TOKEN_RPAREN)
    } else if parser_check(p, TOKEN_LBRACE) {
      # Struct variant: Variant { field: Type }
      parser_advance(p)
      variant_kind = "struct"
      parser_skip_newlines(p)
      while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
        f_name = parser_expect(p, TOKEN_IDENT)["value"]
        parser_expect(p, TOKEN_COLON)
        f_type = parse_type(p)
        push(variant_fields, { "name": f_name, "type": f_type })
        parser_match(p, TOKEN_COMMA)
        parser_skip_newlines(p)
      }
      parser_expect(p, TOKEN_RBRACE)
    }

    # Optional discriminant
    discriminant = nil
    if parser_match(p, TOKEN_ASSIGN) {
      discriminant = parse_expression(p, PREC_ASSIGNMENT)
    }

    variant = ast_enum_variant(variant_name, variant_fields, discriminant)
    variant["kind"] = variant_kind
    push(variants, variant)

    parser_match(p, TOKEN_COMMA)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACE)

  enum_node = ast_enum_decl(name, variants, span)
  enum_node["generic_params"] = generic_params
  return enum_node
}

# ---- Trait Declaration ----

fn parse_trait_decl(p: any) -> any {
  token = parser_advance(p)  # skip trait
  span = ast_span_from_token(token)

  name = parser_advance(p)["value"]

  generic_params = []
  if parser_check(p, TOKEN_LT) {
    generic_params = parse_generic_params(p)
  }

  # Super traits
  super_traits = []
  if parser_match(p, TOKEN_COLON) {
    push(super_traits, parser_advance(p)["value"])
    while parser_match(p, TOKEN_PLUS) {
      push(super_traits, parser_advance(p)["value"])
    }
  }

  parser_expect(p, TOKEN_LBRACE)
  methods = []

  parser_skip_newlines(p)
  while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
    method = parse_fn_decl(p)
    push(methods, method)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACE)

  trait_node = ast_trait_decl(name, methods, span)
  trait_node["generic_params"] = generic_params
  trait_node["super_traits"] = super_traits
  return trait_node
}

# ---- Impl Declaration ----

fn parse_impl_decl(p: any) -> any {
  token = parser_advance(p)  # skip impl
  span = ast_span_from_token(token)

  generic_params = []
  if parser_check(p, TOKEN_LT) {
    generic_params = parse_generic_params(p)
  }

  type_name = parser_advance(p)["value"]

  # Check for trait impl: impl Trait for Type
  trait_name = nil
  if parser_match(p, TOKEN_FOR) {
    trait_name = type_name
    type_name = parser_advance(p)["value"]
  }

  parser_expect(p, TOKEN_LBRACE)
  methods = []

  parser_skip_newlines(p)
  while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
    is_pub = parser_match(p, TOKEN_PUB)
    method = parse_fn_decl(p)
    if method != nil {
      method["is_pub"] = is_pub
    }
    push(methods, method)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACE)

  impl_node = ast_impl_decl(type_name, trait_name, methods, span)
  impl_node["generic_params"] = generic_params
  return impl_node
}

# ---- Type Alias ----

fn parse_type_alias(p: any) -> any {
  token = parser_advance(p)  # skip type
  span = ast_span_from_token(token)

  name = parser_advance(p)["value"]

  generic_params = []
  if parser_check(p, TOKEN_LT) {
    generic_params = parse_generic_params(p)
  }

  parser_expect(p, TOKEN_ASSIGN)
  type_expr = parse_type(p)

  alias = ast_type_alias(name, type_expr, span)
  alias["generic_params"] = generic_params
  return alias
}

# ---- Use / Mod Declaration ----

fn parse_use_decl(p: any) -> any {
  token = parser_advance(p)  # skip use
  span = ast_span_from_token(token)

  path = []
  push(path, parser_advance(p)["value"])

  while parser_match(p, TOKEN_COLONCOLON) {
    if parser_check(p, TOKEN_STAR) {
      parser_advance(p)
      use_node = ast_use_decl(path, nil, span)
      use_node["is_glob"] = true
      return use_node
    }
    push(path, parser_advance(p)["value"])
  }

  alias = nil
  if parser_match(p, TOKEN_AS) {
    alias = parser_advance(p)["value"]
  }

  return ast_use_decl(path, alias, span)
}

fn parse_mod_decl(p: any) -> any {
  token = parser_advance(p)  # skip mod
  span = ast_span_from_token(token)

  name = parser_advance(p)["value"]

  declarations = []
  if parser_check(p, TOKEN_LBRACE) {
    parser_advance(p)
    parser_skip_newlines(p)
    while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
      decl = parse_declaration(p)
      if decl != nil {
        push(declarations, decl)
      }
      parser_skip_newlines(p)
    }
    parser_expect(p, TOKEN_RBRACE)
  }

  return ast_module(name, declarations, span)
}

# ---- Generic Parameters ----

fn parse_generic_params(p: any) -> array {
  parser_expect(p, TOKEN_LT)
  params = []

  while not parser_check(p, TOKEN_GT) and not parser_at_end(p) {
    name = parser_advance(p)["value"]
    bounds = []

    if parser_match(p, TOKEN_COLON) {
      push(bounds, parser_advance(p)["value"])
      while parser_match(p, TOKEN_PLUS) {
        push(bounds, parser_advance(p)["value"])
      }
    }

    push(params, { "name": name, "bounds": bounds })
    parser_match(p, TOKEN_COMMA)
  }

  parser_expect(p, TOKEN_GT)
  return params
}

fn parse_where_clause(p: any) -> array {
  parser_advance(p)  # skip where
  constraints = []

  type_name = parser_advance(p)["value"]
  parser_expect(p, TOKEN_COLON)
  bounds = [parser_advance(p)["value"]]
  while parser_match(p, TOKEN_PLUS) {
    push(bounds, parser_advance(p)["value"])
  }
  push(constraints, { "type": type_name, "bounds": bounds })

  while parser_match(p, TOKEN_COMMA) {
    parser_skip_newlines(p)
    if parser_check(p, TOKEN_LBRACE) {
      break
    }
    type_name = parser_advance(p)["value"]
    parser_expect(p, TOKEN_COLON)
    bounds = [parser_advance(p)["value"]]
    while parser_match(p, TOKEN_PLUS) {
      push(bounds, parser_advance(p)["value"])
    }
    push(constraints, { "type": type_name, "bounds": bounds })
  }

  return constraints
}

# ================================================================
# Statement Parsing
# ================================================================

fn parse_statement(p: any) -> any {
  parser_skip_newlines(p)
  tt = parser_peek(p)["type"]

  match tt {
    TOKEN_RETURN   => { return parse_return_stmt(p) },
    TOKEN_BREAK    => { return parse_break_stmt(p) },
    TOKEN_CONTINUE => { return parse_continue_stmt(p) },
    TOKEN_LET      => { return parse_let_decl(p) },
    _ => {
      # Expression statement (might be assignment)
      expr = parse_expression(p, PREC_NONE)
      if expr == nil {
        parser_error(p, "Expected statement")
        parser_advance(p)
        return nil
      }

      # Check for assignment
      tt2 = parser_peek(p)["type"]
      if tt2 == TOKEN_ASSIGN {
        parser_advance(p)
        value = parse_expression(p, PREC_ASSIGNMENT)
        span = expr["span"]
        return ast_assignment(expr, value, span)
      }
      if token_is_assignment(parser_peek(p)) {
        op_token = parser_advance(p)
        value = parse_expression(p, PREC_ASSIGNMENT)
        span = expr["span"]
        return ast_compound_assign(expr, op_token["value"], value, span)
      }

      return ast_expr_stmt(expr, expr["span"])
    }
  }
}

fn parse_return_stmt(p: any) -> any {
  token = parser_advance(p)  # skip return
  span = ast_span_from_token(token)

  value = nil
  if not parser_check(p, TOKEN_RBRACE) and not parser_check(p, TOKEN_NEWLINE) and not parser_at_end(p) {
    value = parse_expression(p, PREC_ASSIGNMENT)
  }

  return ast_return_stmt(value, span)
}

fn parse_break_stmt(p: any) -> any {
  token = parser_advance(p)
  span = ast_span_from_token(token)
  label = nil
  value = nil

  # Optional label
  if parser_check(p, TOKEN_IDENT) and parser_peek(p)["value"][0] == "'" {
    label = parser_advance(p)["value"]
  }

  # Optional value
  if not parser_check(p, TOKEN_RBRACE) and not parser_check(p, TOKEN_NEWLINE) and not parser_at_end(p) {
    value = parse_expression(p, PREC_ASSIGNMENT)
  }

  return ast_break_stmt(label, value, span)
}

fn parse_continue_stmt(p: any) -> any {
  token = parser_advance(p)
  span = ast_span_from_token(token)
  label = nil

  if parser_check(p, TOKEN_IDENT) and parser_peek(p)["value"][0] == "'" {
    label = parser_advance(p)["value"]
  }

  return ast_continue_stmt(label, span)
}

# ================================================================
# Expression Parsing (Pratt Precedence Climbing)
# ================================================================

fn parse_expression(p: any, min_prec: i32) -> any {
  parser_skip_newlines(p)
  left = parse_prefix(p)

  if left == nil {
    return nil
  }

  while not parser_at_end(p) {
    parser_skip_newlines(p)
    prec = get_infix_precedence(p)
    if prec <= min_prec {
      break
    }
    left = parse_infix(p, left, prec)
  }

  return left
}

# ---- Prefix Parsing ----

fn parse_prefix(p: any) -> any {
  parser_skip_newlines(p)
  token = parser_peek(p)
  tt = token["type"]

  match tt {
    # Literals
    TOKEN_INTEGER    => { return parse_number_literal(p) },
    TOKEN_FLOAT      => { return parse_number_literal(p) },
    TOKEN_HEX        => { return parse_number_literal(p) },
    TOKEN_OCTAL      => { return parse_number_literal(p) },
    TOKEN_BINARY     => { return parse_number_literal(p) },
    TOKEN_STRING     => { return parse_string_literal(p) },
    TOKEN_CHAR       => { return parse_char_literal(p) },
    TOKEN_BOOL_TRUE  => { parser_advance(p); return ast_literal(true, "bool", ast_span_from_token(token)) },
    TOKEN_BOOL_FALSE => { parser_advance(p); return ast_literal(false, "bool", ast_span_from_token(token)) },
    TOKEN_NIL        => { parser_advance(p); return ast_literal(nil, "nil", ast_span_from_token(token)) },

    # Identifiers
    TOKEN_IDENT      => { return parse_ident_expr(p) },
    TOKEN_TYPE_IDENT => { return parse_type_ident_expr(p) },
    TOKEN_SELF       => { parser_advance(p); return ast_ident("self", ast_span_from_token(token)) },

    # Unary operators
    TOKEN_MINUS => { return parse_unary(p) },
    TOKEN_NOT   => { return parse_unary(p) },
    TOKEN_BNOT  => { return parse_unary(p) },
    TOKEN_BAND  => { return parse_ref_expr(p) },

    # Grouping and tuples
    TOKEN_LPAREN   => { return parse_paren_expr(p) },

    # Array and Dict
    TOKEN_LBRACKET => { return parse_array_literal(p) },
    TOKEN_LBRACE   => { return parse_block_or_dict(p) },

    # Control flow as expressions
    TOKEN_IF       => { return parse_if_expr(p) },
    TOKEN_MATCH    => { return parse_match_expr(p) },
    TOKEN_WHILE    => { return parse_while_expr(p) },
    TOKEN_FOR      => { return parse_for_expr(p) },
    TOKEN_LOOP     => { return parse_loop_expr(p) },

    # Async
    TOKEN_ASYNC    => { return parse_async_expr(p) },

    # Closure: |args| body
    TOKEN_PIPE     => { return parse_closure(p) },
    TOKEN_OR       => { return parse_closure_no_params(p) },

    _ => {
      return nil
    }
  }
}

# ---- Infix Parsing ----

fn get_infix_precedence(p: any) -> i32 {
  tt = parser_peek(p)["type"]

  match tt {
    TOKEN_OR        => { return PREC_OR },
    TOKEN_AND       => { return PREC_AND },
    TOKEN_BOR       => { return PREC_BIT_OR },
    TOKEN_BXOR      => { return PREC_BIT_XOR },
    TOKEN_BAND      => { return PREC_BIT_AND },
    TOKEN_EQ        => { return PREC_EQUALITY },
    TOKEN_NEQ       => { return PREC_EQUALITY },
    TOKEN_LT        => { return PREC_COMPARISON },
    TOKEN_GT        => { return PREC_COMPARISON },
    TOKEN_LTE       => { return PREC_COMPARISON },
    TOKEN_GTE       => { return PREC_COMPARISON },
    TOKEN_SHL       => { return PREC_SHIFT },
    TOKEN_SHR       => { return PREC_SHIFT },
    TOKEN_DOTDOT    => { return PREC_RANGE },
    TOKEN_DOTDOTDOT => { return PREC_RANGE },
    TOKEN_PLUS      => { return PREC_TERM },
    TOKEN_MINUS     => { return PREC_TERM },
    TOKEN_STAR      => { return PREC_FACTOR },
    TOKEN_SLASH     => { return PREC_FACTOR },
    TOKEN_PERCENT   => { return PREC_FACTOR },
    TOKEN_POWER     => { return PREC_POWER },
    TOKEN_LPAREN    => { return PREC_POSTFIX },
    TOKEN_LBRACKET  => { return PREC_POSTFIX },
    TOKEN_DOT       => { return PREC_POSTFIX },
    TOKEN_COLONCOLON => { return PREC_POSTFIX },
    TOKEN_QUESTION  => { return PREC_POSTFIX },
    TOKEN_AS        => { return PREC_POSTFIX },
    TOKEN_AWAIT     => { return PREC_POSTFIX },
    TOKEN_PIPE      => { return PREC_PIPE },
    _ => { return PREC_NONE }
  }
}

fn parse_infix(p: any, left: any, prec: i32) -> any {
  tt = parser_peek(p)["type"]

  # Binary operators
  if prec >= PREC_OR and prec <= PREC_FACTOR {
    return parse_binary(p, left, prec)
  }

  # Right-associative power
  if tt == TOKEN_POWER {
    return parse_binary_right(p, left)
  }

  # Postfix operations
  if tt == TOKEN_LPAREN {
    return parse_call(p, left)
  }
  if tt == TOKEN_LBRACKET {
    return parse_index_expr(p, left)
  }
  if tt == TOKEN_DOT {
    return parse_dot_expr(p, left)
  }
  if tt == TOKEN_COLONCOLON {
    return parse_path_expr(p, left)
  }
  if tt == TOKEN_QUESTION {
    return parse_try(p, left)
  }
  if tt == TOKEN_AS {
    return parse_cast(p, left)
  }
  if tt == TOKEN_AWAIT {
    return parse_await(p, left)
  }
  if tt == TOKEN_DOTDOT or tt == TOKEN_DOTDOTDOT {
    return parse_range(p, left)
  }

  # Pipe operator
  if tt == TOKEN_PIPE {
    return parse_pipe(p, left)
  }

  return left
}

fn parse_binary(p: any, left: any, prec: i32) -> any {
  op_token = parser_advance(p)
  op = op_token["value"]
  right = parse_expression(p, prec)
  span = left["span"]
  return ast_binary(left, op, right, span)
}

fn parse_binary_right(p: any, left: any) -> any {
  op_token = parser_advance(p)
  right = parse_expression(p, PREC_POWER - 1)  # right-associative
  span = left["span"]
  return ast_binary(left, "**", right, span)
}

# ---- Literal Parsing ----

fn parse_number_literal(p: any) -> any {
  token = parser_advance(p)
  span = ast_span_from_token(token)

  match token["type"] {
    TOKEN_INTEGER => { return ast_literal(token["value"], "integer", span) },
    TOKEN_FLOAT   => { return ast_literal(token["value"], "float", span) },
    TOKEN_HEX     => { return ast_literal(token["value"], "integer", span) },
    TOKEN_OCTAL   => { return ast_literal(token["value"], "integer", span) },
    TOKEN_BINARY  => { return ast_literal(token["value"], "integer", span) },
    _ => { return ast_literal(token["value"], "integer", span) }
  }
}

fn parse_string_literal(p: any) -> any {
  token = parser_advance(p)
  span = ast_span_from_token(token)

  if token["interpolated"] == true {
    # Build interpolation AST
    return ast_node(AST_INTERPOLATION, span)
  }

  return ast_literal(token["value"], "string", span)
}

fn parse_char_literal(p: any) -> any {
  token = parser_advance(p)
  span = ast_span_from_token(token)
  return ast_literal(token["value"], "char", span)
}

# ---- Identifier Expression ----

fn parse_ident_expr(p: any) -> any {
  token = parser_advance(p)
  span = ast_span_from_token(token)
  return ast_ident(token["value"], span)
}

fn parse_type_ident_expr(p: any) -> any {
  token = parser_advance(p)
  span = ast_span_from_token(token)

  # Check for struct literal: TypeName { field: value }
  if parser_check(p, TOKEN_LBRACE) {
    return parse_struct_literal(p, token["value"], span)
  }

  return ast_ident(token["value"], span)
}

# ---- Unary Expression ----

fn parse_unary(p: any) -> any {
  op_token = parser_advance(p)
  span = ast_span_from_token(op_token)
  operand = parse_expression(p, PREC_UNARY)
  return ast_unary(op_token["value"], operand, true, span)
}

fn parse_ref_expr(p: any) -> any {
  op_token = parser_advance(p)  # skip &
  span = ast_span_from_token(op_token)
  is_mut = parser_match(p, TOKEN_MUT)
  operand = parse_expression(p, PREC_UNARY)
  ref_node = ast_unary("&", operand, true, span)
  ref_node["is_mut"] = is_mut
  return ref_node
}

# ---- Grouping / Tuple ----

fn parse_paren_expr(p: any) -> any {
  token = parser_advance(p)  # skip (
  span = ast_span_from_token(token)

  parser_skip_newlines(p)

  # Empty tuple
  if parser_check(p, TOKEN_RPAREN) {
    parser_advance(p)
    return ast_tuple_literal([], span)
  }

  first = parse_expression(p, PREC_NONE)
  parser_skip_newlines(p)

  # Tuple: (a, b, c)
  if parser_check(p, TOKEN_COMMA) {
    elements = [first]
    while parser_match(p, TOKEN_COMMA) {
      parser_skip_newlines(p)
      if parser_check(p, TOKEN_RPAREN) {
        break
      }
      push(elements, parse_expression(p, PREC_NONE))
      parser_skip_newlines(p)
    }
    parser_expect(p, TOKEN_RPAREN)
    node = ast_node(AST_TUPLE_LITERAL, span)
    node["elements"] = elements
    return node
  }

  # Grouping: (expr)
  parser_expect(p, TOKEN_RPAREN)
  return first
}

# ---- Array Literal ----

fn parse_array_literal(p: any) -> any {
  token = parser_advance(p)  # skip [
  span = ast_span_from_token(token)

  elements = []
  parser_skip_newlines(p)

  while not parser_check(p, TOKEN_RBRACKET) and not parser_at_end(p) {
    push(elements, parse_expression(p, PREC_ASSIGNMENT))
    parser_match(p, TOKEN_COMMA)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACKET)
  return ast_array_literal(elements, span)
}

# ---- Block or Dict Literal ----

fn parse_block_or_dict(p: any) -> any {
  # Disambiguate: { key: value } dict vs { stmt; stmt } block
  # Heuristic: if first token is IDENT/STRING followed by COLON, it's a dict

  next_token = parser_peek_next(p)
  if parser_peek_next(p)["type"] == TOKEN_COLON {
    # Might be dict
    return parse_dict_literal(p)
  }

  return parse_block(p)
}

fn parse_dict_literal(p: any) -> any {
  token = parser_advance(p)  # skip {
  span = ast_span_from_token(token)

  entries = []
  parser_skip_newlines(p)

  while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
    key = parse_expression(p, PREC_ASSIGNMENT)
    parser_expect(p, TOKEN_COLON)
    value = parse_expression(p, PREC_ASSIGNMENT)
    push(entries, { "key": key, "value": value })
    parser_match(p, TOKEN_COMMA)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACE)
  return ast_dict_literal(entries, span)
}

fn parse_block(p: any) -> any {
  token = parser_expect(p, TOKEN_LBRACE)
  span = ast_span_from_token(token)

  statements = []
  parser_skip_newlines(p)

  while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
    stmt = parse_declaration(p)
    if stmt != nil {
      push(statements, stmt)
    }
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACE)
  return ast_block(statements, span)
}

# ---- Struct Literal ----

fn parse_struct_literal(p: any, name: string, span: any) -> any {
  parser_advance(p)  # skip {
  fields = []

  parser_skip_newlines(p)
  while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
    field_name = parser_expect(p, TOKEN_IDENT)["value"]

    field_value = nil
    if parser_match(p, TOKEN_COLON) {
      field_value = parse_expression(p, PREC_ASSIGNMENT)
    } else {
      # Shorthand: { name } == { name: name }
      field_value = ast_ident(field_name, span)
    }

    push(fields, { "name": field_name, "value": field_value })
    parser_match(p, TOKEN_COMMA)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACE)
  return ast_struct_literal(name, fields, span)
}

# ---- Control Flow Expressions ----

fn parse_if_expr(p: any) -> any {
  token = parser_advance(p)  # skip if
  span = ast_span_from_token(token)

  # Condition (no parentheses required)
  condition = parse_expression(p, PREC_NONE)

  then_block = parse_block(p)

  else_block = nil
  parser_skip_newlines(p)
  if parser_match(p, TOKEN_ELSE) {
    parser_skip_newlines(p)
    if parser_check(p, TOKEN_IF) {
      else_block = parse_if_expr(p)
    } else {
      else_block = parse_block(p)
    }
  }

  return ast_if_expr(condition, then_block, else_block, span)
}

fn parse_match_expr(p: any) -> any {
  token = parser_advance(p)  # skip match
  span = ast_span_from_token(token)

  subject = parse_expression(p, PREC_NONE)
  parser_expect(p, TOKEN_LBRACE)

  arms = []
  parser_skip_newlines(p)

  while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
    pattern = parse_pattern(p)

    # Optional guard
    guard = nil
    if parser_match(p, TOKEN_IF) {
      guard = parse_expression(p, PREC_NONE)
    }

    parser_expect(p, TOKEN_FAT_ARROW)

    body = nil
    if parser_check(p, TOKEN_LBRACE) {
      body = parse_block(p)
    } else {
      body = parse_expression(p, PREC_ASSIGNMENT)
    }

    push(arms, ast_match_arm(pattern, guard, body))
    parser_match(p, TOKEN_COMMA)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RBRACE)
  return ast_match_expr(subject, arms, span)
}

fn parse_while_expr(p: any) -> any {
  token = parser_advance(p)  # skip while
  span = ast_span_from_token(token)

  condition = parse_expression(p, PREC_NONE)
  body = parse_block(p)

  return ast_while_expr(condition, body, nil, span)
}

fn parse_for_expr(p: any) -> any {
  token = parser_advance(p)  # skip for
  span = ast_span_from_token(token)

  variable = parser_expect(p, TOKEN_IDENT)["value"]
  parser_expect(p, TOKEN_IN)
  iterable = parse_expression(p, PREC_NONE)
  body = parse_block(p)

  return ast_for_expr(variable, iterable, body, nil, span)
}

fn parse_loop_expr(p: any) -> any {
  token = parser_advance(p)  # skip loop
  span = ast_span_from_token(token)
  body = parse_block(p)
  return ast_loop_expr(body, nil, span)
}

fn parse_async_expr(p: any) -> any {
  token = parser_advance(p)  # skip async
  span = ast_span_from_token(token)

  if parser_check(p, TOKEN_FN) {
    # async fn declaration
    fn_node = parse_fn_decl(p)
    fn_node["is_async"] = true
    return fn_node
  }

  body = parse_block(p)
  return ast_async_expr(body, span)
}

# ---- Closure ----

fn parse_closure(p: any) -> any {
  token = parser_advance(p)  # skip |
  span = ast_span_from_token(token)

  params = []
  parser_skip_newlines(p)

  while not parser_check(p, TOKEN_PIPE) and not parser_at_end(p) {
    is_mut = parser_match(p, TOKEN_MUT)
    name = parser_expect(p, TOKEN_IDENT)["value"]

    type_ann = nil
    if parser_match(p, TOKEN_COLON) {
      type_ann = parse_type(p)
    }

    push(params, ast_param(name, type_ann, is_mut, nil))
    parser_match(p, TOKEN_COMMA)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_PIPE)

  # Optional return type
  return_type = nil
  if parser_match(p, TOKEN_ARROW) {
    return_type = parse_type(p)
  }

  body = nil
  if parser_check(p, TOKEN_LBRACE) {
    body = parse_block(p)
  } else {
    body = parse_expression(p, PREC_ASSIGNMENT)
  }

  closure = ast_closure(params, body, span)
  closure["return_type"] = return_type
  return closure
}

fn parse_closure_no_params(p: any) -> any {
  token = parser_advance(p)  # skip ||
  span = ast_span_from_token(token)

  body = nil
  if parser_check(p, TOKEN_LBRACE) {
    body = parse_block(p)
  } else {
    body = parse_expression(p, PREC_ASSIGNMENT)
  }

  return ast_closure([], body, span)
}

# ---- Postfix Operations ----

fn parse_call(p: any, callee: any) -> any {
  parser_advance(p)  # skip (
  span = callee["span"]

  args = []
  parser_skip_newlines(p)

  while not parser_check(p, TOKEN_RPAREN) and not parser_at_end(p) {
    push(args, parse_expression(p, PREC_ASSIGNMENT))
    parser_match(p, TOKEN_COMMA)
    parser_skip_newlines(p)
  }

  parser_expect(p, TOKEN_RPAREN)
  return ast_call(callee, args, span)
}

fn parse_index_expr(p: any, object: any) -> any {
  parser_advance(p)  # skip [
  span = object["span"]

  index = parse_expression(p, PREC_NONE)
  parser_expect(p, TOKEN_RBRACKET)

  return ast_index(object, index, span)
}

fn parse_dot_expr(p: any, object: any) -> any {
  parser_advance(p)  # skip .
  span = object["span"]

  # await is a postfix keyword: expr.await
  if parser_check(p, TOKEN_AWAIT) {
    parser_advance(p)
    return ast_await_expr(object, span)
  }

  field_token = parser_advance(p)
  field = field_token["value"]

  # Method call: object.method(args)
  if parser_check(p, TOKEN_LPAREN) {
    parser_advance(p)
    args = []
    parser_skip_newlines(p)
    while not parser_check(p, TOKEN_RPAREN) and not parser_at_end(p) {
      push(args, parse_expression(p, PREC_ASSIGNMENT))
      parser_match(p, TOKEN_COMMA)
      parser_skip_newlines(p)
    }
    parser_expect(p, TOKEN_RPAREN)
    return ast_method_call(object, field, args, span)
  }

  return ast_field_access(object, field, span)
}

fn parse_path_expr(p: any, left: any) -> any {
  parser_advance(p)  # skip ::
  right_token = parser_advance(p)

  span = left["span"]
  path_node = ast_node("PathExpr", span)
  path_node["left"] = left
  path_node["right"] = right_token["value"]
  return path_node
}

fn parse_try(p: any, expr: any) -> any {
  parser_advance(p)  # skip ?
  return ast_try_expr(expr, expr["span"])
}

fn parse_cast(p: any, expr: any) -> any {
  parser_advance(p)  # skip as
  target_type = parse_type(p)
  return ast_cast_expr(expr, target_type, expr["span"])
}

fn parse_await(p: any, expr: any) -> any {
  parser_advance(p)  # skip await
  return ast_await_expr(expr, expr["span"])
}

fn parse_range(p: any, start: any) -> any {
  token = parser_advance(p)
  inclusive = token["type"] == TOKEN_DOTDOTDOT
  span = start["span"]

  end_val = nil
  if not parser_check(p, TOKEN_RBRACE) and not parser_check(p, TOKEN_RBRACKET) and
     not parser_check(p, TOKEN_RPAREN) and not parser_at_end(p) {
    end_val = parse_expression(p, PREC_RANGE)
  }

  return ast_range(start, end_val, inclusive, span)
}

fn parse_pipe(p: any, left: any) -> any {
  parser_advance(p)  # skip |>
  right = parse_expression(p, PREC_PIPE)
  return ast_pipe_expr(left, right, left["span"])
}

# ================================================================
# Pattern Parsing
# ================================================================

fn parse_pattern(p: any) -> any {
  parser_skip_newlines(p)
  token = parser_peek(p)
  tt = token["type"]
  span = ast_span_from_token(token)

  match tt {
    TOKEN_UNDERSCORE => {
      parser_advance(p)
      pattern = ast_pat_wildcard(span)
      # Check for OR pattern
      if parser_check(p, TOKEN_PIPE) {
        return parse_or_pattern(p, pattern)
      }
      return pattern
    },
    TOKEN_INTEGER => {
      parser_advance(p)
      pattern = ast_pat_literal(token["value"], span)
      if parser_check(p, TOKEN_DOTDOT) or parser_check(p, TOKEN_DOTDOTDOT) {
        return parse_range_pattern(p, pattern)
      }
      if parser_check(p, TOKEN_PIPE) {
        return parse_or_pattern(p, pattern)
      }
      return pattern
    },
    TOKEN_STRING => {
      parser_advance(p)
      return ast_pat_literal(token["value"], span)
    },
    TOKEN_BOOL_TRUE => {
      parser_advance(p)
      return ast_pat_literal(true, span)
    },
    TOKEN_BOOL_FALSE => {
      parser_advance(p)
      return ast_pat_literal(false, span)
    },
    TOKEN_IDENT => {
      parser_advance(p)
      name = token["value"]

      # Enum pattern: SomeEnum::Variant(...)
      if parser_check(p, TOKEN_COLONCOLON) {
        parser_advance(p)
        variant = parser_advance(p)["value"]
        patterns = []
        if parser_check(p, TOKEN_LPAREN) {
          parser_advance(p)
          while not parser_check(p, TOKEN_RPAREN) and not parser_at_end(p) {
            push(patterns, parse_pattern(p))
            parser_match(p, TOKEN_COMMA)
          }
          parser_expect(p, TOKEN_RPAREN)
        }
        return ast_pat_enum(name, variant, patterns, span)
      }

      # Struct pattern: Point { x, y }
      if parser_check(p, TOKEN_LBRACE) {
        parser_advance(p)
        field_pats = []
        parser_skip_newlines(p)
        while not parser_check(p, TOKEN_RBRACE) and not parser_at_end(p) {
          f_name = parser_advance(p)["value"]
          f_pattern = nil
          if parser_match(p, TOKEN_COLON) {
            f_pattern = parse_pattern(p)
          }
          push(field_pats, { "name": f_name, "pattern": f_pattern })
          parser_match(p, TOKEN_COMMA)
          parser_skip_newlines(p)
        }
        parser_expect(p, TOKEN_RBRACE)
        return ast_pat_struct(name, field_pats, span)
      }

      pattern = ast_pat_ident(name, false, span)
      if parser_check(p, TOKEN_PIPE) {
        return parse_or_pattern(p, pattern)
      }
      return pattern
    },
    TOKEN_LPAREN => {
      parser_advance(p)
      patterns = []
      while not parser_check(p, TOKEN_RPAREN) and not parser_at_end(p) {
        push(patterns, parse_pattern(p))
        parser_match(p, TOKEN_COMMA)
      }
      parser_expect(p, TOKEN_RPAREN)
      return ast_pat_tuple(patterns, span)
    },
    _ => {
      parser_advance(p)
      return ast_pat_literal(token["value"], span)
    }
  }
}

fn parse_or_pattern(p: any, first: any) -> any {
  patterns = [first]
  while parser_match(p, TOKEN_PIPE) {
    parser_skip_newlines(p)
    push(patterns, parse_pattern(p))
  }
  return ast_pat_or(patterns, first["span"])
}

fn parse_range_pattern(p: any, start: any) -> any {
  token = parser_advance(p)
  inclusive = token["type"] == TOKEN_DOTDOTDOT
  end_pat = parse_pattern(p)
  return ast_pat_range(start, end_pat, inclusive, start["span"])
}

# ================================================================
# Type Parsing
# ================================================================

fn parse_type(p: any) -> any {
  parser_skip_newlines(p)
  token = parser_peek(p)
  tt = token["type"]
  span = ast_span_from_token(token)

  # Reference type: &T, &mut T
  if tt == TOKEN_BAND {
    parser_advance(p)
    is_mut = parser_match(p, TOKEN_MUT)
    inner = parse_type(p)
    return ast_type_ref(inner, is_mut, span)
  }

  # Array type: [T; N] or [T]
  if tt == TOKEN_LBRACKET {
    parser_advance(p)
    elem_type = parse_type(p)
    size = nil
    if parser_match(p, TOKEN_SEMICOLON) {
      size = parse_expression(p, PREC_NONE)
    }
    parser_expect(p, TOKEN_RBRACKET)
    return ast_type_array(elem_type, size, span)
  }

  # Tuple type: (T1, T2)
  if tt == TOKEN_LPAREN {
    parser_advance(p)
    types = []
    while not parser_check(p, TOKEN_RPAREN) and not parser_at_end(p) {
      push(types, parse_type(p))
      parser_match(p, TOKEN_COMMA)
    }
    parser_expect(p, TOKEN_RPAREN)
    node = ast_node(AST_TYPE_TUPLE, span)
    node["types"] = types
    return node
  }

  # Function type: fn(T1, T2) -> T3
  if tt == TOKEN_FN {
    parser_advance(p)
    parser_expect(p, TOKEN_LPAREN)
    param_types = []
    while not parser_check(p, TOKEN_RPAREN) and not parser_at_end(p) {
      push(param_types, parse_type(p))
      parser_match(p, TOKEN_COMMA)
    }
    parser_expect(p, TOKEN_RPAREN)
    ret_type = nil
    if parser_match(p, TOKEN_ARROW) {
      ret_type = parse_type(p)
    }
    return ast_type_fn(param_types, ret_type, span)
  }

  # Infer type: _
  if tt == TOKEN_UNDERSCORE {
    parser_advance(p)
    return ast_node(AST_TYPE_INFER, span)
  }

  # Named type (possibly generic)
  name = parser_advance(p)["value"]

  # Check for generic arguments: Type<A, B>
  if parser_check(p, TOKEN_LT) {
    parser_advance(p)
    type_args = []
    while not parser_check(p, TOKEN_GT) and not parser_at_end(p) {
      push(type_args, parse_type(p))
      parser_match(p, TOKEN_COMMA)
    }
    parser_expect(p, TOKEN_GT)
    return ast_type_generic(name, type_args, span)
  }

  return ast_type_named(name, span)
}

# ---- Parser Performance Report ----

fn parser_performance_report(result: any) -> any {
  return {
    "node_count": result["node_count"],
    "error_count": result["error_count"],
    "elapsed_ms": result["elapsed_ms"],
    "accuracy": 100.0 - (result["error_count"] * 100.0 / max(result["node_count"], 1)),
    "r2_pass": (100.0 - (result["error_count"] * 100.0 / max(result["node_count"], 1))) > 99.0
  }
}

