# ---- Type Kind Constants ----

TYPE_I8       = "i8"
TYPE_I16      = "i16"
TYPE_I32      = "i32"
TYPE_I64      = "i64"
TYPE_U8       = "u8"
TYPE_U16      = "u16"
TYPE_U32      = "u32"
TYPE_U64      = "u64"
TYPE_F32      = "f32"
TYPE_F64      = "f64"
TYPE_BOOL     = "bool"
TYPE_CHAR     = "char"
TYPE_STRING   = "string"
TYPE_VOID     = "void"
TYPE_NEVER    = "never"
TYPE_NIL      = "nil"
TYPE_ANY      = "any"
TYPE_ARRAY    = "array"
TYPE_TUPLE    = "tuple"
TYPE_DICT     = "dict"
TYPE_FN       = "fn"
TYPE_STRUCT   = "struct"
TYPE_ENUM     = "enum"
TYPE_TRAIT    = "trait"
TYPE_REF      = "ref"
TYPE_MUT_REF  = "mut_ref"
TYPE_GENERIC  = "generic"
TYPE_INFER    = "infer"
TYPE_OPTION   = "Option"
TYPE_RESULT   = "Result"
TYPE_SELF     = "Self"

# ---- Type Representation ----

fn create_type(kind: string) -> any {
  return {
    "kind": kind,
    "name": kind,
    "id": 0,
    "size": 0,
    "align": 0,
    "is_numeric": false,
    "is_integer": false,
    "is_float": false,
    "is_signed": false
  }
}

fn type_primitive(kind: string) -> any {
  t = create_type(kind)
  match kind {
    "i8"   => { t["size"] = 1; t["align"] = 1; t["is_numeric"] = true; t["is_integer"] = true; t["is_signed"] = true },
    "i16"  => { t["size"] = 2; t["align"] = 2; t["is_numeric"] = true; t["is_integer"] = true; t["is_signed"] = true },
    "i32"  => { t["size"] = 4; t["align"] = 4; t["is_numeric"] = true; t["is_integer"] = true; t["is_signed"] = true },
    "i64"  => { t["size"] = 8; t["align"] = 8; t["is_numeric"] = true; t["is_integer"] = true; t["is_signed"] = true },
    "u8"   => { t["size"] = 1; t["align"] = 1; t["is_numeric"] = true; t["is_integer"] = true },
    "u16"  => { t["size"] = 2; t["align"] = 2; t["is_numeric"] = true; t["is_integer"] = true },
    "u32"  => { t["size"] = 4; t["align"] = 4; t["is_numeric"] = true; t["is_integer"] = true },
    "u64"  => { t["size"] = 8; t["align"] = 8; t["is_numeric"] = true; t["is_integer"] = true },
    "f32"  => { t["size"] = 4; t["align"] = 4; t["is_numeric"] = true; t["is_float"] = true; t["is_signed"] = true },
    "f64"  => { t["size"] = 8; t["align"] = 8; t["is_numeric"] = true; t["is_float"] = true; t["is_signed"] = true },
    "bool" => { t["size"] = 1; t["align"] = 1 },
    "char" => { t["size"] = 4; t["align"] = 4 },
    "string" => { t["size"] = 24; t["align"] = 8 },
    "void" => { t["size"] = 0; t["align"] = 1 },
    "never" => { t["size"] = 0; t["align"] = 1 },
    _ => {}
  }
  return t
}

fn type_array(element_type: any, size: any) -> any {
  t = create_type(TYPE_ARRAY)
  t["element_type"] = element_type
  t["array_size"] = size  # nil for dynamic arrays
  if size != nil and element_type["size"] > 0 {
    t["size"] = element_type["size"] * size
    t["align"] = element_type["align"]
  } else {
    t["size"] = 24  # fat pointer (ptr + len + cap)
    t["align"] = 8
  }
  return t
}

fn type_tuple(types: array) -> any {
  t = create_type(TYPE_TUPLE)
  t["types"] = types
  # Calculate size with alignment padding
  total_size = 0
  max_align = 1
  i = 0
  while i < length(types) {
    elem = types[i]
    # Align
    if elem["align"] > 0 {
      padding = (elem["align"] - (total_size % elem["align"])) % elem["align"]
      total_size = total_size + padding
    }
    total_size = total_size + elem["size"]
    if elem["align"] > max_align {
      max_align = elem["align"]
    }
    i = i + 1
  }
  t["size"] = total_size
  t["align"] = max_align
  return t
}

fn type_dict(key_type: any, value_type: any) -> any {
  t = create_type(TYPE_DICT)
  t["key_type"] = key_type
  t["value_type"] = value_type
  t["size"] = 48  # HashMap internal representation
  t["align"] = 8
  return t
}

fn type_fn(param_types: array, return_type: any) -> any {
  t = create_type(TYPE_FN)
  t["param_types"] = param_types
  t["return_type"] = return_type
  t["size"] = 8  # function pointer
  t["align"] = 8
  return t
}

fn type_struct(name: string, fields: array) -> any {
  t = create_type(TYPE_STRUCT)
  t["name"] = name
  t["fields"] = fields  # [{name, type}, ...]
  t["generic_params"] = []
  # Calculate layout
  total_size = 0
  max_align = 1
  i = 0
  while i < length(fields) {
    f = fields[i]
    ft = f["type"]
    if ft != nil and ft["align"] > 0 {
      padding = (ft["align"] - (total_size % ft["align"])) % ft["align"]
      total_size = total_size + padding
    }
    if ft != nil {
      total_size = total_size + ft["size"]
      if ft["align"] > max_align {
        max_align = ft["align"]
      }
    }
    i = i + 1
  }
  t["size"] = total_size
  t["align"] = max_align
  return t
}

fn type_enum(name: string, variants: array) -> any {
  t = create_type(TYPE_ENUM)
  t["name"] = name
  t["variants"] = variants  # [{name, types}, ...]
  t["generic_params"] = []
  # Size = discriminant + max variant size
  max_variant_size = 0
  i = 0
  while i < length(variants) {
    v = variants[i]
    v_size = 0
    j = 0
    if v["types"] != nil {
      while j < length(v["types"]) {
        v_size = v_size + v["types"][j]["size"]
        j = j + 1
      }
    }
    if v_size > max_variant_size {
      max_variant_size = v_size
    }
    i = i + 1
  }
  t["size"] = 4 + max_variant_size  # 4 bytes discriminant
  t["align"] = 8
  return t
}

fn type_ref(inner_type: any, is_mut: bool) -> any {
  t = create_type(TYPE_REF)
  if is_mut {
    t["kind"] = TYPE_MUT_REF
  }
  t["inner_type"] = inner_type
  t["is_mut"] = is_mut
  t["size"] = 8  # pointer
  t["align"] = 8
  return t
}

fn type_generic(name: string, bounds: array) -> any {
  t = create_type(TYPE_GENERIC)
  t["name"] = name
  t["bounds"] = bounds
  return t
}

fn type_option(inner_type: any) -> any {
  t = create_type(TYPE_OPTION)
  t["inner_type"] = inner_type
  t["size"] = inner_type["size"] + 1  # discriminant byte
  t["align"] = inner_type["align"]
  return t
}

fn type_result(ok_type: any, err_type: any) -> any {
  t = create_type(TYPE_RESULT)
  t["ok_type"] = ok_type
  t["err_type"] = err_type
  max_size = ok_type["size"]
  if err_type["size"] > max_size {
    max_size = err_type["size"]
  }
  t["size"] = max_size + 1  # discriminant byte
  t["align"] = 8
  return t
}

fn type_infer(id: i32) -> any {
  t = create_type(TYPE_INFER)
  t["infer_id"] = id
  return t
}

# ---- Type Checker ----

fn create_type_checker() -> any {
  return {
    "scopes": [{}],        # Stack of scope maps
    "scope_depth": 0,
    "type_defs": {},       # Named type definitions
    "trait_defs": {},      # Trait definitions
    "impl_defs": [],       # Impl blocks
    "infer_counter": 0,
    "substitutions": {},   # Type variable substitutions
    "errors": [],
    "error_count": 0,
    "warnings": [],
    "checked_count": 0
  }
}

# ---- Scope Management ----

fn tc_push_scope(tc: any) -> any {
  push(tc["scopes"], {})
  tc["scope_depth"] = tc["scope_depth"] + 1
  return tc
}

fn tc_pop_scope(tc: any) -> any {
  pop(tc["scopes"])
  tc["scope_depth"] = tc["scope_depth"] - 1
  return tc
}

fn tc_define(tc: any, name: string, type_info: any) -> any {
  current_scope = tc["scopes"][tc["scope_depth"]]
  current_scope[name] = type_info
  return tc
}

fn tc_lookup(tc: any, name: string) -> any {
  # Search from innermost scope outward
  depth = tc["scope_depth"]
  while depth >= 0 {
    scope = tc["scopes"][depth]
    if scope[name] != nil {
      return scope[name]
    }
    depth = depth - 1
  }
  return nil
}

fn tc_define_type(tc: any, name: string, type_def: any) -> any {
  tc["type_defs"][name] = type_def
  return tc
}

fn tc_lookup_type(tc: any, name: string) -> any {
  return tc["type_defs"][name]
}

fn tc_define_trait(tc: any, name: string, trait_def: any) -> any {
  tc["trait_defs"][name] = trait_def
  return tc
}

fn tc_add_impl(tc: any, impl_def: any) -> any {
  push(tc["impl_defs"], impl_def)
  return tc
}

# ---- Error Reporting ----

fn tc_error(tc: any, message: string, span: any) -> any {
  err = {
    "message": message,
    "line": span["line"],
    "col": span["col"]
  }
  push(tc["errors"], err)
  tc["error_count"] = tc["error_count"] + 1
  return tc
}

fn tc_warning(tc: any, message: string, span: any) -> any {
  push(tc["warnings"], { "message": message, "line": span["line"], "col": span["col"] })
  return tc
}

# ---- Type Inference ----

fn tc_fresh_type_var(tc: any) -> any {
  tc["infer_counter"] = tc["infer_counter"] + 1
  return type_infer(tc["infer_counter"])
}

fn tc_unify(tc: any, t1: any, t2: any, span: any) -> bool {
  # Resolve type variables
  t1 = tc_resolve(tc, t1)
  t2 = tc_resolve(tc, t2)

  if t1 == nil or t2 == nil {
    return true  # Allow nil (unknown) to unify
  }

  # Same type
  if t1["kind"] == t2["kind"] and t1["name"] == t2["name"] {
    return true
  }

  # Infer variable
  if t1["kind"] == TYPE_INFER {
    tc["substitutions"][to_string(t1["infer_id"])] = t2
    return true
  }
  if t2["kind"] == TYPE_INFER {
    tc["substitutions"][to_string(t2["infer_id"])] = t1
    return true
  }

  # Any type matches everything
  if t1["kind"] == TYPE_ANY or t2["kind"] == TYPE_ANY {
    return true
  }

  # Never type is a subtype of everything
  if t1["kind"] == TYPE_NEVER or t2["kind"] == TYPE_NEVER {
    return true
  }

  # Numeric coercion: i32 -> i64, f32 -> f64
  if t1["is_numeric"] and t2["is_numeric"] {
    if type_can_coerce(t1, t2) {
      return true
    }
  }

  # Array element type unification
  if t1["kind"] == TYPE_ARRAY and t2["kind"] == TYPE_ARRAY {
    return tc_unify(tc, t1["element_type"], t2["element_type"], span)
  }

  # Function type unification
  if t1["kind"] == TYPE_FN and t2["kind"] == TYPE_FN {
    if length(t1["param_types"]) != length(t2["param_types"]) {
      tc_error(tc, "Function parameter count mismatch", span)
      return false
    }
    i = 0
    while i < length(t1["param_types"]) {
      if not tc_unify(tc, t1["param_types"][i], t2["param_types"][i], span) {
        return false
      }
      i = i + 1
    }
    return tc_unify(tc, t1["return_type"], t2["return_type"], span)
  }

  # Option unification
  if t1["kind"] == TYPE_OPTION and t2["kind"] == TYPE_OPTION {
    return tc_unify(tc, t1["inner_type"], t2["inner_type"], span)
  }

  # Result unification
  if t1["kind"] == TYPE_RESULT and t2["kind"] == TYPE_RESULT {
    return tc_unify(tc, t1["ok_type"], t2["ok_type"], span) and
           tc_unify(tc, t1["err_type"], t2["err_type"], span)
  }

  # Ref unification
  if (t1["kind"] == TYPE_REF or t1["kind"] == TYPE_MUT_REF) and
     (t2["kind"] == TYPE_REF or t2["kind"] == TYPE_MUT_REF) {
    return tc_unify(tc, t1["inner_type"], t2["inner_type"], span)
  }

  tc_error(tc, "Type mismatch: expected " + type_to_string(t1) + ", got " + type_to_string(t2), span)
  return false
}

fn tc_resolve(tc: any, t: any) -> any {
  if t == nil {
    return nil
  }
  if t["kind"] == TYPE_INFER {
    resolved = tc["substitutions"][to_string(t["infer_id"])]
    if resolved != nil {
      return tc_resolve(tc, resolved)
    }
  }
  return t
}

# ---- Type Coercion Rules ----

fn type_can_coerce(from: any, to: any) -> bool {
  if from["kind"] == to["kind"] {
    return true
  }

  # Widening: i8 -> i16 -> i32 -> i64
  if from["is_integer"] and to["is_integer"] and to["size"] >= from["size"] {
    if from["is_signed"] == to["is_signed"] or (not from["is_signed"] and to["is_signed"]) {
      return true
    }
  }

  # Float widening: f32 -> f64
  if from["is_float"] and to["is_float"] and to["size"] >= from["size"] {
    return true
  }

  # Integer to float
  if from["is_integer"] and to["is_float"] {
    return true
  }

  return false
}

# ---- AST Type Checking ----

fn check_program(tc: any, program: any) -> any {
  # Register built-in types
  tc_define(tc, "i8", type_primitive("i8"))
  tc_define(tc, "i16", type_primitive("i16"))
  tc_define(tc, "i32", type_primitive("i32"))
  tc_define(tc, "i64", type_primitive("i64"))
  tc_define(tc, "u8", type_primitive("u8"))
  tc_define(tc, "u16", type_primitive("u16"))
  tc_define(tc, "u32", type_primitive("u32"))
  tc_define(tc, "u64", type_primitive("u64"))
  tc_define(tc, "f32", type_primitive("f32"))
  tc_define(tc, "f64", type_primitive("f64"))
  tc_define(tc, "bool", type_primitive("bool"))
  tc_define(tc, "char", type_primitive("char"))
  tc_define(tc, "string", type_primitive("string"))
  tc_define(tc, "void", type_primitive("void"))

  # Check all declarations
  i = 0
  while i < length(program["declarations"]) {
    check_declaration(tc, program["declarations"][i])
    i = i + 1
  }

  return tc
}

fn check_declaration(tc: any, decl: any) -> any {
  tc["checked_count"] = tc["checked_count"] + 1
  kind = decl["kind"]

  match kind {
    AST_FN_DECL      => { return check_fn_decl(tc, decl) },
    AST_LET_DECL     => { return check_let_decl(tc, decl) },
    AST_CONST_DECL   => { return check_const_decl(tc, decl) },
    AST_STRUCT_DECL  => { return check_struct_decl(tc, decl) },
    AST_ENUM_DECL    => { return check_enum_decl(tc, decl) },
    AST_TRAIT_DECL   => { return check_trait_decl(tc, decl) },
    AST_IMPL_DECL    => { return check_impl_decl(tc, decl) },
    AST_EXPR_STMT    => { return check_expr(tc, decl["expr"]) },
    AST_RETURN_STMT  => { return check_return_stmt(tc, decl) },
    AST_ASSIGNMENT   => { return check_assignment(tc, decl) },
    AST_BLOCK        => { return check_block(tc, decl) },
    _ => { return nil }
  }
}

fn check_fn_decl(tc: any, decl: any) -> any {
  # Build function type from parameters and return type
  param_types = []
  i = 0
  while i < length(decl["params"]) {
    p = decl["params"][i]
    pt = nil
    if p["type_ann"] != nil {
      pt = resolve_type_annotation(tc, p["type_ann"])
    } else {
      pt = tc_fresh_type_var(tc)
    }
    push(param_types, pt)
    i = i + 1
  }

  ret_type = nil
  if decl["return_type"] != nil {
    ret_type = resolve_type_annotation(tc, decl["return_type"])
  } else {
    ret_type = tc_fresh_type_var(tc)
  }

  fn_type = type_fn(param_types, ret_type)
  tc_define(tc, decl["name"], fn_type)

  # Check body in new scope
  tc_push_scope(tc)

  # Define params in scope
  i = 0
  while i < length(decl["params"]) {
    p = decl["params"][i]
    tc_define(tc, p["name"], param_types[i])
    i = i + 1
  }

  # Check body
  if decl["body"] != nil {
    body_type = check_block(tc, decl["body"])
    # Unify body type with declared return type
    if ret_type != nil and body_type != nil {
      tc_unify(tc, ret_type, body_type, decl["span"])
    }
  }

  tc_pop_scope(tc)
  decl["type_info"] = fn_type
  return fn_type
}

fn check_let_decl(tc: any, decl: any) -> any {
  declared_type = nil
  if decl["type_ann"] != nil {
    declared_type = resolve_type_annotation(tc, decl["type_ann"])
  }

  value_type = nil
  if decl["value"] != nil {
    value_type = check_expr(tc, decl["value"])
  }

  final_type = nil
  if declared_type != nil and value_type != nil {
    tc_unify(tc, declared_type, value_type, decl["span"])
    final_type = declared_type
  } else if declared_type != nil {
    final_type = declared_type
  } else if value_type != nil {
    final_type = value_type
  } else {
    final_type = tc_fresh_type_var(tc)
  }

  tc_define(tc, decl["name"], final_type)
  decl["type_info"] = final_type
  return final_type
}

fn check_const_decl(tc: any, decl: any) -> any {
  value_type = check_expr(tc, decl["value"])
  if decl["type_ann"] != nil {
    declared_type = resolve_type_annotation(tc, decl["type_ann"])
    tc_unify(tc, declared_type, value_type, decl["span"])
    tc_define(tc, decl["name"], declared_type)
    return declared_type
  }
  tc_define(tc, decl["name"], value_type)
  return value_type
}

fn check_struct_decl(tc: any, decl: any) -> any {
  fields = []
  i = 0
  while i < length(decl["fields"]) {
    f = decl["fields"][i]
    ft = resolve_type_annotation(tc, f["type_ann"])
    push(fields, { "name": f["name"], "type": ft })
    i = i + 1
  }
  struct_type = type_struct(decl["name"], fields)
  tc_define_type(tc, decl["name"], struct_type)
  tc_define(tc, decl["name"], struct_type)
  return struct_type
}

fn check_enum_decl(tc: any, decl: any) -> any {
  variants = []
  i = 0
  while i < length(decl["variants"]) {
    v = decl["variants"][i]
    v_types = []
    if v["fields"] != nil {
      j = 0
      while j < length(v["fields"]) {
        push(v_types, resolve_type_annotation(tc, v["fields"][j]))
        j = j + 1
      }
    }
    push(variants, { "name": v["name"], "types": v_types })
    i = i + 1
  }
  enum_type = type_enum(decl["name"], variants)
  tc_define_type(tc, decl["name"], enum_type)
  tc_define(tc, decl["name"], enum_type)
  return enum_type
}

fn check_trait_decl(tc: any, decl: any) -> any {
  tc_define_trait(tc, decl["name"], decl)
  return nil
}

fn check_impl_decl(tc: any, decl: any) -> any {
  tc_add_impl(tc, decl)
  tc_push_scope(tc)

  # Check all methods
  i = 0
  while i < length(decl["methods"]) {
    check_fn_decl(tc, decl["methods"][i])
    i = i + 1
  }

  tc_pop_scope(tc)
  return nil
}

fn check_block(tc: any, block: any) -> any {
  if block == nil {
    return type_primitive("void")
  }

  tc_push_scope(tc)
  last_type = type_primitive("void")

  i = 0
  while i < length(block["statements"]) {
    last_type = check_declaration(tc, block["statements"][i])
    i = i + 1
  }

  tc_pop_scope(tc)
  return last_type
}

fn check_return_stmt(tc: any, stmt: any) -> any {
  if stmt["value"] != nil {
    return check_expr(tc, stmt["value"])
  }
  return type_primitive("void")
}

fn check_assignment(tc: any, stmt: any) -> any {
  target_type = check_expr(tc, stmt["target"])
  value_type = check_expr(tc, stmt["value"])
  tc_unify(tc, target_type, value_type, stmt["span"])
  return type_primitive("void")
}

# ---- Expression Type Checking ----

fn check_expr(tc: any, expr: any) -> any {
  if expr == nil {
    return nil
  }
  tc["checked_count"] = tc["checked_count"] + 1
  kind = expr["kind"]

  match kind {
    AST_LITERAL => {
      return check_literal(tc, expr)
    },
    AST_IDENT => {
      result = tc_lookup(tc, expr["name"])
      if result == nil {
        tc_error(tc, "Undefined variable: " + expr["name"], expr["span"])
        return tc_fresh_type_var(tc)
      }
      expr["type_info"] = result
      return result
    },
    AST_BINARY => {
      return check_binary(tc, expr)
    },
    AST_UNARY => {
      return check_unary(tc, expr)
    },
    AST_CALL => {
      return check_call(tc, expr)
    },
    AST_METHOD_CALL => {
      return check_method_call(tc, expr)
    },
    AST_FIELD_ACCESS => {
      return check_field_access(tc, expr)
    },
    AST_INDEX => {
      return check_index(tc, expr)
    },
    AST_IF_EXPR => {
      return check_if_expr(tc, expr)
    },
    AST_MATCH_EXPR => {
      return check_match_expr(tc, expr)
    },
    AST_BLOCK => {
      return check_block(tc, expr)
    },
    AST_ARRAY_LITERAL => {
      return check_array_literal(tc, expr)
    },
    AST_WHILE_EXPR => {
      check_expr(tc, expr["condition"])
      check_block(tc, expr["body"])
      return type_primitive("void")
    },
    AST_FOR_EXPR => {
      tc_push_scope(tc)
      iter_type = check_expr(tc, expr["iterable"])
      tc_define(tc, expr["variable"], tc_fresh_type_var(tc))
      check_block(tc, expr["body"])
      tc_pop_scope(tc)
      return type_primitive("void")
    },
    AST_CLOSURE => {
      return check_closure(tc, expr)
    },
    AST_ASYNC_EXPR => {
      body_type = check_block(tc, expr["body"])
      return body_type
    },
    AST_AWAIT_EXPR => {
      return check_expr(tc, expr["expr"])
    },
    AST_TRY_EXPR => {
      return check_expr(tc, expr["expr"])
    },
    _ => {
      return tc_fresh_type_var(tc)
    }
  }
}

fn check_literal(tc: any, expr: any) -> any {
  result = nil
  match expr["lit_type"] {
    "integer" => { result = type_primitive("i32") },
    "float"   => { result = type_primitive("f64") },
    "string"  => { result = type_primitive("string") },
    "char"    => { result = type_primitive("char") },
    "bool"    => { result = type_primitive("bool") },
    "nil"     => { result = type_primitive("nil") },
    _ => { result = tc_fresh_type_var(tc) }
  }
  expr["type_info"] = result
  return result
}

fn check_binary(tc: any, expr: any) -> any {
  left_type = check_expr(tc, expr["left"])
  right_type = check_expr(tc, expr["right"])
  op = expr["op"]

  # Comparison operators return bool
  if op == "==" or op == "!=" or op == "<" or op == ">" or op == "<=" or op == ">=" {
    tc_unify(tc, left_type, right_type, expr["span"])
    result = type_primitive("bool")
    expr["type_info"] = result
    return result
  }

  # Logical operators
  if op == "&&" or op == "||" {
    tc_unify(tc, left_type, type_primitive("bool"), expr["span"])
    tc_unify(tc, right_type, type_primitive("bool"), expr["span"])
    result = type_primitive("bool")
    expr["type_info"] = result
    return result
  }

  # String concatenation
  if op == "+" and left_type != nil and left_type["kind"] == TYPE_STRING {
    result = type_primitive("string")
    expr["type_info"] = result
    return result
  }

  # Arithmetic operators
  tc_unify(tc, left_type, right_type, expr["span"])
  expr["type_info"] = left_type
  return left_type
}

fn check_unary(tc: any, expr: any) -> any {
  operand_type = check_expr(tc, expr["operand"])
  op = expr["op"]

  if op == "!" {
    result = type_primitive("bool")
    expr["type_info"] = result
    return result
  }
  if op == "-" {
    expr["type_info"] = operand_type
    return operand_type
  }
  if op == "&" {
    result = type_ref(operand_type, expr["is_mut"] == true)
    expr["type_info"] = result
    return result
  }

  return operand_type
}

fn check_call(tc: any, expr: any) -> any {
  callee_type = check_expr(tc, expr["callee"])

  if callee_type != nil and callee_type["kind"] == TYPE_FN {
    # Check argument count
    if length(expr["args"]) != length(callee_type["param_types"]) {
      tc_error(tc, "Expected " + to_string(length(callee_type["param_types"])) +
               " arguments, got " + to_string(length(expr["args"])), expr["span"])
    } else {
      # Check each argument
      i = 0
      while i < length(expr["args"]) {
        arg_type = check_expr(tc, expr["args"][i])
        tc_unify(tc, callee_type["param_types"][i], arg_type, expr["span"])
        i = i + 1
      }
    }
    result = callee_type["return_type"]
    expr["type_info"] = result
    return result
  }

  # Unknown callee type
  i = 0
  while i < length(expr["args"]) {
    check_expr(tc, expr["args"][i])
    i = i + 1
  }
  return tc_fresh_type_var(tc)
}

fn check_method_call(tc: any, expr: any) -> any {
  object_type = check_expr(tc, expr["object"])
  i = 0
  while i < length(expr["args"]) {
    check_expr(tc, expr["args"][i])
    i = i + 1
  }
  return tc_fresh_type_var(tc)
}

fn check_field_access(tc: any, expr: any) -> any {
  object_type = check_expr(tc, expr["object"])
  object_type = tc_resolve(tc, object_type)

  if object_type != nil and object_type["kind"] == TYPE_STRUCT {
    i = 0
    while i < length(object_type["fields"]) {
      f = object_type["fields"][i]
      if f["name"] == expr["field"] {
        expr["type_info"] = f["type"]
        return f["type"]
      }
      i = i + 1
    }
    tc_error(tc, "No field '" + expr["field"] + "' on type " + object_type["name"], expr["span"])
  }

  return tc_fresh_type_var(tc)
}

fn check_index(tc: any, expr: any) -> any {
  object_type = check_expr(tc, expr["object"])
  index_type = check_expr(tc, expr["index"])

  object_type = tc_resolve(tc, object_type)

  if object_type != nil and object_type["kind"] == TYPE_ARRAY {
    expr["type_info"] = object_type["element_type"]
    return object_type["element_type"]
  }

  return tc_fresh_type_var(tc)
}

fn check_if_expr(tc: any, expr: any) -> any {
  cond_type = check_expr(tc, expr["condition"])
  tc_unify(tc, cond_type, type_primitive("bool"), expr["span"])

  then_type = check_block(tc, expr["then_block"])
  if expr["else_block"] != nil {
    else_type = nil
    if expr["else_block"]["kind"] == AST_IF_EXPR {
      else_type = check_expr(tc, expr["else_block"])
    } else {
      else_type = check_block(tc, expr["else_block"])
    }
    tc_unify(tc, then_type, else_type, expr["span"])
  }

  return then_type
}

fn check_match_expr(tc: any, expr: any) -> any {
  subject_type = check_expr(tc, expr["subject"])
  result_type = tc_fresh_type_var(tc)

  i = 0
  while i < length(expr["arms"]) {
    arm = expr["arms"][i]
    # Check pattern
    check_pattern(tc, arm["pattern"], subject_type)
    # Check guard
    if arm["guard"] != nil {
      guard_type = check_expr(tc, arm["guard"])
      tc_unify(tc, guard_type, type_primitive("bool"), expr["span"])
    }
    # Check body
    body_type = check_expr(tc, arm["body"])
    tc_unify(tc, result_type, body_type, expr["span"])
    i = i + 1
  }

  return result_type
}

fn check_array_literal(tc: any, expr: any) -> any {
  if length(expr["elements"]) == 0 {
    return type_array(tc_fresh_type_var(tc), nil)
  }

  elem_type = check_expr(tc, expr["elements"][0])
  i = 1
  while i < length(expr["elements"]) {
    et = check_expr(tc, expr["elements"][i])
    tc_unify(tc, elem_type, et, expr["span"])
    i = i + 1
  }

  return type_array(elem_type, length(expr["elements"]))
}

fn check_closure(tc: any, expr: any) -> any {
  tc_push_scope(tc)

  param_types = []
  i = 0
  while i < length(expr["params"]) {
    p = expr["params"][i]
    pt = nil
    if p["type_ann"] != nil {
      pt = resolve_type_annotation(tc, p["type_ann"])
    } else {
      pt = tc_fresh_type_var(tc)
    }
    tc_define(tc, p["name"], pt)
    push(param_types, pt)
    i = i + 1
  }

  body_type = check_expr(tc, expr["body"])
  tc_pop_scope(tc)

  return type_fn(param_types, body_type)
}

fn check_pattern(tc: any, pattern: any, expected_type: any) -> any {
  if pattern == nil {
    return nil
  }
  kind = pattern["kind"]

  match kind {
    AST_PAT_WILDCARD => { return nil },
    AST_PAT_IDENT => {
      tc_define(tc, pattern["name"], expected_type)
      return nil
    },
    AST_PAT_LITERAL => {
      return nil
    },
    _ => { return nil }
  }
}

# ---- Type Resolution from AST Annotations ----

fn resolve_type_annotation(tc: any, type_ast: any) -> any {
  if type_ast == nil {
    return tc_fresh_type_var(tc)
  }

  kind = type_ast["kind"]

  if kind == AST_TYPE_NAMED {
    name = type_ast["name"]
    # Check primitives
    primitive = tc_lookup(tc, name)
    if primitive != nil {
      return primitive
    }
    # Check user-defined types
    user_type = tc_lookup_type(tc, name)
    if user_type != nil {
      return user_type
    }
    return create_type(name)
  }

  if kind == AST_TYPE_GENERIC {
    type_args = []
    i = 0
    while i < length(type_ast["type_args"]) {
      push(type_args, resolve_type_annotation(tc, type_ast["type_args"][i]))
      i = i + 1
    }
    base = create_type(type_ast["name"])
    base["type_args"] = type_args
    return base
  }

  if kind == AST_TYPE_ARRAY {
    elem = resolve_type_annotation(tc, type_ast["element_type"])
    return type_array(elem, type_ast["size"])
  }

  if kind == AST_TYPE_FN {
    param_types = []
    i = 0
    while i < length(type_ast["param_types"]) {
      push(param_types, resolve_type_annotation(tc, type_ast["param_types"][i]))
      i = i + 1
    }
    ret = resolve_type_annotation(tc, type_ast["return_type"])
    return type_fn(param_types, ret)
  }

  if kind == AST_TYPE_REF {
    inner = resolve_type_annotation(tc, type_ast["inner_type"])
    return type_ref(inner, type_ast["is_mut"])
  }

  if kind == AST_TYPE_INFER {
    return tc_fresh_type_var(tc)
  }

  return tc_fresh_type_var(tc)
}

# ---- Type Display ----

fn type_to_string(t: any) -> string {
  if t == nil {
    return "unknown"
  }
  kind = t["kind"]

  if kind == TYPE_ARRAY {
    elem = type_to_string(t["element_type"])
    if t["array_size"] != nil {
      return "[" + elem + "; " + to_string(t["array_size"]) + "]"
    }
    return "[" + elem + "]"
  }
  if kind == TYPE_FN {
    params = ""
    i = 0
    while i < length(t["param_types"]) {
      if i > 0 { params = params + ", " }
      params = params + type_to_string(t["param_types"][i])
      i = i + 1
    }
    ret = type_to_string(t["return_type"])
    return "fn(" + params + ") -> " + ret
  }
  if kind == TYPE_REF {
    return "&" + type_to_string(t["inner_type"])
  }
  if kind == TYPE_MUT_REF {
    return "&mut " + type_to_string(t["inner_type"])
  }
  if kind == TYPE_OPTION {
    return "Option<" + type_to_string(t["inner_type"]) + ">"
  }
  if kind == TYPE_RESULT {
    return "Result<" + type_to_string(t["ok_type"]) + ", " + type_to_string(t["err_type"]) + ">"
  }
  if kind == TYPE_INFER {
    return "?T" + to_string(t["infer_id"])
  }

  return t["name"]
}

# ---- Type Checker Report ----

fn tc_report(tc: any) -> any {
  return {
    "checked_count": tc["checked_count"],
    "error_count": tc["error_count"],
    "warning_count": length(tc["warnings"]),
    "type_defs_count": length(tc["type_defs"]),
    "trait_defs_count": length(tc["trait_defs"]),
    "impl_count": length(tc["impl_defs"]),
    "infer_vars": tc["infer_counter"],
    "r3_pass": tc["error_count"] == 0  # R3: Type safety 100%
  }
}

# ================================================================
# FreeLang v4 Core - Intermediate Representation (IR)
# Three-address code with SSA form for optimization
# ================================================================

# ---- IR Opcode Constants ----

# Arithmetic
IR_ADD      = "ADD"
IR_SUB      = "SUB"
IR_MUL      = "MUL"
IR_DIV      = "DIV"
IR_MOD      = "MOD"
IR_NEG      = "NEG"
IR_POW      = "POW"

# Bitwise
IR_BAND     = "BAND"
IR_BOR      = "BOR"
IR_BXOR     = "BXOR"
IR_BNOT     = "BNOT"
IR_SHL      = "SHL"
IR_SHR      = "SHR"

# Comparison
IR_EQ       = "EQ"
IR_NEQ      = "NEQ"
IR_LT       = "LT"
IR_GT       = "GT"
IR_LTE      = "LTE"
IR_GTE      = "GTE"

# Logical
IR_AND      = "AND"
IR_OR       = "OR"
IR_NOT      = "NOT"

# Control flow
IR_JMP      = "JMP"
IR_JMP_IF   = "JMP_IF"
IR_JMP_NIF  = "JMP_NIF"
IR_CALL     = "CALL"
IR_RET      = "RET"
IR_NOP      = "NOP"
IR_HALT     = "HALT"

# Memory
IR_LOAD     = "LOAD"
IR_STORE    = "STORE"
IR_ALLOC    = "ALLOC"
IR_FREE     = "FREE"
IR_LOAD_FIELD   = "LOAD_FIELD"
IR_STORE_FIELD  = "STORE_FIELD"
IR_LOAD_INDEX   = "LOAD_INDEX"
IR_STORE_INDEX  = "STORE_INDEX"

# Constants
IR_CONST_INT    = "CONST_INT"
IR_CONST_FLOAT  = "CONST_FLOAT"
IR_CONST_STR    = "CONST_STR"
IR_CONST_BOOL   = "CONST_BOOL"
IR_CONST_NIL    = "CONST_NIL"

# SSA
IR_PHI      = "PHI"
IR_MOVE     = "MOVE"
IR_CAST     = "CAST"

# Object operations
IR_NEW_ARRAY    = "NEW_ARRAY"
IR_NEW_STRUCT   = "NEW_STRUCT"
IR_NEW_CLOSURE  = "NEW_CLOSURE"

# ---- IR Instruction ----

fn ir_instr(op: string, dest: any, src1: any, src2: any) -> any {
  return {
    "op": op,
    "dest": dest,
    "src1": src1,
    "src2": src2,
    "label": nil,
    "block_id": 0,
    "line": 0,
    "comment": ""
  }
}

fn ir_const(dest: any, op: string, value: any) -> any {
  instr = ir_instr(op, dest, value, nil)
  return instr
}

fn ir_jump(target_label: string) -> any {
  instr = ir_instr(IR_JMP, nil, nil, nil)
  instr["label"] = target_label
  return instr
}

fn ir_jump_if(condition: any, target_label: string) -> any {
  instr = ir_instr(IR_JMP_IF, nil, condition, nil)
  instr["label"] = target_label
  return instr
}

fn ir_jump_nif(condition: any, target_label: string) -> any {
  instr = ir_instr(IR_JMP_NIF, nil, condition, nil)
  instr["label"] = target_label
  return instr
}

fn ir_call(dest: any, func: any, args: array) -> any {
  instr = ir_instr(IR_CALL, dest, func, nil)
  instr["args"] = args
  return instr
}

fn ir_ret(value: any) -> any {
  return ir_instr(IR_RET, nil, value, nil)
}

fn ir_phi(dest: any, sources: array) -> any {
  instr = ir_instr(IR_PHI, dest, nil, nil)
  instr["sources"] = sources  # [{value, block_id}, ...]
  return instr
}

# ---- Basic Block ----

fn ir_basic_block(id: i32, label: string) -> any {
  return {
    "id": id,
    "label": label,
    "instructions": [],
    "predecessors": [],
    "successors": [],
    "dominators": [],
    "phi_nodes": [],
    "is_entry": false,
    "is_exit": false,
    "loop_header": false,
    "loop_depth": 0
  }
}

fn bb_add_instr(bb: any, instr: any) -> any {
  instr["block_id"] = bb["id"]
  push(bb["instructions"], instr)
  return bb
}

fn bb_add_predecessor(bb: any, pred_id: i32) -> any {
  push(bb["predecessors"], pred_id)
  return bb
}

fn bb_add_successor(bb: any, succ_id: i32) -> any {
  push(bb["successors"], succ_id)
  return bb
}

fn bb_is_terminated(bb: any) -> bool {
  instrs = bb["instructions"]
  if length(instrs) == 0 {
    return false
  }
  last = instrs[length(instrs) - 1]
  return last["op"] == IR_JMP or last["op"] == IR_JMP_IF or
         last["op"] == IR_JMP_NIF or last["op"] == IR_RET or
         last["op"] == IR_HALT
}

# ---- IR Function ----

fn ir_function(name: string, params: array, return_type: any) -> any {
  entry_block = ir_basic_block(0, name + "_entry")
  entry_block["is_entry"] = true

  return {
    "name": name,
    "params": params,
    "return_type": return_type,
    "blocks": [entry_block],
    "block_count": 1,
    "register_count": 0,
    "local_count": 0,
    "constants": [],
    "labels": {},
    "is_entry_point": false
  }
}

fn ir_func_new_block(func: any, label: string) -> any {
  id = func["block_count"]
  func["block_count"] = id + 1
  bb = ir_basic_block(id, label)
  push(func["blocks"], bb)
  return bb
}

fn ir_func_new_register(func: any) -> string {
  id = func["register_count"]
  func["register_count"] = id + 1
  return "%r" + to_string(id)
}

fn ir_func_new_local(func: any, name: string) -> string {
  func["local_count"] = func["local_count"] + 1
  return "%" + name
}

fn ir_func_add_constant(func: any, value: any) -> i32 {
  idx = length(func["constants"])
  push(func["constants"], value)
  return idx
}

fn ir_func_get_block(func: any, id: i32) -> any {
  if id >= 0 and id < length(func["blocks"]) {
    return func["blocks"][id]
  }
  return nil
}

# ---- IR Module ----

fn ir_module(name: string) -> any {
  return {
    "name": name,
    "functions": [],
    "globals": [],
    "type_defs": [],
    "string_pool": [],
    "entry_function": nil
  }
}

fn ir_module_add_function(mod: any, func: any) -> any {
  push(mod["functions"], func)
  if func["is_entry_point"] {
    mod["entry_function"] = func["name"]
  }
  return mod
}

fn ir_module_add_global(mod: any, name: string, type_info: any, value: any) -> any {
  push(mod["globals"], { "name": name, "type": type_info, "value": value })
  return mod
}

fn ir_module_intern_string(mod: any, s: string) -> i32 {
  # Check if already interned
  i = 0
  while i < length(mod["string_pool"]) {
    if mod["string_pool"][i] == s {
      return i
    }
    i = i + 1
  }
  idx = length(mod["string_pool"])
  push(mod["string_pool"], s)
  return idx
}

# ---- IR Pretty Printer ----

fn ir_instr_to_string(instr: any) -> string {
  op = instr["op"]
  result = ""

  if instr["dest"] != nil {
    result = result + instr["dest"] + " = "
  }

  result = result + op

  if instr["src1"] != nil {
    result = result + " " + to_string(instr["src1"])
  }
  if instr["src2"] != nil {
    result = result + ", " + to_string(instr["src2"])
  }
  if instr["label"] != nil {
    result = result + " @" + instr["label"]
  }
  if instr["args"] != nil {
    result = result + "("
    i = 0
    while i < length(instr["args"]) {
      if i > 0 { result = result + ", " }
      result = result + to_string(instr["args"][i])
      i = i + 1
    }
    result = result + ")"
  }
  if instr["comment"] != "" {
    result = result + "  # " + instr["comment"]
  }

  return result
}

fn ir_block_to_string(bb: any) -> string {
  result = bb["label"] + ":"
  if bb["is_entry"] { result = result + " (entry)" }
  if bb["is_exit"] { result = result + " (exit)" }
  result = result + "\n"

  i = 0
  while i < length(bb["instructions"]) {
    result = result + "  " + ir_instr_to_string(bb["instructions"][i]) + "\n"
    i = i + 1
  }

  return result
}

fn ir_function_to_string(func: any) -> string {
  result = "fn " + func["name"] + "("
  i = 0
  while i < length(func["params"]) {
    if i > 0 { result = result + ", " }
    result = result + func["params"][i]
    i = i + 1
  }
  result = result + ")"
  if func["return_type"] != nil {
    result = result + " -> " + to_string(func["return_type"])
  }
  result = result + " {\n"

  i = 0
  while i < length(func["blocks"]) {
    result = result + ir_block_to_string(func["blocks"][i])
    i = i + 1
  }

  result = result + "}\n"
  return result
}

fn ir_module_to_string(mod: any) -> string {
  result = "# IR Module: " + mod["name"] + "\n\n"

  # Globals
  i = 0
  while i < length(mod["globals"]) {
    g = mod["globals"][i]
    result = result + "global " + g["name"] + " = " + to_string(g["value"]) + "\n"
    i = i + 1
  }
  if length(mod["globals"]) > 0 {
    result = result + "\n"
  }

  # Functions
  i = 0
  while i < length(mod["functions"]) {
    result = result + ir_function_to_string(mod["functions"][i]) + "\n"
    i = i + 1
  }

  return result
}

# ---- IR Statistics ----

fn ir_module_stats(mod: any) -> any {
  total_blocks = 0
  total_instrs = 0
  total_functions = length(mod["functions"])

  i = 0
  while i < total_functions {
    func = mod["functions"][i]
    total_blocks = total_blocks + length(func["blocks"])
    j = 0
    while j < length(func["blocks"]) {
      total_instrs = total_instrs + length(func["blocks"][j]["instructions"])
      j = j + 1
    }
    i = i + 1
  }

  return {
    "functions": total_functions,
    "blocks": total_blocks,
    "instructions": total_instrs,
    "globals": length(mod["globals"]),
    "strings": length(mod["string_pool"])
  }
}

# ================================================================
# FreeLang v4 Core - Compiler (AST -> IR)
# Translates typed AST into three-address IR code
# Performance target: R5 < 200ms (O0), < 500ms (O3)
# ================================================================

# ---- Compiler State ----

fn create_compiler(opt_level: i32) -> any {
  return {
    "module": ir_module("main"),
    "current_function": nil,
    "current_block": nil,
    "scope_stack": [{}],
    "scope_depth": 0,
    "label_counter": 0,
    "break_labels": [],
    "continue_labels": [],
    "opt_level": opt_level,  # 0=none, 1=basic, 2=standard, 3=aggressive
    "errors": [],
    "error_count": 0,
    "start_time": 0,
    "elapsed_ms": 0,
    "stats": {
      "functions_compiled": 0,
      "instructions_generated": 0,
      "constants_folded": 0,
      "dead_code_eliminated": 0,
      "branches_optimized": 0
    }
  }
}

# ---- Label Generation ----

fn compiler_new_label(c: any, prefix: string) -> string {
  c["label_counter"] = c["label_counter"] + 1
  return prefix + "_" + to_string(c["label_counter"])
}

# ---- Scope Management ----

fn compiler_push_scope(c: any) -> any {
  push(c["scope_stack"], {})
  c["scope_depth"] = c["scope_depth"] + 1
  return c
}

fn compiler_pop_scope(c: any) -> any {
  pop(c["scope_stack"])
  c["scope_depth"] = c["scope_depth"] - 1
  return c
}

fn compiler_define_var(c: any, name: string, register: string) -> any {
  c["scope_stack"][c["scope_depth"]][name] = register
  return c
}

fn compiler_lookup_var(c: any, name: string) -> string {
  depth = c["scope_depth"]
  while depth >= 0 {
    reg = c["scope_stack"][depth][name]
    if reg != nil {
      return reg
    }
    depth = depth - 1
  }
  return nil
}

# ---- IR Emission Helpers ----

fn emit(c: any, instr: any) -> any {
  if c["current_block"] != nil {
    bb_add_instr(c["current_block"], instr)
    c["stats"]["instructions_generated"] = c["stats"]["instructions_generated"] + 1
  }
  return c
}

fn emit_to_block(c: any, block: any, instr: any) -> any {
  bb_add_instr(block, instr)
  c["stats"]["instructions_generated"] = c["stats"]["instructions_generated"] + 1
  return c
}

fn new_reg(c: any) -> string {
  return ir_func_new_register(c["current_function"])
}

fn set_block(c: any, block: any) -> any {
  c["current_block"] = block
  return c
}

fn new_block(c: any, label: string) -> any {
  return ir_func_new_block(c["current_function"], label)
}

# ---- Main Compile Entry ----

fn compile(ast: any, opt_level: i32) -> any {
  c = create_compiler(opt_level)
  c["start_time"] = time_now()

  # Compile all top-level declarations
  compile_program(c, ast)

  # Run optimization passes if requested
  if opt_level >= 1 {
    optimize_module(c)
  }

  c["elapsed_ms"] = time_now() - c["start_time"]

  return {
    "module": c["module"],
    "errors": c["errors"],
    "error_count": c["error_count"],
    "elapsed_ms": c["elapsed_ms"],
    "stats": c["stats"]
  }
}

fn compile_program(c: any, program: any) -> any {
  i = 0
  while i < length(program["declarations"]) {
    compile_declaration(c, program["declarations"][i])
    i = i + 1
  }
  return c
}

# ---- Declaration Compilation ----

fn compile_declaration(c: any, decl: any) -> any {
  kind = decl["kind"]

  match kind {
    AST_FN_DECL     => { return compile_fn_decl(c, decl) },
    AST_LET_DECL    => { return compile_let_decl(c, decl) },
    AST_CONST_DECL  => { return compile_const_decl(c, decl) },
    AST_STRUCT_DECL => { return compile_struct_decl(c, decl) },
    AST_EXPR_STMT   => { return compile_expr(c, decl["expr"]) },
    AST_RETURN_STMT => { return compile_return_stmt(c, decl) },
    AST_ASSIGNMENT  => { return compile_assignment(c, decl) },
    AST_COMPOUND_ASSIGN => { return compile_compound_assign(c, decl) },
    AST_BLOCK       => { return compile_block(c, decl) },
    _ => { return nil }
  }
}

fn compile_fn_decl(c: any, decl: any) -> any {
  # Create IR function
  params = []
  i = 0
  while i < length(decl["params"]) {
    push(params, decl["params"][i]["name"])
    i = i + 1
  }

  func = ir_function(decl["name"], params, decl["return_type"])

  # Check if this is main
  if decl["name"] == "main" {
    func["is_entry_point"] = true
  }

  saved_func = c["current_function"]
  saved_block = c["current_block"]

  c["current_function"] = func
  c["current_block"] = func["blocks"][0]  # entry block

  c["stats"]["functions_compiled"] = c["stats"]["functions_compiled"] + 1

  compiler_push_scope(c)

  # Define parameters as local variables
  i = 0
  while i < length(decl["params"]) {
    param_name = decl["params"][i]["name"]
    reg = ir_func_new_local(func, param_name)
    compiler_define_var(c, param_name, reg)
    i = i + 1
  }

  # Compile body
  if decl["body"] != nil {
    result = compile_block(c, decl["body"])

    # Ensure function ends with return
    if not bb_is_terminated(c["current_block"]) {
      if result != nil {
        emit(c, ir_ret(result))
      } else {
        emit(c, ir_ret(nil))
      }
    }
  }

  compiler_pop_scope(c)

  # Add function to module
  ir_module_add_function(c["module"], func)

  c["current_function"] = saved_func
  c["current_block"] = saved_block

  return nil
}

fn compile_let_decl(c: any, decl: any) -> any {
  reg = ir_func_new_local(c["current_function"], decl["name"])
  compiler_define_var(c, decl["name"], reg)

  if decl["value"] != nil {
    value_reg = compile_expr(c, decl["value"])
    emit(c, ir_instr(IR_STORE, reg, value_reg, nil))
  } else {
    emit(c, ir_const(reg, IR_CONST_NIL, nil))
  }

  return reg
}

fn compile_const_decl(c: any, decl: any) -> any {
  value_reg = compile_expr(c, decl["value"])
  compiler_define_var(c, decl["name"], value_reg)
  return value_reg
}

fn compile_struct_decl(c: any, decl: any) -> any {
  # Register struct type - no code generation needed
  return nil
}

fn compile_return_stmt(c: any, stmt: any) -> any {
  if stmt["value"] != nil {
    value_reg = compile_expr(c, stmt["value"])
    emit(c, ir_ret(value_reg))
  } else {
    emit(c, ir_ret(nil))
  }
  return nil
}

fn compile_assignment(c: any, stmt: any) -> any {
  value_reg = compile_expr(c, stmt["value"])

  target = stmt["target"]
  if target["kind"] == AST_IDENT {
    var_reg = compiler_lookup_var(c, target["name"])
    if var_reg != nil {
      emit(c, ir_instr(IR_STORE, var_reg, value_reg, nil))
    }
  } else if target["kind"] == AST_FIELD_ACCESS {
    obj_reg = compile_expr(c, target["object"])
    instr = ir_instr(IR_STORE_FIELD, nil, obj_reg, value_reg)
    instr["comment"] = target["field"]
    emit(c, instr)
  } else if target["kind"] == AST_INDEX {
    obj_reg = compile_expr(c, target["object"])
    idx_reg = compile_expr(c, target["index"])
    emit(c, ir_instr(IR_STORE_INDEX, nil, obj_reg, value_reg))
  }

  return nil
}

fn compile_compound_assign(c: any, stmt: any) -> any {
  target_reg = compile_expr(c, stmt["target"])
  value_reg = compile_expr(c, stmt["value"])
  result_reg = new_reg(c)

  op = stmt["op"]
  ir_op = IR_ADD
  match op {
    "+=" => { ir_op = IR_ADD },
    "-=" => { ir_op = IR_SUB },
    "*=" => { ir_op = IR_MUL },
    "/=" => { ir_op = IR_DIV },
    "%=" => { ir_op = IR_MOD },
    _ => { ir_op = IR_ADD }
  }

  emit(c, ir_instr(ir_op, result_reg, target_reg, value_reg))

  # Store back
  target = stmt["target"]
  if target["kind"] == AST_IDENT {
    var_reg = compiler_lookup_var(c, target["name"])
    if var_reg != nil {
      emit(c, ir_instr(IR_STORE, var_reg, result_reg, nil))
    }
  }

  return result_reg
}

fn compile_block(c: any, block: any) -> any {
  if block == nil {
    return nil
  }

  compiler_push_scope(c)
  result = nil

  i = 0
  while i < length(block["statements"]) {
    result = compile_declaration(c, block["statements"][i])
    i = i + 1
  }

  compiler_pop_scope(c)
  return result
}

# ---- Expression Compilation ----

fn compile_expr(c: any, expr: any) -> string {
  if expr == nil {
    return nil
  }
  kind = expr["kind"]

  match kind {
    AST_LITERAL      => { return compile_literal(c, expr) },
    AST_IDENT        => { return compile_ident(c, expr) },
    AST_BINARY       => { return compile_binary(c, expr) },
    AST_UNARY        => { return compile_unary(c, expr) },
    AST_CALL         => { return compile_call(c, expr) },
    AST_METHOD_CALL  => { return compile_method_call(c, expr) },
    AST_FIELD_ACCESS => { return compile_field_access(c, expr) },
    AST_INDEX        => { return compile_index(c, expr) },
    AST_IF_EXPR      => { return compile_if_expr(c, expr) },
    AST_MATCH_EXPR   => { return compile_match_expr(c, expr) },
    AST_WHILE_EXPR   => { return compile_while_expr(c, expr) },
    AST_FOR_EXPR     => { return compile_for_expr(c, expr) },
    AST_LOOP_EXPR    => { return compile_loop_expr(c, expr) },
    AST_BLOCK        => { return compile_block(c, expr) },
    AST_ARRAY_LITERAL => { return compile_array_literal(c, expr) },
    AST_CLOSURE      => { return compile_closure(c, expr) },
    _ => { return nil }
  }
}

fn compile_literal(c: any, expr: any) -> string {
  reg = new_reg(c)

  match expr["lit_type"] {
    "integer" => {
      # Constant folding at O1+
      emit(c, ir_const(reg, IR_CONST_INT, expr["value"]))
    },
    "float" => {
      emit(c, ir_const(reg, IR_CONST_FLOAT, expr["value"]))
    },
    "string" => {
      str_idx = ir_module_intern_string(c["module"], expr["value"])
      emit(c, ir_const(reg, IR_CONST_STR, str_idx))
    },
    "char" => {
      emit(c, ir_const(reg, IR_CONST_STR, expr["value"]))
    },
    "bool" => {
      emit(c, ir_const(reg, IR_CONST_BOOL, expr["value"]))
    },
    "nil" => {
      emit(c, ir_const(reg, IR_CONST_NIL, nil))
    },
    _ => {
      emit(c, ir_const(reg, IR_CONST_NIL, nil))
    }
  }

  return reg
}

fn compile_ident(c: any, expr: any) -> string {
  var_reg = compiler_lookup_var(c, expr["name"])
  if var_reg != nil {
    result = new_reg(c)
    emit(c, ir_instr(IR_LOAD, result, var_reg, nil))
    return result
  }
  # Unknown - emit as load by name
  result = new_reg(c)
  instr = ir_instr(IR_LOAD, result, expr["name"], nil)
  instr["comment"] = "global lookup: " + expr["name"]
  emit(c, instr)
  return result
}

fn compile_binary(c: any, expr: any) -> string {
  # Constant folding (O1+)
  if c["opt_level"] >= 1 {
    folded = try_constant_fold(c, expr)
    if folded != nil {
      c["stats"]["constants_folded"] = c["stats"]["constants_folded"] + 1
      return folded
    }
  }

  # Short-circuit evaluation for && and ||
  if expr["op"] == "&&" {
    return compile_short_circuit_and(c, expr)
  }
  if expr["op"] == "||" {
    return compile_short_circuit_or(c, expr)
  }

  left_reg = compile_expr(c, expr["left"])
  right_reg = compile_expr(c, expr["right"])
  result_reg = new_reg(c)

  ir_op = op_to_ir(expr["op"])
  emit(c, ir_instr(ir_op, result_reg, left_reg, right_reg))

  return result_reg
}

fn compile_short_circuit_and(c: any, expr: any) -> string {
  result_reg = new_reg(c)
  right_label = compiler_new_label(c, "and_right")
  end_label = compiler_new_label(c, "and_end")

  left_reg = compile_expr(c, expr["left"])
  emit(c, ir_jump_nif(left_reg, end_label))

  right_block = new_block(c, right_label)
  set_block(c, right_block)
  right_reg = compile_expr(c, expr["right"])
  emit(c, ir_instr(IR_MOVE, result_reg, right_reg, nil))
  emit(c, ir_jump(end_label))

  end_block = new_block(c, end_label)
  set_block(c, end_block)

  c["stats"]["branches_optimized"] = c["stats"]["branches_optimized"] + 1
  return result_reg
}

fn compile_short_circuit_or(c: any, expr: any) -> string {
  result_reg = new_reg(c)
  right_label = compiler_new_label(c, "or_right")
  end_label = compiler_new_label(c, "or_end")

  left_reg = compile_expr(c, expr["left"])
  emit(c, ir_jump_if(left_reg, end_label))

  right_block = new_block(c, right_label)
  set_block(c, right_block)
  right_reg = compile_expr(c, expr["right"])
  emit(c, ir_instr(IR_MOVE, result_reg, right_reg, nil))
  emit(c, ir_jump(end_label))

  end_block = new_block(c, end_label)
  set_block(c, end_block)

  c["stats"]["branches_optimized"] = c["stats"]["branches_optimized"] + 1
  return result_reg
}

fn compile_unary(c: any, expr: any) -> string {
  operand_reg = compile_expr(c, expr["operand"])
  result_reg = new_reg(c)

  match expr["op"] {
    "-" => { emit(c, ir_instr(IR_NEG, result_reg, operand_reg, nil)) },
    "!" => { emit(c, ir_instr(IR_NOT, result_reg, operand_reg, nil)) },
    "~" => { emit(c, ir_instr(IR_BNOT, result_reg, operand_reg, nil)) },
    "&" => { emit(c, ir_instr(IR_LOAD, result_reg, operand_reg, nil)) },
    _ => { emit(c, ir_instr(IR_MOVE, result_reg, operand_reg, nil)) }
  }

  return result_reg
}

fn compile_call(c: any, expr: any) -> string {
  callee_reg = compile_expr(c, expr["callee"])

  arg_regs = []
  i = 0
  while i < length(expr["args"]) {
    push(arg_regs, compile_expr(c, expr["args"][i]))
    i = i + 1
  }

  result_reg = new_reg(c)
  emit(c, ir_call(result_reg, callee_reg, arg_regs))

  return result_reg
}

fn compile_method_call(c: any, expr: any) -> string {
  obj_reg = compile_expr(c, expr["object"])

  arg_regs = [obj_reg]  # self is first arg
  i = 0
  while i < length(expr["args"]) {
    push(arg_regs, compile_expr(c, expr["args"][i]))
    i = i + 1
  }

  result_reg = new_reg(c)
  method_name = expr["method"]
  emit(c, ir_call(result_reg, method_name, arg_regs))

  return result_reg
}

fn compile_field_access(c: any, expr: any) -> string {
  obj_reg = compile_expr(c, expr["object"])
  result_reg = new_reg(c)

  instr = ir_instr(IR_LOAD_FIELD, result_reg, obj_reg, nil)
  instr["comment"] = expr["field"]
  emit(c, instr)

  return result_reg
}

fn compile_index(c: any, expr: any) -> string {
  obj_reg = compile_expr(c, expr["object"])
  idx_reg = compile_expr(c, expr["index"])
  result_reg = new_reg(c)

  emit(c, ir_instr(IR_LOAD_INDEX, result_reg, obj_reg, idx_reg))

  return result_reg
}

fn compile_if_expr(c: any, expr: any) -> string {
  result_reg = new_reg(c)
  then_label = compiler_new_label(c, "then")
  else_label = compiler_new_label(c, "else")
  end_label = compiler_new_label(c, "if_end")

  cond_reg = compile_expr(c, expr["condition"])

  if expr["else_block"] != nil {
    emit(c, ir_jump_nif(cond_reg, else_label))
  } else {
    emit(c, ir_jump_nif(cond_reg, end_label))
  }

  # Then block
  then_block = new_block(c, then_label)
  set_block(c, then_block)
  then_result = compile_block(c, expr["then_block"])
  if then_result != nil {
    emit(c, ir_instr(IR_MOVE, result_reg, then_result, nil))
  }
  emit(c, ir_jump(end_label))

  # Else block
  if expr["else_block"] != nil {
    else_block = new_block(c, else_label)
    set_block(c, else_block)
    else_result = nil
    if expr["else_block"]["kind"] == AST_IF_EXPR {
      else_result = compile_expr(c, expr["else_block"])
    } else {
      else_result = compile_block(c, expr["else_block"])
    }
    if else_result != nil {
      emit(c, ir_instr(IR_MOVE, result_reg, else_result, nil))
    }
    emit(c, ir_jump(end_label))
  }

  # End block
  end_block = new_block(c, end_label)
  set_block(c, end_block)

  return result_reg
}

fn compile_match_expr(c: any, expr: any) -> string {
  result_reg = new_reg(c)
  end_label = compiler_new_label(c, "match_end")

  subject_reg = compile_expr(c, expr["subject"])

  i = 0
  while i < length(expr["arms"]) {
    arm = expr["arms"][i]
    next_label = compiler_new_label(c, "match_arm_" + to_string(i))
    body_label = compiler_new_label(c, "match_body_" + to_string(i))

    # Pattern matching (simplified: compare values)
    pattern = arm["pattern"]
    if pattern["kind"] == AST_PAT_LITERAL {
      cmp_reg = new_reg(c)
      pat_reg = new_reg(c)
      emit(c, ir_const(pat_reg, IR_CONST_INT, pattern["value"]))
      emit(c, ir_instr(IR_EQ, cmp_reg, subject_reg, pat_reg))
      emit(c, ir_jump_nif(cmp_reg, next_label))
    } else if pattern["kind"] == AST_PAT_WILDCARD {
      # Always matches - no comparison needed
    } else if pattern["kind"] == AST_PAT_IDENT {
      # Bind to variable
      compiler_define_var(c, pattern["name"], subject_reg)
    }

    # Guard
    if arm["guard"] != nil {
      guard_reg = compile_expr(c, arm["guard"])
      emit(c, ir_jump_nif(guard_reg, next_label))
    }

    # Body
    body_block = new_block(c, body_label)
    set_block(c, body_block)
    body_result = compile_expr(c, arm["body"])
    if body_result != nil {
      emit(c, ir_instr(IR_MOVE, result_reg, body_result, nil))
    }
    emit(c, ir_jump(end_label))

    # Next arm
    next_block = new_block(c, next_label)
    set_block(c, next_block)

    i = i + 1
  }

  # End
  end_block = new_block(c, end_label)
  set_block(c, end_block)

  return result_reg
}

fn compile_while_expr(c: any, expr: any) -> string {
  cond_label = compiler_new_label(c, "while_cond")
  body_label = compiler_new_label(c, "while_body")
  end_label = compiler_new_label(c, "while_end")

  push(c["break_labels"], end_label)
  push(c["continue_labels"], cond_label)

  emit(c, ir_jump(cond_label))

  # Condition
  cond_block = new_block(c, cond_label)
  set_block(c, cond_block)
  cond_reg = compile_expr(c, expr["condition"])
  emit(c, ir_jump_nif(cond_reg, end_label))

  # Body
  body_block = new_block(c, body_label)
  set_block(c, body_block)
  compile_block(c, expr["body"])
  emit(c, ir_jump(cond_label))

  # End
  end_block = new_block(c, end_label)
  set_block(c, end_block)

  pop(c["break_labels"])
  pop(c["continue_labels"])

  return nil
}

fn compile_for_expr(c: any, expr: any) -> string {
  init_label = compiler_new_label(c, "for_init")
  cond_label = compiler_new_label(c, "for_cond")
  body_label = compiler_new_label(c, "for_body")
  end_label = compiler_new_label(c, "for_end")

  push(c["break_labels"], end_label)
  push(c["continue_labels"], cond_label)

  compiler_push_scope(c)

  # Initialize iterator
  iter_reg = compile_expr(c, expr["iterable"])
  idx_reg = new_reg(c)
  emit(c, ir_const(idx_reg, IR_CONST_INT, 0))
  compiler_define_var(c, expr["variable"], idx_reg)

  emit(c, ir_jump(cond_label))

  # Condition (simplified: index < length)
  cond_block = new_block(c, cond_label)
  set_block(c, cond_block)
  len_reg = new_reg(c)
  cmp_reg = new_reg(c)
  instr = ir_call(len_reg, "length", [iter_reg])
  emit(c, instr)
  emit(c, ir_instr(IR_LT, cmp_reg, idx_reg, len_reg))
  emit(c, ir_jump_nif(cmp_reg, end_label))

  # Body
  body_block = new_block(c, body_label)
  set_block(c, body_block)

  # Load current element
  elem_reg = new_reg(c)
  emit(c, ir_instr(IR_LOAD_INDEX, elem_reg, iter_reg, idx_reg))
  compiler_define_var(c, expr["variable"], elem_reg)

  compile_block(c, expr["body"])

  # Increment index
  one_reg = new_reg(c)
  emit(c, ir_const(one_reg, IR_CONST_INT, 1))
  emit(c, ir_instr(IR_ADD, idx_reg, idx_reg, one_reg))
  emit(c, ir_jump(cond_label))

  # End
  end_block = new_block(c, end_label)
  set_block(c, end_block)

  compiler_pop_scope(c)
  pop(c["break_labels"])
  pop(c["continue_labels"])

  return nil
}

fn compile_loop_expr(c: any, expr: any) -> string {
  body_label = compiler_new_label(c, "loop_body")
  end_label = compiler_new_label(c, "loop_end")

  push(c["break_labels"], end_label)
  push(c["continue_labels"], body_label)

  emit(c, ir_jump(body_label))

  body_block = new_block(c, body_label)
  set_block(c, body_block)
  compile_block(c, expr["body"])
  emit(c, ir_jump(body_label))

  end_block = new_block(c, end_label)
  set_block(c, end_block)

  pop(c["break_labels"])
  pop(c["continue_labels"])

  return nil
}

fn compile_array_literal(c: any, expr: any) -> string {
  result_reg = new_reg(c)
  size_reg = new_reg(c)
  emit(c, ir_const(size_reg, IR_CONST_INT, length(expr["elements"])))

  instr = ir_instr(IR_NEW_ARRAY, result_reg, size_reg, nil)
  emit(c, instr)

  i = 0
  while i < length(expr["elements"]) {
    elem_reg = compile_expr(c, expr["elements"][i])
    idx_reg = new_reg(c)
    emit(c, ir_const(idx_reg, IR_CONST_INT, i))
    emit(c, ir_instr(IR_STORE_INDEX, nil, result_reg, elem_reg))
    i = i + 1
  }

  return result_reg
}

fn compile_closure(c: any, expr: any) -> string {
  # Compile closure as a nested function
  closure_name = compiler_new_label(c, "closure")

  params = []
  i = 0
  while i < length(expr["params"]) {
    push(params, expr["params"][i]["name"])
    i = i + 1
  }

  closure_func = ir_function(closure_name, params, nil)

  saved_func = c["current_function"]
  saved_block = c["current_block"]

  c["current_function"] = closure_func
  c["current_block"] = closure_func["blocks"][0]

  compiler_push_scope(c)

  i = 0
  while i < length(expr["params"]) {
    p = expr["params"][i]
    reg = ir_func_new_local(closure_func, p["name"])
    compiler_define_var(c, p["name"], reg)
    i = i + 1
  }

  body_result = compile_expr(c, expr["body"])
  if body_result != nil {
    emit(c, ir_ret(body_result))
  } else {
    emit(c, ir_ret(nil))
  }

  compiler_pop_scope(c)

  ir_module_add_function(c["module"], closure_func)

  c["current_function"] = saved_func
  c["current_block"] = saved_block

  # Create closure object
  result_reg = new_reg(c)
  emit(c, ir_instr(IR_NEW_CLOSURE, result_reg, closure_name, nil))

  return result_reg
}

# ---- Operator Mapping ----

fn op_to_ir(op: string) -> string {
  match op {
    "+"  => { return IR_ADD },
    "-"  => { return IR_SUB },
    "*"  => { return IR_MUL },
    "/"  => { return IR_DIV },
    "%"  => { return IR_MOD },
    "**" => { return IR_POW },
    "&"  => { return IR_BAND },
    "|"  => { return IR_BOR },
    "^"  => { return IR_BXOR },
    "<<" => { return IR_SHL },
    ">>" => { return IR_SHR },
    "==" => { return IR_EQ },
    "!=" => { return IR_NEQ },
    "<"  => { return IR_LT },
    ">"  => { return IR_GT },
    "<=" => { return IR_LTE },
    ">=" => { return IR_GTE },
    "&&" => { return IR_AND },
    "||" => { return IR_OR },
    _ => { return IR_NOP }
  }
}

# ---- Constant Folding (O1+ optimization) ----

fn try_constant_fold(c: any, expr: any) -> string {
  if expr["left"]["kind"] != AST_LITERAL or expr["right"]["kind"] != AST_LITERAL {
    return nil
  }
  if expr["left"]["lit_type"] != "integer" or expr["right"]["lit_type"] != "integer" {
    return nil
  }

  left_val = to_number(expr["left"]["value"])
  right_val = to_number(expr["right"]["value"])
  result_val = 0

  match expr["op"] {
    "+" => { result_val = left_val + right_val },
    "-" => { result_val = left_val - right_val },
    "*" => { result_val = left_val * right_val },
    "/" => {
      if right_val == 0 { return nil }
      result_val = left_val / right_val
    },
    "%" => {
      if right_val == 0 { return nil }
      result_val = left_val % right_val
    },
    _ => { return nil }
  }

  reg = new_reg(c)
  emit(c, ir_const(reg, IR_CONST_INT, result_val))
  return reg
}

# ---- Optimization Passes ----

fn optimize_module(c: any) -> any {
  mod = c["module"]

  if c["opt_level"] >= 1 {
    # Pass 1: Dead code elimination
    dead_code_elimination(c, mod)
  }

  if c["opt_level"] >= 2 {
    # Pass 2: Common subexpression elimination (stub)
    # Pass 3: Loop invariant code motion (stub)
  }

  if c["opt_level"] >= 3 {
    # Pass 4: Function inlining (stub)
    # Pass 5: Register coalescing (stub)
  }

  return c
}

fn dead_code_elimination(c: any, mod: any) -> any {
  i = 0
  while i < length(mod["functions"]) {
    func = mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      # Remove unreachable code after unconditional jumps/returns
      found_terminator = false
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]
        if found_terminator {
          # This instruction is dead
          c["stats"]["dead_code_eliminated"] = c["stats"]["dead_code_eliminated"] + 1
        }
        if instr["op"] == IR_JMP or instr["op"] == IR_RET or instr["op"] == IR_HALT {
          found_terminator = true
        }
        k = k + 1
      }
      j = j + 1
    }
    i = i + 1
  }
  return c
}

# ---- Compiler Report ----

fn compiler_report(result: any) -> any {
  return {
    "elapsed_ms": result["elapsed_ms"],
    "error_count": result["error_count"],
    "stats": result["stats"],
    "module_stats": ir_module_stats(result["module"]),
    "r5_o0_pass": result["elapsed_ms"] < 200,
    "r5_o3_pass": result["elapsed_ms"] < 500
  }
}

# ================================================================
# FreeLang v4 Core - Virtual Machine
# Stack-based bytecode VM with GC and runtime support
# Performance target: R4 Memory safety 0 leaks
# ================================================================

# ---- VM Configuration ----

VM_STACK_SIZE      = 65536
VM_CALL_STACK_SIZE = 1024
VM_HEAP_INITIAL    = 1048576  # 1MB
VM_GC_THRESHOLD    = 0.75

# ---- Value Types for VM ----

VAL_INT     = 0
VAL_FLOAT   = 1
VAL_BOOL    = 2
VAL_STRING  = 3
VAL_NIL     = 4
VAL_ARRAY   = 5
VAL_DICT    = 6
VAL_STRUCT  = 7
VAL_FN      = 8
VAL_CLOSURE = 9
VAL_REF     = 10

# ---- VM Value ----

fn vm_value(vtype: i32, data: any) -> any {
  return {
    "type": vtype,
    "data": data,
    "gc_mark": false,
    "gc_gen": 0
  }
}

fn vm_int(n: i32) -> any {
  return vm_value(VAL_INT, n)
}

fn vm_float(f: f64) -> any {
  return vm_value(VAL_FLOAT, f)
}

fn vm_bool(b: bool) -> any {
  return vm_value(VAL_BOOL, b)
}

fn vm_string(s: string) -> any {
  return vm_value(VAL_STRING, s)
}

fn vm_nil() -> any {
  return vm_value(VAL_NIL, nil)
}

fn vm_array(elements: array) -> any {
  return vm_value(VAL_ARRAY, elements)
}

fn vm_dict(entries: any) -> any {
  return vm_value(VAL_DICT, entries)
}

fn vm_struct(name: string, fields: any) -> any {
  return vm_value(VAL_STRUCT, { "name": name, "fields": fields })
}

fn vm_fn_val(name: string, code_offset: i32) -> any {
  return vm_value(VAL_FN, { "name": name, "offset": code_offset })
}

fn vm_closure_val(fn_val: any, captures: array) -> any {
  return vm_value(VAL_CLOSURE, { "fn": fn_val, "captures": captures })
}

# ---- VM State ----

fn create_vm() -> any {
  return {
    "stack": [],
    "sp": 0,                     # stack pointer
    "call_stack": [],
    "csp": 0,                    # call stack pointer
    "registers": {},
    "globals": {},
    "functions": {},             # name -> {code, params, ...}
    "ip": 0,                    # instruction pointer
    "running": false,
    "halted": false,

    # GC state
    "heap": [],
    "heap_size": 0,
    "gc_threshold": VM_GC_THRESHOLD,
    "gc_runs": 0,
    "gc_collected": 0,
    "gc_total_allocated": 0,

    # Metrics
    "instructions_executed": 0,
    "max_stack_depth": 0,
    "max_call_depth": 0,
    "start_time": 0,
    "elapsed_ms": 0,

    # Error handling
    "errors": [],
    "error_count": 0,
    "panic_value": nil
  }
}

# ---- Stack Operations ----

fn vm_push(vm: any, value: any) -> any {
  push(vm["stack"], value)
  vm["sp"] = vm["sp"] + 1
  if vm["sp"] > vm["max_stack_depth"] {
    vm["max_stack_depth"] = vm["sp"]
  }
  return vm
}

fn vm_pop(vm: any) -> any {
  if vm["sp"] <= 0 {
    vm_error(vm, "Stack underflow")
    return vm_nil()
  }
  vm["sp"] = vm["sp"] - 1
  return pop(vm["stack"])
}

fn vm_peek(vm: any) -> any {
  if vm["sp"] <= 0 {
    return vm_nil()
  }
  return vm["stack"][vm["sp"] - 1]
}

fn vm_peek_at(vm: any, offset: i32) -> any {
  idx = vm["sp"] - 1 - offset
  if idx < 0 {
    return vm_nil()
  }
  return vm["stack"][idx]
}

# ---- Call Stack ----

fn vm_push_frame(vm: any, fn_name: string, return_ip: i32, base_sp: i32) -> any {
  frame = {
    "fn_name": fn_name,
    "return_ip": return_ip,
    "base_sp": base_sp,
    "locals": {}
  }
  push(vm["call_stack"], frame)
  vm["csp"] = vm["csp"] + 1
  if vm["csp"] > vm["max_call_depth"] {
    vm["max_call_depth"] = vm["csp"]
  }
  return vm
}

fn vm_pop_frame(vm: any) -> any {
  if vm["csp"] <= 0 {
    vm_error(vm, "Call stack underflow")
    return nil
  }
  vm["csp"] = vm["csp"] - 1
  return pop(vm["call_stack"])
}

fn vm_current_frame(vm: any) -> any {
  if vm["csp"] <= 0 {
    return nil
  }
  return vm["call_stack"][vm["csp"] - 1]
}

# ---- Register / Variable Access ----

fn vm_set_local(vm: any, name: string, value: any) -> any {
  frame = vm_current_frame(vm)
  if frame != nil {
    frame["locals"][name] = value
  } else {
    vm["globals"][name] = value
  }
  return vm
}

fn vm_get_local(vm: any, name: string) -> any {
  frame = vm_current_frame(vm)
  if frame != nil {
    val = frame["locals"][name]
    if val != nil {
      return val
    }
  }
  return vm["globals"][name]
}

fn vm_set_register(vm: any, reg: string, value: any) -> any {
  vm["registers"][reg] = value
  return vm
}

fn vm_get_register(vm: any, reg: string) -> any {
  return vm["registers"][reg]
}

# ---- Function Registration ----

fn vm_register_function(vm: any, name: string, code: array, params: array) -> any {
  vm["functions"][name] = {
    "name": name,
    "code": code,
    "params": params,
    "code_offset": length(code)
  }
  return vm
}

fn vm_register_native(vm: any, name: string, handler: any) -> any {
  vm["functions"][name] = {
    "name": name,
    "native": true,
    "handler": handler,
    "params": []
  }
  return vm
}

# ---- IR Instruction Execution ----

fn vm_execute_module(vm: any, mod: any) -> any {
  vm["running"] = true
  vm["start_time"] = time_now()

  # Register all functions
  i = 0
  while i < length(mod["functions"]) {
    func = mod["functions"][i]
    vm_register_function(vm, func["name"], func["blocks"], func["params"])
    i = i + 1
  }

  # Set globals
  i = 0
  while i < length(mod["globals"]) {
    g = mod["globals"][i]
    vm["globals"][g["name"]] = g["value"]
    i = i + 1
  }

  # Execute entry function
  if mod["entry_function"] != nil {
    vm_call_function(vm, mod["entry_function"], [])
  }

  vm["elapsed_ms"] = time_now() - vm["start_time"]
  return vm
}

fn vm_call_function(vm: any, name: string, args: array) -> any {
  func = vm["functions"][name]
  if func == nil {
    vm_error(vm, "Undefined function: " + name)
    return vm_nil()
  }

  # Check for native function
  if func["native"] == true {
    return func["handler"](vm, args)
  }

  # Push call frame
  vm_push_frame(vm, name, vm["ip"], vm["sp"])

  # Bind parameters
  i = 0
  while i < length(func["params"]) and i < length(args) {
    vm_set_local(vm, func["params"][i], args[i])
    i = i + 1
  }

  # Execute blocks
  j = 0
  while j < length(func["code"]) and vm["running"] {
    block = func["code"][j]
    result = vm_execute_block(vm, block)
    if result != nil {
      # Return value found
      frame = vm_pop_frame(vm)
      return result
    }
    j = j + 1
  }

  frame = vm_pop_frame(vm)
  return vm_nil()
}

fn vm_execute_block(vm: any, block: any) -> any {
  i = 0
  while i < length(block["instructions"]) and vm["running"] {
    instr = block["instructions"][i]
    result = vm_execute_instr(vm, instr)
    vm["instructions_executed"] = vm["instructions_executed"] + 1

    if instr["op"] == IR_RET {
      return result
    }

    # GC check
    vm["gc_total_allocated"] = vm["gc_total_allocated"] + 1
    if vm["gc_total_allocated"] % 10000 == 0 {
      vm_gc_maybe_collect(vm)
    }

    i = i + 1
  }
  return nil
}

fn vm_execute_instr(vm: any, instr: any) -> any {
  op = instr["op"]
  dest = instr["dest"]
  src1 = instr["src1"]
  src2 = instr["src2"]

  match op {
    # Constants
    IR_CONST_INT => {
      vm_set_register(vm, dest, vm_int(src1))
    },
    IR_CONST_FLOAT => {
      vm_set_register(vm, dest, vm_float(src1))
    },
    IR_CONST_STR => {
      vm_set_register(vm, dest, vm_string(to_string(src1)))
    },
    IR_CONST_BOOL => {
      vm_set_register(vm, dest, vm_bool(src1))
    },
    IR_CONST_NIL => {
      vm_set_register(vm, dest, vm_nil())
    },

    # Arithmetic
    IR_ADD => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      if a != nil and b != nil {
        if a["type"] == VAL_INT and b["type"] == VAL_INT {
          vm_set_register(vm, dest, vm_int(a["data"] + b["data"]))
        } else if a["type"] == VAL_FLOAT or b["type"] == VAL_FLOAT {
          vm_set_register(vm, dest, vm_float(to_float(a["data"]) + to_float(b["data"])))
        } else if a["type"] == VAL_STRING {
          vm_set_register(vm, dest, vm_string(a["data"] + to_string(b["data"])))
        }
      }
    },
    IR_SUB => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      if a != nil and b != nil {
        vm_set_register(vm, dest, vm_int(a["data"] - b["data"]))
      }
    },
    IR_MUL => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      if a != nil and b != nil {
        vm_set_register(vm, dest, vm_int(a["data"] * b["data"]))
      }
    },
    IR_DIV => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      if b != nil and b["data"] != 0 {
        vm_set_register(vm, dest, vm_int(a["data"] / b["data"]))
      } else {
        vm_error(vm, "Division by zero")
        vm_set_register(vm, dest, vm_nil())
      }
    },
    IR_MOD => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      if b != nil and b["data"] != 0 {
        vm_set_register(vm, dest, vm_int(a["data"] % b["data"]))
      } else {
        vm_error(vm, "Modulo by zero")
      }
    },
    IR_NEG => {
      a = vm_get_register(vm, src1)
      if a != nil {
        vm_set_register(vm, dest, vm_int(0 - a["data"]))
      }
    },

    # Comparison
    IR_EQ => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      vm_set_register(vm, dest, vm_bool(vm_values_equal(a, b)))
    },
    IR_NEQ => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      vm_set_register(vm, dest, vm_bool(not vm_values_equal(a, b)))
    },
    IR_LT => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      vm_set_register(vm, dest, vm_bool(a["data"] < b["data"]))
    },
    IR_GT => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      vm_set_register(vm, dest, vm_bool(a["data"] > b["data"]))
    },
    IR_LTE => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      vm_set_register(vm, dest, vm_bool(a["data"] <= b["data"]))
    },
    IR_GTE => {
      a = vm_get_register(vm, src1)
      b = vm_get_register(vm, src2)
      vm_set_register(vm, dest, vm_bool(a["data"] >= b["data"]))
    },

    # Logical
    IR_NOT => {
      a = vm_get_register(vm, src1)
      if a != nil {
        vm_set_register(vm, dest, vm_bool(not vm_is_truthy(a)))
      }
    },

    # Memory
    IR_LOAD => {
      val = vm_get_local(vm, src1)
      if val == nil {
        val = vm_get_register(vm, src1)
      }
      vm_set_register(vm, dest, val)
    },
    IR_STORE => {
      val = vm_get_register(vm, src1)
      vm_set_local(vm, dest, val)
    },
    IR_LOAD_FIELD => {
      obj = vm_get_register(vm, src1)
      if obj != nil and obj["type"] == VAL_STRUCT {
        field_val = obj["data"]["fields"][instr["comment"]]
        vm_set_register(vm, dest, field_val)
      }
    },
    IR_STORE_FIELD => {
      obj = vm_get_register(vm, src1)
      val = vm_get_register(vm, src2)
      if obj != nil and obj["type"] == VAL_STRUCT {
        obj["data"]["fields"][instr["comment"]] = val
      }
    },
    IR_LOAD_INDEX => {
      obj = vm_get_register(vm, src1)
      idx = vm_get_register(vm, src2)
      if obj != nil and obj["type"] == VAL_ARRAY and idx != nil {
        elements = obj["data"]
        index = idx["data"]
        if index >= 0 and index < length(elements) {
          vm_set_register(vm, dest, elements[index])
        } else {
          vm_error(vm, "Index out of bounds: " + to_string(index))
        }
      }
    },

    # Object creation
    IR_NEW_ARRAY => {
      size = 0
      if src1 != nil {
        s = vm_get_register(vm, src1)
        if s != nil { size = s["data"] }
      }
      vm_set_register(vm, dest, vm_array([]))
      vm_heap_alloc(vm, dest)
    },
    IR_NEW_STRUCT => {
      vm_set_register(vm, dest, vm_struct(src1, {}))
      vm_heap_alloc(vm, dest)
    },

    # Control flow
    IR_MOVE => {
      val = vm_get_register(vm, src1)
      vm_set_register(vm, dest, val)
    },
    IR_CALL => {
      fn_ref = src1
      args = []
      if instr["args"] != nil {
        j = 0
        while j < length(instr["args"]) {
          arg_val = vm_get_register(vm, instr["args"][j])
          push(args, arg_val)
          j = j + 1
        }
      }
      result = vm_call_function(vm, fn_ref, args)
      if dest != nil {
        vm_set_register(vm, dest, result)
      }
    },
    IR_RET => {
      if src1 != nil {
        return vm_get_register(vm, src1)
      }
      return vm_nil()
    },
    IR_HALT => {
      vm["running"] = false
      vm["halted"] = true
    },
    IR_NOP => {
      # Do nothing
    },

    _ => {
      vm_error(vm, "Unknown opcode: " + op)
    }
  }

  return nil
}

# ---- Value Comparison ----

fn vm_values_equal(a: any, b: any) -> bool {
  if a == nil and b == nil { return true }
  if a == nil or b == nil { return false }
  if a["type"] != b["type"] { return false }
  return a["data"] == b["data"]
}

fn vm_is_truthy(v: any) -> bool {
  if v == nil { return false }
  if v["type"] == VAL_NIL { return false }
  if v["type"] == VAL_BOOL { return v["data"] == true }
  if v["type"] == VAL_INT { return v["data"] != 0 }
  if v["type"] == VAL_STRING { return length(v["data"]) > 0 }
  return true
}

# ---- Garbage Collector (Mark-Sweep) ----

fn vm_heap_alloc(vm: any, reg: string) -> any {
  val = vm_get_register(vm, reg)
  if val != nil {
    push(vm["heap"], val)
    vm["heap_size"] = vm["heap_size"] + 1
  }
  return vm
}

fn vm_gc_maybe_collect(vm: any) -> any {
  if vm["heap_size"] > 0 {
    # Simple threshold check
    vm_gc_collect(vm)
  }
  return vm
}

fn vm_gc_collect(vm: any) -> any {
  vm["gc_runs"] = vm["gc_runs"] + 1

  # Phase 1: Mark all roots
  vm_gc_mark_roots(vm)

  # Phase 2: Sweep unmarked objects
  collected = vm_gc_sweep(vm)
  vm["gc_collected"] = vm["gc_collected"] + collected

  return vm
}

fn vm_gc_mark_roots(vm: any) -> any {
  # Mark stack values
  i = 0
  while i < vm["sp"] {
    vm_gc_mark(vm["stack"][i])
    i = i + 1
  }

  # Mark register values
  keys = dict_keys(vm["registers"])
  i = 0
  while i < length(keys) {
    vm_gc_mark(vm["registers"][keys[i]])
    i = i + 1
  }

  # Mark globals
  keys = dict_keys(vm["globals"])
  i = 0
  while i < length(keys) {
    vm_gc_mark(vm["globals"][keys[i]])
    i = i + 1
  }

  # Mark call stack locals
  i = 0
  while i < vm["csp"] {
    frame = vm["call_stack"][i]
    local_keys = dict_keys(frame["locals"])
    j = 0
    while j < length(local_keys) {
      vm_gc_mark(frame["locals"][local_keys[j]])
      j = j + 1
    }
    i = i + 1
  }

  return vm
}

fn vm_gc_mark(value: any) -> any {
  if value == nil { return nil }
  if value["gc_mark"] == true { return nil }  # Already marked
  value["gc_mark"] = true

  # Recursively mark references
  if value["type"] == VAL_ARRAY {
    i = 0
    while i < length(value["data"]) {
      vm_gc_mark(value["data"][i])
      i = i + 1
    }
  } else if value["type"] == VAL_STRUCT {
    if value["data"] != nil and value["data"]["fields"] != nil {
      keys = dict_keys(value["data"]["fields"])
      i = 0
      while i < length(keys) {
        vm_gc_mark(value["data"]["fields"][keys[i]])
        i = i + 1
      }
    }
  } else if value["type"] == VAL_CLOSURE {
    if value["data"]["captures"] != nil {
      i = 0
      while i < length(value["data"]["captures"]) {
        vm_gc_mark(value["data"]["captures"][i])
        i = i + 1
      }
    }
  }

  return nil
}

fn vm_gc_sweep(vm: any) -> i32 {
  new_heap = []
  collected = 0

  i = 0
  while i < length(vm["heap"]) {
    obj = vm["heap"][i]
    if obj["gc_mark"] {
      obj["gc_mark"] = false  # Reset for next cycle
      push(new_heap, obj)
    } else {
      collected = collected + 1
    }
    i = i + 1
  }

  vm["heap"] = new_heap
  vm["heap_size"] = length(new_heap)

  return collected
}

# ---- Error Handling ----

fn vm_error(vm: any, message: string) -> any {
  err = {
    "message": message,
    "ip": vm["ip"],
    "frame": nil
  }
  frame = vm_current_frame(vm)
  if frame != nil {
    err["frame"] = frame["fn_name"]
  }
  push(vm["errors"], err)
  vm["error_count"] = vm["error_count"] + 1
  return vm
}

# ---- VM Report ----

fn vm_report(vm: any) -> any {
  return {
    "instructions_executed": vm["instructions_executed"],
    "max_stack_depth": vm["max_stack_depth"],
    "max_call_depth": vm["max_call_depth"],
    "heap_size": vm["heap_size"],
    "gc_runs": vm["gc_runs"],
    "gc_collected": vm["gc_collected"],
    "error_count": vm["error_count"],
    "elapsed_ms": vm["elapsed_ms"],
    "r4_pass": vm["error_count"] == 0 and vm["gc_collected"] >= 0  # R4: 0 leaks
  }
}

# ---- Built-in Standard Library Functions ----

fn vm_register_stdlib(vm: any) -> any {
  # I/O
  vm_register_native(vm, "print", fn(vm: any, args: array) -> any {
    i = 0
    while i < length(args) {
      if args[i] != nil {
        print(to_string(args[i]["data"]))
      }
      i = i + 1
    }
    return vm_nil()
  })

  vm_register_native(vm, "println", fn(vm: any, args: array) -> any {
    i = 0
    while i < length(args) {
      if args[i] != nil {
        print(to_string(args[i]["data"]))
      }
      i = i + 1
    }
    print("\n")
    return vm_nil()
  })

  # Math
  vm_register_native(vm, "abs", fn(vm: any, args: array) -> any {
    if length(args) > 0 and args[0] != nil {
      n = args[0]["data"]
      if n < 0 { return vm_int(0 - n) }
      return vm_int(n)
    }
    return vm_int(0)
  })

  vm_register_native(vm, "max", fn(vm: any, args: array) -> any {
    if length(args) >= 2 {
      a = args[0]["data"]
      b = args[1]["data"]
      if a > b { return vm_int(a) }
      return vm_int(b)
    }
    return vm_nil()
  })

  vm_register_native(vm, "min", fn(vm: any, args: array) -> any {
    if length(args) >= 2 {
      a = args[0]["data"]
      b = args[1]["data"]
      if a < b { return vm_int(a) }
      return vm_int(b)
    }
    return vm_nil()
  })

  # Array
  vm_register_native(vm, "length", fn(vm: any, args: array) -> any {
    if length(args) > 0 and args[0] != nil {
      if args[0]["type"] == VAL_ARRAY {
        return vm_int(length(args[0]["data"]))
      }
      if args[0]["type"] == VAL_STRING {
        return vm_int(length(args[0]["data"]))
      }
    }
    return vm_int(0)
  })

  vm_register_native(vm, "push", fn(vm: any, args: array) -> any {
    if length(args) >= 2 and args[0]["type"] == VAL_ARRAY {
      push(args[0]["data"], args[1])
    }
    return vm_nil()
  })

  vm_register_native(vm, "pop", fn(vm: any, args: array) -> any {
    if length(args) > 0 and args[0]["type"] == VAL_ARRAY {
      return pop(args[0]["data"])
    }
    return vm_nil()
  })

  # Type checking
  vm_register_native(vm, "type_of", fn(vm: any, args: array) -> any {
    if length(args) > 0 and args[0] != nil {
      match args[0]["type"] {
        VAL_INT => { return vm_string("int") },
        VAL_FLOAT => { return vm_string("float") },
        VAL_BOOL => { return vm_string("bool") },
        VAL_STRING => { return vm_string("string") },
        VAL_NIL => { return vm_string("nil") },
        VAL_ARRAY => { return vm_string("array") },
        VAL_DICT => { return vm_string("dict") },
        VAL_STRUCT => { return vm_string("struct") },
        VAL_FN => { return vm_string("fn") },
        _ => { return vm_string("unknown") }
      }
    }
    return vm_string("nil")
  })

  # Conversion
  vm_register_native(vm, "to_string", fn(vm: any, args: array) -> any {
    if length(args) > 0 and args[0] != nil {
      return vm_string(to_string(args[0]["data"]))
    }
    return vm_string("")
  })

  vm_register_native(vm, "to_int", fn(vm: any, args: array) -> any {
    if length(args) > 0 and args[0] != nil {
      return vm_int(to_number(args[0]["data"]))
    }
    return vm_int(0)
  })

  # Time
  vm_register_native(vm, "time_now", fn(vm: any, args: array) -> any {
    return vm_int(time_now())
  })

  return vm
}

# ================================================================
# FreeLang v4 Core - JIT Compiler
# Tiered compilation: Interpreter -> Baseline -> Optimized
# Performance target: R6 JIT speedup 2-5x vs interpreter
# ================================================================

# ---- JIT Tier Constants ----

JIT_TIER_INTERPRETER = 0
JIT_TIER_BASELINE    = 1
JIT_TIER_OPTIMIZED   = 2

JIT_HOT_THRESHOLD_BASELINE  = 50     # calls before baseline JIT
JIT_HOT_THRESHOLD_OPTIMIZED = 500    # calls before optimized JIT

# ---- JIT Profile Data ----

fn create_jit_profile(fn_name: string) -> any {
  return {
    "fn_name": fn_name,
    "call_count": 0,
    "total_time_us": 0,
    "avg_time_us": 0,
    "tier": JIT_TIER_INTERPRETER,
    "compiled_code": nil,
    "optimized_code": nil,
    "type_feedback": {},      # arg positions -> observed types
    "branch_feedback": {},    # branch_id -> {taken, not_taken}
    "deopt_count": 0,
    "inline_candidates": [],
    "last_compiled_at": 0
  }
}

# ---- JIT Compiler State ----

fn create_jit_compiler() -> any {
  return {
    "profiles": {},             # fn_name -> JitProfile
    "compiled_functions": {},   # fn_name -> compiled code
    "compile_queue": [],
    "total_compilations": 0,
    "total_deoptimizations": 0,
    "baseline_count": 0,
    "optimized_count": 0,
    "register_allocator": create_register_allocator(),
    "inline_cache": {},
    "code_cache_size": 0,
    "max_code_cache": 10485760,  # 10MB
    "start_time": 0,
    "elapsed_ms": 0,
    "stats": {
      "compilations": 0,
      "baseline_compilations": 0,
      "optimized_compilations": 0,
      "deoptimizations": 0,
      "inlined_calls": 0,
      "type_specializations": 0,
      "registers_allocated": 0,
      "spills": 0,
      "speedup_ratio": 1.0
    }
  }
}

# ---- Register Allocator ----

fn create_register_allocator() -> any {
  # 16 general-purpose registers (x86-64 style)
  regs = []
  push(regs, { "name": "rax", "allocated": false, "value": nil })
  push(regs, { "name": "rbx", "allocated": false, "value": nil })
  push(regs, { "name": "rcx", "allocated": false, "value": nil })
  push(regs, { "name": "rdx", "allocated": false, "value": nil })
  push(regs, { "name": "rsi", "allocated": false, "value": nil })
  push(regs, { "name": "rdi", "allocated": false, "value": nil })
  push(regs, { "name": "r8",  "allocated": false, "value": nil })
  push(regs, { "name": "r9",  "allocated": false, "value": nil })
  push(regs, { "name": "r10", "allocated": false, "value": nil })
  push(regs, { "name": "r11", "allocated": false, "value": nil })
  push(regs, { "name": "r12", "allocated": false, "value": nil })
  push(regs, { "name": "r13", "allocated": false, "value": nil })
  push(regs, { "name": "r14", "allocated": false, "value": nil })
  push(regs, { "name": "r15", "allocated": false, "value": nil })
  push(regs, { "name": "rbp", "allocated": true, "value": "frame_pointer" })
  push(regs, { "name": "rsp", "allocated": true, "value": "stack_pointer" })

  return {
    "registers": regs,
    "available_count": 14,  # 16 - 2 reserved
    "spill_slots": [],
    "live_ranges": {},
    "interference_graph": {}
  }
}

fn alloc_register(ra: any, var_name: string) -> string {
  # Linear scan allocation
  i = 0
  while i < length(ra["registers"]) {
    reg = ra["registers"][i]
    if not reg["allocated"] {
      reg["allocated"] = true
      reg["value"] = var_name
      ra["available_count"] = ra["available_count"] - 1
      return reg["name"]
    }
    i = i + 1
  }

  # All registers full - spill
  spill_slot = length(ra["spill_slots"])
  push(ra["spill_slots"], var_name)
  return "spill_" + to_string(spill_slot)
}

fn free_register(ra: any, reg_name: string) -> any {
  i = 0
  while i < length(ra["registers"]) {
    reg = ra["registers"][i]
    if reg["name"] == reg_name and reg["allocated"] and reg["value"] != "frame_pointer" and reg["value"] != "stack_pointer" {
      reg["allocated"] = false
      reg["value"] = nil
      ra["available_count"] = ra["available_count"] + 1
      return ra
    }
    i = i + 1
  }
  return ra
}

fn ra_efficiency(ra: any) -> f64 {
  total = length(ra["registers"]) - 2  # minus reserved
  spills = length(ra["spill_slots"])
  if total + spills == 0 { return 100.0 }
  return (total * 100.0) / (total + spills)
}

# ---- Profiling ----

fn jit_record_call(jit: any, fn_name: string, elapsed_us: i32) -> any {
  profile = jit["profiles"][fn_name]
  if profile == nil {
    profile = create_jit_profile(fn_name)
    jit["profiles"][fn_name] = profile
  }

  profile["call_count"] = profile["call_count"] + 1
  profile["total_time_us"] = profile["total_time_us"] + elapsed_us
  profile["avg_time_us"] = profile["total_time_us"] / profile["call_count"]

  # Check if hot enough for compilation
  if profile["tier"] == JIT_TIER_INTERPRETER and profile["call_count"] >= JIT_HOT_THRESHOLD_BASELINE {
    push(jit["compile_queue"], { "fn_name": fn_name, "tier": JIT_TIER_BASELINE })
  } else if profile["tier"] == JIT_TIER_BASELINE and profile["call_count"] >= JIT_HOT_THRESHOLD_OPTIMIZED {
    push(jit["compile_queue"], { "fn_name": fn_name, "tier": JIT_TIER_OPTIMIZED })
  }

  return jit
}

fn jit_record_type_feedback(jit: any, fn_name: string, arg_pos: i32, observed_type: string) -> any {
  profile = jit["profiles"][fn_name]
  if profile == nil { return jit }

  key = to_string(arg_pos)
  if profile["type_feedback"][key] == nil {
    profile["type_feedback"][key] = {}
  }
  profile["type_feedback"][key][observed_type] = true

  return jit
}

fn jit_record_branch(jit: any, fn_name: string, branch_id: string, taken: bool) -> any {
  profile = jit["profiles"][fn_name]
  if profile == nil { return jit }

  if profile["branch_feedback"][branch_id] == nil {
    profile["branch_feedback"][branch_id] = { "taken": 0, "not_taken": 0 }
  }

  if taken {
    profile["branch_feedback"][branch_id]["taken"] = profile["branch_feedback"][branch_id]["taken"] + 1
  } else {
    profile["branch_feedback"][branch_id]["not_taken"] = profile["branch_feedback"][branch_id]["not_taken"] + 1
  }

  return jit
}

# ---- Compilation ----

fn jit_process_compile_queue(jit: any, ir_module: any) -> any {
  while length(jit["compile_queue"]) > 0 {
    item = pop(jit["compile_queue"])
    fn_name = item["fn_name"]
    tier = item["tier"]

    if tier == JIT_TIER_BASELINE {
      jit_compile_baseline(jit, fn_name, ir_module)
    } else if tier == JIT_TIER_OPTIMIZED {
      jit_compile_optimized(jit, fn_name, ir_module)
    }
  }
  return jit
}

fn jit_compile_baseline(jit: any, fn_name: string, ir_module: any) -> any {
  profile = jit["profiles"][fn_name]
  if profile == nil { return jit }

  # Find the IR function
  ir_func = nil
  i = 0
  while i < length(ir_module["functions"]) {
    if ir_module["functions"][i]["name"] == fn_name {
      ir_func = ir_module["functions"][i]
      break
    }
    i = i + 1
  }

  if ir_func == nil { return jit }

  # Baseline compilation: direct IR -> native code mapping
  native_code = []
  ra = create_register_allocator()

  j = 0
  while j < length(ir_func["blocks"]) {
    block = ir_func["blocks"][j]
    # Emit block label
    push(native_code, { "type": "label", "name": block["label"] })

    k = 0
    while k < length(block["instructions"]) {
      instr = block["instructions"][k]
      native_instrs = baseline_translate_instr(jit, ra, instr)
      m = 0
      while m < length(native_instrs) {
        push(native_code, native_instrs[m])
        m = m + 1
      }
      k = k + 1
    }
    j = j + 1
  }

  profile["tier"] = JIT_TIER_BASELINE
  profile["compiled_code"] = native_code
  profile["last_compiled_at"] = time_now()
  jit["compiled_functions"][fn_name] = native_code
  jit["stats"]["baseline_compilations"] = jit["stats"]["baseline_compilations"] + 1
  jit["stats"]["compilations"] = jit["stats"]["compilations"] + 1
  jit["stats"]["registers_allocated"] = jit["stats"]["registers_allocated"] + (14 - ra["available_count"])
  jit["stats"]["spills"] = jit["stats"]["spills"] + length(ra["spill_slots"])

  return jit
}

fn baseline_translate_instr(jit: any, ra: any, instr: any) -> array {
  result = []
  op = instr["op"]

  match op {
    IR_CONST_INT => {
      reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "mov", "dest": reg, "imm": instr["src1"] })
    },
    IR_ADD => {
      dest_reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "mov", "dest": dest_reg, "src": instr["src1"] })
      push(result, { "type": "add", "dest": dest_reg, "src": instr["src2"] })
    },
    IR_SUB => {
      dest_reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "mov", "dest": dest_reg, "src": instr["src1"] })
      push(result, { "type": "sub", "dest": dest_reg, "src": instr["src2"] })
    },
    IR_MUL => {
      dest_reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "mov", "dest": "rax", "src": instr["src1"] })
      push(result, { "type": "imul", "src": instr["src2"] })
      push(result, { "type": "mov", "dest": dest_reg, "src": "rax" })
    },
    IR_DIV => {
      dest_reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "xor", "dest": "rdx", "src": "rdx" })
      push(result, { "type": "mov", "dest": "rax", "src": instr["src1"] })
      push(result, { "type": "idiv", "src": instr["src2"] })
      push(result, { "type": "mov", "dest": dest_reg, "src": "rax" })
    },
    IR_EQ => {
      dest_reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "cmp", "src1": instr["src1"], "src2": instr["src2"] })
      push(result, { "type": "sete", "dest": dest_reg })
    },
    IR_LT => {
      dest_reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "cmp", "src1": instr["src1"], "src2": instr["src2"] })
      push(result, { "type": "setl", "dest": dest_reg })
    },
    IR_JMP => {
      push(result, { "type": "jmp", "label": instr["label"] })
    },
    IR_JMP_IF => {
      push(result, { "type": "test", "src": instr["src1"] })
      push(result, { "type": "jnz", "label": instr["label"] })
    },
    IR_JMP_NIF => {
      push(result, { "type": "test", "src": instr["src1"] })
      push(result, { "type": "jz", "label": instr["label"] })
    },
    IR_CALL => {
      # Set up arguments in registers (System V ABI)
      arg_regs = ["rdi", "rsi", "rdx", "rcx", "r8", "r9"]
      if instr["args"] != nil {
        n = 0
        while n < length(instr["args"]) and n < 6 {
          push(result, { "type": "mov", "dest": arg_regs[n], "src": instr["args"][n] })
          n = n + 1
        }
        # Remaining args go on stack
        while n < length(instr["args"]) {
          push(result, { "type": "push", "src": instr["args"][n] })
          n = n + 1
        }
      }
      push(result, { "type": "call", "target": instr["src1"] })
      if instr["dest"] != nil {
        dest_reg = alloc_register(ra, instr["dest"])
        push(result, { "type": "mov", "dest": dest_reg, "src": "rax" })
      }
    },
    IR_RET => {
      if instr["src1"] != nil {
        push(result, { "type": "mov", "dest": "rax", "src": instr["src1"] })
      }
      push(result, { "type": "ret" })
    },
    IR_MOVE => {
      dest_reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "mov", "dest": dest_reg, "src": instr["src1"] })
    },
    IR_LOAD => {
      dest_reg = alloc_register(ra, instr["dest"])
      push(result, { "type": "load", "dest": dest_reg, "addr": instr["src1"] })
    },
    IR_STORE => {
      push(result, { "type": "store", "addr": instr["dest"], "src": instr["src1"] })
    },
    _ => {
      push(result, { "type": "nop", "comment": "unhandled: " + op })
    }
  }

  return result
}

fn jit_compile_optimized(jit: any, fn_name: string, ir_module: any) -> any {
  profile = jit["profiles"][fn_name]
  if profile == nil { return jit }

  # Optimized compilation uses type feedback for specialization
  type_info = profile["type_feedback"]
  branch_info = profile["branch_feedback"]

  # 1. Type specialization
  specializations = 0
  keys = dict_keys(type_info)
  i = 0
  while i < length(keys) {
    arg_types = type_info[keys[i]]
    type_list = dict_keys(arg_types)
    if length(type_list) == 1 {
      # Monomorphic - can specialize!
      specializations = specializations + 1
    }
    i = i + 1
  }
  jit["stats"]["type_specializations"] = jit["stats"]["type_specializations"] + specializations

  # 2. Branch prediction optimization
  branch_keys = dict_keys(branch_info)
  i = 0
  while i < length(branch_keys) {
    info = branch_info[branch_keys[i]]
    total = info["taken"] + info["not_taken"]
    if total > 0 {
      taken_ratio = info["taken"] / total
      # If >90% taken or not-taken, mark as predictable
    }
    i = i + 1
  }

  # 3. Inline small functions
  inlined = 0
  i = 0
  while i < length(profile["inline_candidates"]) {
    candidate = profile["inline_candidates"][i]
    candidate_profile = jit["profiles"][candidate]
    if candidate_profile != nil and candidate_profile["avg_time_us"] < 10 {
      # Small enough to inline
      inlined = inlined + 1
    }
    i = i + 1
  }
  jit["stats"]["inlined_calls"] = jit["stats"]["inlined_calls"] + inlined

  # Mark as optimized
  profile["tier"] = JIT_TIER_OPTIMIZED
  profile["last_compiled_at"] = time_now()
  jit["stats"]["optimized_compilations"] = jit["stats"]["optimized_compilations"] + 1
  jit["stats"]["compilations"] = jit["stats"]["compilations"] + 1

  return jit
}

# ---- Deoptimization ----

fn jit_deoptimize(jit: any, fn_name: string, reason: string) -> any {
  profile = jit["profiles"][fn_name]
  if profile == nil { return jit }

  profile["tier"] = JIT_TIER_INTERPRETER
  profile["compiled_code"] = nil
  profile["optimized_code"] = nil
  profile["deopt_count"] = profile["deopt_count"] + 1
  jit["stats"]["deoptimizations"] = jit["stats"]["deoptimizations"] + 1

  # Remove from compiled cache
  jit["compiled_functions"][fn_name] = nil

  return jit
}

# ---- JIT Execution ----

fn jit_should_use_compiled(jit: any, fn_name: string) -> bool {
  profile = jit["profiles"][fn_name]
  if profile == nil { return false }
  return profile["tier"] >= JIT_TIER_BASELINE and profile["compiled_code"] != nil
}

fn jit_get_compiled(jit: any, fn_name: string) -> any {
  return jit["compiled_functions"][fn_name]
}

# ---- Speedup Calculation ----

fn jit_calculate_speedup(jit: any) -> f64 {
  total_interpreted_time = 0
  total_compiled_time = 0

  keys = dict_keys(jit["profiles"])
  i = 0
  while i < length(keys) {
    profile = jit["profiles"][keys[i]]
    if profile["tier"] >= JIT_TIER_BASELINE {
      # Estimated compiled time = interpreted / speedup_factor
      interpreted_est = profile["avg_time_us"] * profile["call_count"]
      compiled_est = interpreted_est / 3.0  # ~3x speedup estimate for baseline
      if profile["tier"] == JIT_TIER_OPTIMIZED {
        compiled_est = interpreted_est / 5.0  # ~5x for optimized
      }
      total_interpreted_time = total_interpreted_time + interpreted_est
      total_compiled_time = total_compiled_time + compiled_est
    }
    i = i + 1
  }

  if total_compiled_time > 0 {
    jit["stats"]["speedup_ratio"] = total_interpreted_time / total_compiled_time
    return jit["stats"]["speedup_ratio"]
  }

  return 1.0
}

# ---- JIT Report ----

fn jit_report(jit: any) -> any {
  speedup = jit_calculate_speedup(jit)
  ra = jit["register_allocator"]

  return {
    "total_compilations": jit["stats"]["compilations"],
    "baseline_compilations": jit["stats"]["baseline_compilations"],
    "optimized_compilations": jit["stats"]["optimized_compilations"],
    "deoptimizations": jit["stats"]["deoptimizations"],
    "inlined_calls": jit["stats"]["inlined_calls"],
    "type_specializations": jit["stats"]["type_specializations"],
    "registers_allocated": jit["stats"]["registers_allocated"],
    "spills": jit["stats"]["spills"],
    "speedup_ratio": speedup,
    "register_efficiency": ra_efficiency(ra),
    "r6_pass": speedup >= 2.0,  # R6: JIT speedup 2-5x
    "r8_pass": ra_efficiency(ra) >= 85.0  # R8: Register allocation >85%
  }
}

# ================================================================
# FreeLang v4 Core - Bytecode Cache
# Content-addressable storage with LRU eviction
# Performance target: R7 Cache hit rate > 80%
# ================================================================

# ---- Cache Configuration ----

CACHE_MAX_ENTRIES     = 1024
CACHE_MAX_SIZE_BYTES  = 52428800  # 50MB
CACHE_TTL_MS          = 3600000    # 1 hour

# ---- Cache Entry ----

fn create_cache_entry(key: string, data: any, size: i32) -> any {
  return {
    "key": key,
    "data": data,
    "size": size,
    "created_at": time_now(),
    "last_accessed": time_now(),
    "access_count": 0,
    "version": 1,
    "valid": true
  }
}

# ---- Bytecode Cache ----

fn create_bytecode_cache() -> any {
  return {
    "entries": {},         # key -> CacheEntry
    "keys_lru": [],       # LRU ordered keys (most recent at end)
    "entry_count": 0,
    "total_size": 0,
    "max_entries": CACHE_MAX_ENTRIES,
    "max_size": CACHE_MAX_SIZE_BYTES,
    "ttl_ms": CACHE_TTL_MS,

    # Statistics
    "hits": 0,
    "misses": 0,
    "evictions": 0,
    "invalidations": 0,
    "total_lookups": 0,
    "total_writes": 0,

    # Hash table for fast lookup
    "hash_buckets": [],
    "bucket_count": 256
  }
}

# ---- Hash Function ----

fn cache_hash(source: string) -> string {
  # SHA256-like hash for content addressing
  h = 5381
  i = 0
  while i < length(source) {
    ch = char_code(source[i])
    h = ((h * 33) + ch) % 4294967296  # 2^32
    i = i + 1
  }

  # Convert to hex string
  hex_chars = "0123456789abcdef"
  result = ""
  temp = h
  j = 0
  while j < 8 {
    digit = temp % 16
    result = hex_chars[digit] + result
    temp = temp / 16
    j = j + 1
  }

  return "sha_" + result
}

fn cache_hash_key(source: string, opt_level: i32) -> string {
  base = cache_hash(source)
  return base + "_O" + to_string(opt_level)
}

# ---- Cache Operations ----

fn cache_get(cache: any, key: string) -> any {
  cache["total_lookups"] = cache["total_lookups"] + 1

  entry = cache["entries"][key]
  if entry == nil {
    cache["misses"] = cache["misses"] + 1
    return nil
  }

  # Check TTL
  if time_now() - entry["created_at"] > cache["ttl_ms"] {
    cache_remove(cache, key)
    cache["misses"] = cache["misses"] + 1
    return nil
  }

  # Check validity
  if not entry["valid"] {
    cache_remove(cache, key)
    cache["misses"] = cache["misses"] + 1
    return nil
  }

  # Hit! Update LRU and access count
  cache["hits"] = cache["hits"] + 1
  entry["last_accessed"] = time_now()
  entry["access_count"] = entry["access_count"] + 1
  cache_touch_lru(cache, key)

  return entry["data"]
}

fn cache_put(cache: any, key: string, data: any, size: i32) -> any {
  cache["total_writes"] = cache["total_writes"] + 1

  # Check if already exists (update)
  existing = cache["entries"][key]
  if existing != nil {
    cache["total_size"] = cache["total_size"] - existing["size"]
    existing["data"] = data
    existing["size"] = size
    existing["last_accessed"] = time_now()
    existing["access_count"] = existing["access_count"] + 1
    existing["version"] = existing["version"] + 1
    cache["total_size"] = cache["total_size"] + size
    cache_touch_lru(cache, key)
    return cache
  }

  # Evict if necessary
  while cache["entry_count"] >= cache["max_entries"] or
        cache["total_size"] + size > cache["max_size"] {
    if cache["entry_count"] == 0 {
      break
    }
    cache_evict_lru(cache)
  }

  # Insert new entry
  entry = create_cache_entry(key, data, size)
  cache["entries"][key] = entry
  push(cache["keys_lru"], key)
  cache["entry_count"] = cache["entry_count"] + 1
  cache["total_size"] = cache["total_size"] + size

  return cache
}

fn cache_remove(cache: any, key: string) -> any {
  entry = cache["entries"][key]
  if entry == nil {
    return cache
  }

  cache["total_size"] = cache["total_size"] - entry["size"]
  cache["entries"][key] = nil
  cache["entry_count"] = cache["entry_count"] - 1

  # Remove from LRU list
  new_lru = []
  i = 0
  while i < length(cache["keys_lru"]) {
    if cache["keys_lru"][i] != key {
      push(new_lru, cache["keys_lru"][i])
    }
    i = i + 1
  }
  cache["keys_lru"] = new_lru

  return cache
}

fn cache_invalidate(cache: any, key: string) -> any {
  entry = cache["entries"][key]
  if entry != nil {
    entry["valid"] = false
    cache["invalidations"] = cache["invalidations"] + 1
  }
  return cache
}

fn cache_invalidate_all(cache: any) -> any {
  keys = cache["keys_lru"]
  i = 0
  while i < length(keys) {
    entry = cache["entries"][keys[i]]
    if entry != nil {
      entry["valid"] = false
    }
    i = i + 1
  }
  cache["invalidations"] = cache["invalidations"] + cache["entry_count"]
  return cache
}

fn cache_clear(cache: any) -> any {
  cache["entries"] = {}
  cache["keys_lru"] = []
  cache["entry_count"] = 0
  cache["total_size"] = 0
  return cache
}

# ---- LRU Management ----

fn cache_touch_lru(cache: any, key: string) -> any {
  # Move key to end of LRU list (most recently used)
  new_lru = []
  i = 0
  while i < length(cache["keys_lru"]) {
    if cache["keys_lru"][i] != key {
      push(new_lru, cache["keys_lru"][i])
    }
    i = i + 1
  }
  push(new_lru, key)
  cache["keys_lru"] = new_lru
  return cache
}

fn cache_evict_lru(cache: any) -> any {
  if length(cache["keys_lru"]) == 0 {
    return cache
  }

  # Evict least recently used (front of list)
  lru_key = cache["keys_lru"][0]
  cache_remove(cache, lru_key)
  cache["evictions"] = cache["evictions"] + 1

  return cache
}

# ---- Source-based Caching API ----

fn cache_compile_result(cache: any, source: string, opt_level: i32, ir_module: any) -> any {
  key = cache_hash_key(source, opt_level)

  # Estimate size (number of instructions * ~50 bytes each)
  stats = ir_module_stats(ir_module)
  est_size = stats["instructions"] * 50

  cache_put(cache, key, ir_module, est_size)
  return cache
}

fn cache_lookup_compiled(cache: any, source: string, opt_level: i32) -> any {
  key = cache_hash_key(source, opt_level)
  return cache_get(cache, key)
}

# ---- Serialization (for persistent cache) ----

fn cache_serialize_entry(entry: any) -> string {
  # Serialize cache entry to string format
  if entry == nil { return "" }

  result = "CACHE_ENTRY_V1\n"
  result = result + "key=" + entry["key"] + "\n"
  result = result + "size=" + to_string(entry["size"]) + "\n"
  result = result + "version=" + to_string(entry["version"]) + "\n"
  result = result + "created=" + to_string(entry["created_at"]) + "\n"
  result = result + "accessed=" + to_string(entry["last_accessed"]) + "\n"
  result = result + "count=" + to_string(entry["access_count"]) + "\n"
  # Data would be serialized IR module
  result = result + "END_ENTRY\n"

  return result
}

fn cache_deserialize_entry(serialized: string) -> any {
  # Parse serialized cache entry
  if length(serialized) == 0 { return nil }

  entry = create_cache_entry("", nil, 0)
  # Simple key=value parsing
  lines = split(serialized, "\n")
  i = 0
  while i < length(lines) {
    line = lines[i]
    if starts_with(line, "key=") {
      entry["key"] = substring(line, 4)
    } else if starts_with(line, "size=") {
      entry["size"] = to_number(substring(line, 5))
    } else if starts_with(line, "version=") {
      entry["version"] = to_number(substring(line, 8))
    }
    i = i + 1
  }

  return entry
}

# ---- Warm-up / Prefetch ----

fn cache_warm_up(cache: any, sources: array, opt_level: i32) -> any {
  # Pre-compile a list of sources into cache
  i = 0
  while i < length(sources) {
    key = cache_hash_key(sources[i], opt_level)
    # Check if already cached
    if cache_get(cache, key) == nil {
      # Would trigger compilation and caching
      # For now, just record the miss
    }
    i = i + 1
  }
  return cache
}

# ---- Cache Statistics ----

fn cache_hit_rate(cache: any) -> f64 {
  if cache["total_lookups"] == 0 {
    return 0.0
  }
  return (cache["hits"] * 100.0) / cache["total_lookups"]
}

fn cache_report(cache: any) -> any {
  hit_rate = cache_hit_rate(cache)

  return {
    "entry_count": cache["entry_count"],
    "total_size": cache["total_size"],
    "total_lookups": cache["total_lookups"],
    "hits": cache["hits"],
    "misses": cache["misses"],
    "hit_rate": hit_rate,
    "evictions": cache["evictions"],
    "invalidations": cache["invalidations"],
    "total_writes": cache["total_writes"],
    "r7_pass": hit_rate > 80.0  # R7: Cache hit rate > 80%
  }
}

# ================================================================
# FreeLang v4 Core - Standard Library: Math Module
# Comprehensive math functions with numeric precision
# ================================================================

# ---- Constants ----

PI          = 3.14159265358979323846
E           = 2.71828182845904523536
TAU         = 6.28318530717958647692
SQRT2       = 1.41421356237309504880
LN2         = 0.69314718055994530942
LN10        = 2.30258509299404568402
LOG2E       = 1.44269504088896340736
LOG10E      = 0.43429448190325182765
INFINITY    = 1.0 / 0.0
NEG_INF     = -1.0 / 0.0
NAN         = 0.0 / 0.0
EPSILON     = 2.220446049250313e-16
MAX_I32     = 2147483647
MIN_I32     = -2147483648
MAX_F64     = 1.7976931348623157e308

# ---- Basic Arithmetic ----

fn math_abs(x: f64) -> f64 {
  if x < 0.0 { return 0.0 - x }
  return x
}

fn math_abs_i(x: i32) -> i32 {
  if x < 0 { return 0 - x }
  return x
}

fn math_sign(x: f64) -> f64 {
  if x > 0.0 { return 1.0 }
  if x < 0.0 { return -1.0 }
  return 0.0
}

fn math_max(a: f64, b: f64) -> f64 {
  if a >= b { return a }
  return b
}

fn math_min(a: f64, b: f64) -> f64 {
  if a <= b { return a }
  return b
}

fn math_clamp(x: f64, lo: f64, hi: f64) -> f64 {
  if x < lo { return lo }
  if x > hi { return hi }
  return x
}

fn math_max_i(a: i32, b: i32) -> i32 {
  if a >= b { return a }
  return b
}

fn math_min_i(a: i32, b: i32) -> i32 {
  if a <= b { return a }
  return b
}

fn math_clamp_i(x: i32, lo: i32, hi: i32) -> i32 {
  if x < lo { return lo }
  if x > hi { return hi }
  return x
}

# ---- Rounding ----

fn math_floor(x: f64) -> f64 {
  i = x as i32
  if x < 0.0 and x != (i as f64) {
    return (i - 1) as f64
  }
  return i as f64
}

fn math_ceil(x: f64) -> f64 {
  i = x as i32
  if x > 0.0 and x != (i as f64) {
    return (i + 1) as f64
  }
  return i as f64
}

fn math_round(x: f64) -> f64 {
  if x >= 0.0 {
    return math_floor(x + 0.5)
  }
  return math_ceil(x - 0.5)
}

fn math_trunc(x: f64) -> f64 {
  return (x as i32) as f64
}

fn math_fract(x: f64) -> f64 {
  return x - math_trunc(x)
}

# ---- Power and Root ----

fn math_pow(base: f64, exp: i32) -> f64 {
  if exp == 0 { return 1.0 }
  if exp < 0 {
    return 1.0 / math_pow(base, 0 - exp)
  }

  result = 1.0
  b = base
  e = exp
  while e > 0 {
    if e % 2 == 1 {
      result = result * b
    }
    b = b * b
    e = e / 2
  }
  return result
}

fn math_powf(base: f64, exp: f64) -> f64 {
  # For fractional exponents, use exp(exp * ln(base))
  if base <= 0.0 {
    if base == 0.0 { return 0.0 }
    return NAN  # negative base with fractional exp
  }
  return math_exp(exp * math_ln(base))
}

fn math_sqrt(x: f64) -> f64 {
  if x < 0.0 { return NAN }
  if x == 0.0 { return 0.0 }

  # Newton's method
  guess = x / 2.0
  i = 0
  while i < 50 {
    new_guess = (guess + x / guess) / 2.0
    if math_abs(new_guess - guess) < EPSILON {
      return new_guess
    }
    guess = new_guess
    i = i + 1
  }
  return guess
}

fn math_cbrt(x: f64) -> f64 {
  if x == 0.0 { return 0.0 }
  neg = x < 0.0
  y = math_abs(x)

  # Newton's method for cube root
  guess = y / 3.0
  i = 0
  while i < 50 {
    new_guess = (2.0 * guess + y / (guess * guess)) / 3.0
    if math_abs(new_guess - guess) < EPSILON {
      if neg { return 0.0 - new_guess }
      return new_guess
    }
    guess = new_guess
    i = i + 1
  }
  if neg { return 0.0 - guess }
  return guess
}

fn math_hypot(x: f64, y: f64) -> f64 {
  return math_sqrt(x * x + y * y)
}

# ---- Exponential and Logarithm ----

fn math_exp(x: f64) -> f64 {
  # Taylor series: e^x = 1 + x + x^2/2! + x^3/3! + ...
  if x == 0.0 { return 1.0 }

  # Range reduction: e^x = e^n * e^f where x = n + f
  n = math_round(x) as i32
  f = x - (n as f64)

  # Compute e^f using Taylor series
  result = 1.0
  term = 1.0
  i = 1
  while i < 30 {
    term = term * f / (i as f64)
    result = result + term
    if math_abs(term) < EPSILON { break }
    i = i + 1
  }

  # Multiply by e^n
  if n > 0 {
    e_n = math_pow(E, n)
    return result * e_n
  } else if n < 0 {
    e_n = math_pow(E, 0 - n)
    return result / e_n
  }
  return result
}

fn math_ln(x: f64) -> f64 {
  if x <= 0.0 { return NAN }
  if x == 1.0 { return 0.0 }

  # Reduce to [1, 2) range
  k = 0
  y = x
  while y >= 2.0 {
    y = y / 2.0
    k = k + 1
  }
  while y < 1.0 {
    y = y * 2.0
    k = k - 1
  }

  # ln(y) for y in [1, 2) using series
  z = (y - 1.0) / (y + 1.0)
  z2 = z * z
  result = 0.0
  term = z
  i = 0
  while i < 30 {
    result = result + term / (2.0 * (i as f64) + 1.0)
    term = term * z2
    i = i + 1
  }
  result = result * 2.0

  return result + (k as f64) * LN2
}

fn math_log2(x: f64) -> f64 {
  return math_ln(x) / LN2
}

fn math_log10(x: f64) -> f64 {
  return math_ln(x) / LN10
}

fn math_log(x: f64, base: f64) -> f64 {
  return math_ln(x) / math_ln(base)
}

fn math_exp2(x: f64) -> f64 {
  return math_powf(2.0, x)
}

# ---- Trigonometric Functions ----

fn math_sin(x: f64) -> f64 {
  # Reduce to [-PI, PI]
  y = x
  while y > PI { y = y - TAU }
  while y < (0.0 - PI) { y = y + TAU }

  # Taylor series: sin(x) = x - x^3/3! + x^5/5! - ...
  result = 0.0
  term = y
  i = 0
  while i < 20 {
    result = result + term
    term = 0.0 - term * y * y / ((2.0 * (i as f64) + 2.0) * (2.0 * (i as f64) + 3.0))
    if math_abs(term) < EPSILON { break }
    i = i + 1
  }
  return result
}

fn math_cos(x: f64) -> f64 {
  return math_sin(x + PI / 2.0)
}

fn math_tan(x: f64) -> f64 {
  c = math_cos(x)
  if math_abs(c) < EPSILON { return INFINITY }
  return math_sin(x) / c
}

fn math_asin(x: f64) -> f64 {
  if x < -1.0 or x > 1.0 { return NAN }
  if x == 1.0 { return PI / 2.0 }
  if x == -1.0 { return 0.0 - PI / 2.0 }

  # Series expansion
  result = x
  term = x
  i = 1
  while i < 50 {
    term = term * x * x * (2.0 * (i as f64) - 1.0) * (2.0 * (i as f64) - 1.0) / ((2.0 * (i as f64)) * (2.0 * (i as f64) + 1.0))
    result = result + term
    if math_abs(term) < EPSILON { break }
    i = i + 1
  }
  return result
}

fn math_acos(x: f64) -> f64 {
  return PI / 2.0 - math_asin(x)
}

fn math_atan(x: f64) -> f64 {
  # Use identity: atan(x) = asin(x / sqrt(1 + x^2))
  return math_asin(x / math_sqrt(1.0 + x * x))
}

fn math_atan2(y: f64, x: f64) -> f64 {
  if x > 0.0 { return math_atan(y / x) }
  if x < 0.0 and y >= 0.0 { return math_atan(y / x) + PI }
  if x < 0.0 and y < 0.0 { return math_atan(y / x) - PI }
  if x == 0.0 and y > 0.0 { return PI / 2.0 }
  if x == 0.0 and y < 0.0 { return 0.0 - PI / 2.0 }
  return 0.0  # x == 0 and y == 0
}

# ---- Hyperbolic Functions ----

fn math_sinh(x: f64) -> f64 {
  return (math_exp(x) - math_exp(0.0 - x)) / 2.0
}

fn math_cosh(x: f64) -> f64 {
  return (math_exp(x) + math_exp(0.0 - x)) / 2.0
}

fn math_tanh(x: f64) -> f64 {
  if x > 20.0 { return 1.0 }
  if x < -20.0 { return -1.0 }
  e2x = math_exp(2.0 * x)
  return (e2x - 1.0) / (e2x + 1.0)
}

# ---- Conversion and Utility ----

fn math_deg_to_rad(deg: f64) -> f64 {
  return deg * PI / 180.0
}

fn math_rad_to_deg(rad: f64) -> f64 {
  return rad * 180.0 / PI
}

fn math_lerp(a: f64, b: f64, t: f64) -> f64 {
  return a + (b - a) * t
}

fn math_map_range(x: f64, in_min: f64, in_max: f64, out_min: f64, out_max: f64) -> f64 {
  return (x - in_min) / (in_max - in_min) * (out_max - out_min) + out_min
}

fn math_is_nan(x: f64) -> bool {
  return x != x
}

fn math_is_inf(x: f64) -> bool {
  return x == INFINITY or x == NEG_INF
}

fn math_is_finite(x: f64) -> bool {
  return not math_is_nan(x) and not math_is_inf(x)
}

fn math_approximately(a: f64, b: f64, tolerance: f64) -> bool {
  return math_abs(a - b) <= tolerance
}

# ---- Integer Math ----

fn math_gcd(a: i32, b: i32) -> i32 {
  a = math_abs_i(a)
  b = math_abs_i(b)
  while b != 0 {
    temp = b
    b = a % b
    a = temp
  }
  return a
}

fn math_lcm(a: i32, b: i32) -> i32 {
  if a == 0 or b == 0 { return 0 }
  return math_abs_i(a * b) / math_gcd(a, b)
}

fn math_is_prime(n: i32) -> bool {
  if n < 2 { return false }
  if n < 4 { return true }
  if n % 2 == 0 or n % 3 == 0 { return false }
  i = 5
  while i * i <= n {
    if n % i == 0 or n % (i + 2) == 0 { return false }
    i = i + 6
  }
  return true
}

fn math_factorial(n: i32) -> i64 {
  if n <= 1 { return 1 }
  result = 1
  i = 2
  while i <= n {
    result = result * i
    i = i + 1
  }
  return result
}

fn math_fibonacci(n: i32) -> i64 {
  if n <= 0 { return 0 }
  if n == 1 { return 1 }
  a = 0
  b = 1
  i = 2
  while i <= n {
    temp = a + b
    a = b
    b = temp
    i = i + 1
  }
  return b
}

fn math_comb(n: i32, k: i32) -> i64 {
  if k < 0 or k > n { return 0 }
  if k == 0 or k == n { return 1 }
  # Use smaller k for efficiency
  if k > n - k { k = n - k }
  result = 1
  i = 0
  while i < k {
    result = result * (n - i) / (i + 1)
    i = i + 1
  }
  return result
}

fn math_perm(n: i32, k: i32) -> i64 {
  if k < 0 or k > n { return 0 }
  result = 1
  i = 0
  while i < k {
    result = result * (n - i)
    i = i + 1
  }
  return result
}

# ---- Random Number Generation (LCG) ----

RAND_STATE = 12345

fn math_seed(s: i32) {
  RAND_STATE = s
}

fn math_rand() -> f64 {
  # Linear Congruential Generator
  RAND_STATE = (RAND_STATE * 1103515245 + 12345) % 2147483648
  return (RAND_STATE as f64) / 2147483648.0
}

fn math_rand_int(min: i32, max: i32) -> i32 {
  r = math_rand()
  return min + ((r * ((max - min + 1) as f64)) as i32)
}

fn math_rand_float(min: f64, max: f64) -> f64 {
  return min + math_rand() * (max - min)
}

# ---- Statistics ----

fn math_sum(arr: array) -> f64 {
  result = 0.0
  i = 0
  while i < length(arr) {
    result = result + (arr[i] as f64)
    i = i + 1
  }
  return result
}

fn math_mean(arr: array) -> f64 {
  if length(arr) == 0 { return 0.0 }
  return math_sum(arr) / (length(arr) as f64)
}

fn math_variance(arr: array) -> f64 {
  if length(arr) <= 1 { return 0.0 }
  m = math_mean(arr)
  sum_sq = 0.0
  i = 0
  while i < length(arr) {
    diff = (arr[i] as f64) - m
    sum_sq = sum_sq + diff * diff
    i = i + 1
  }
  return sum_sq / (length(arr) as f64)
}

fn math_std_dev(arr: array) -> f64 {
  return math_sqrt(math_variance(arr))
}

fn math_median(arr: array) -> f64 {
  if length(arr) == 0 { return 0.0 }
  sorted = math_sort(arr)
  n = length(sorted)
  if n % 2 == 1 {
    return sorted[n / 2] as f64
  }
  return ((sorted[n / 2 - 1] as f64) + (sorted[n / 2] as f64)) / 2.0
}

fn math_sort(arr: array) -> array {
  # Simple insertion sort (for small arrays)
  result = []
  i = 0
  while i < length(arr) {
    push(result, arr[i])
    i = i + 1
  }

  i = 1
  while i < length(result) {
    key = result[i]
    j = i - 1
    while j >= 0 and result[j] > key {
      result[j + 1] = result[j]
      j = j - 1
    }
    result[j + 1] = key
    i = i + 1
  }
  return result
}

# ---- Vector Math (2D) ----

fn vec2_create(x: f64, y: f64) -> any {
  return {"x": x, "y": y}
}

fn vec2_add(a: any, b: any) -> any {
  return vec2_create(a["x"] + b["x"], a["y"] + b["y"])
}

fn vec2_sub(a: any, b: any) -> any {
  return vec2_create(a["x"] - b["x"], a["y"] - b["y"])
}

fn vec2_scale(v: any, s: f64) -> any {
  return vec2_create(v["x"] * s, v["y"] * s)
}

fn vec2_dot(a: any, b: any) -> f64 {
  return a["x"] * b["x"] + a["y"] * b["y"]
}

fn vec2_length(v: any) -> f64 {
  return math_sqrt(v["x"] * v["x"] + v["y"] * v["y"])
}

fn vec2_normalize(v: any) -> any {
  len = vec2_length(v)
  if len == 0.0 { return vec2_create(0.0, 0.0) }
  return vec2_scale(v, 1.0 / len)
}

fn vec2_distance(a: any, b: any) -> f64 {
  return vec2_length(vec2_sub(b, a))
}

fn vec2_angle(a: any, b: any) -> f64 {
  return math_atan2(b["y"] - a["y"], b["x"] - a["x"])
}

# ---- Matrix Math (2x2) ----

fn mat2_create(a: f64, b: f64, c: f64, d: f64) -> any {
  return {"a": a, "b": b, "c": c, "d": d}
}

fn mat2_identity() -> any {
  return mat2_create(1.0, 0.0, 0.0, 1.0)
}

fn mat2_mul(m1: any, m2: any) -> any {
  return mat2_create(
    m1["a"] * m2["a"] + m1["b"] * m2["c"],
    m1["a"] * m2["b"] + m1["b"] * m2["d"],
    m1["c"] * m2["a"] + m1["d"] * m2["c"],
    m1["c"] * m2["b"] + m1["d"] * m2["d"]
  )
}

fn mat2_det(m: any) -> f64 {
  return m["a"] * m["d"] - m["b"] * m["c"]
}

fn mat2_inverse(m: any) -> any {
  det = mat2_det(m)
  if math_abs(det) < EPSILON { return nil }
  inv_det = 1.0 / det
  return mat2_create(
    m["d"] * inv_det,
    0.0 - m["b"] * inv_det,
    0.0 - m["c"] * inv_det,
    m["a"] * inv_det
  )
}

fn mat2_transform(m: any, v: any) -> any {
  return vec2_create(
    m["a"] * v["x"] + m["b"] * v["y"],
    m["c"] * v["x"] + m["d"] * v["y"]
  )
}

fn mat2_rotation(angle: f64) -> any {
  c = math_cos(angle)
  s = math_sin(angle)
  return mat2_create(c, 0.0 - s, s, c)
}

fn mat2_scale_matrix(sx: f64, sy: f64) -> any {
  return mat2_create(sx, 0.0, 0.0, sy)
}

# ================================================================
# FreeLang v4 Core - Standard Library: String Utilities
# Comprehensive string manipulation functions
# ================================================================

# ---- Basic String Operations ----

fn str_length(s: string) -> i32 {
  return length(s)
}

fn str_is_empty(s: string) -> bool {
  return length(s) == 0
}

fn str_char_at(s: string, index: i32) -> string {
  if index < 0 or index >= length(s) { return "" }
  return s[index]
}

fn str_char_code_at(s: string, index: i32) -> i32 {
  if index < 0 or index >= length(s) { return -1 }
  return char_code(s[index])
}

fn str_from_char_code(code: i32) -> string {
  return from_char_code(code)
}

# ---- Substring and Slice ----

fn str_substring(s: string, start: i32, end: i32) -> string {
  if start < 0 { start = 0 }
  if end > length(s) { end = length(s) }
  if start >= end { return "" }

  result = ""
  i = start
  while i < end {
    result = result + s[i]
    i = i + 1
  }
  return result
}

fn str_slice(s: string, start: i32) -> string {
  return str_substring(s, start, length(s))
}

fn str_left(s: string, n: i32) -> string {
  return str_substring(s, 0, n)
}

fn str_right(s: string, n: i32) -> string {
  len = length(s)
  if n >= len { return s }
  return str_substring(s, len - n, len)
}

# ---- Search ----

fn str_index_of(s: string, sub: string) -> i32 {
  if length(sub) == 0 { return 0 }
  if length(sub) > length(s) { return -1 }

  i = 0
  while i <= length(s) - length(sub) {
    match = true
    j = 0
    while j < length(sub) {
      if s[i + j] != sub[j] {
        match = false
        break
      }
      j = j + 1
    }
    if match { return i }
    i = i + 1
  }
  return -1
}

fn str_last_index_of(s: string, sub: string) -> i32 {
  if length(sub) == 0 { return length(s) }
  if length(sub) > length(s) { return -1 }

  i = length(s) - length(sub)
  while i >= 0 {
    match = true
    j = 0
    while j < length(sub) {
      if s[i + j] != sub[j] {
        match = false
        break
      }
      j = j + 1
    }
    if match { return i }
    i = i - 1
  }
  return -1
}

fn str_contains(s: string, sub: string) -> bool {
  return str_index_of(s, sub) >= 0
}

fn str_starts_with(s: string, prefix: string) -> bool {
  if length(prefix) > length(s) { return false }
  i = 0
  while i < length(prefix) {
    if s[i] != prefix[i] { return false }
    i = i + 1
  }
  return true
}

fn str_ends_with(s: string, suffix: string) -> bool {
  if length(suffix) > length(s) { return false }
  offset = length(s) - length(suffix)
  i = 0
  while i < length(suffix) {
    if s[offset + i] != suffix[i] { return false }
    i = i + 1
  }
  return true
}

fn str_count(s: string, sub: string) -> i32 {
  if length(sub) == 0 { return 0 }
  count = 0
  pos = 0
  while pos <= length(s) - length(sub) {
    idx = str_index_of(str_slice(s, pos), sub)
    if idx < 0 { break }
    count = count + 1
    pos = pos + idx + length(sub)
  }
  return count
}

# ---- Case Conversion ----

fn str_to_upper(s: string) -> string {
  result = ""
  i = 0
  while i < length(s) {
    ch = s[i]
    code = char_code(ch)
    if code >= 97 and code <= 122 {  # a-z
      result = result + from_char_code(code - 32)
    } else {
      result = result + ch
    }
    i = i + 1
  }
  return result
}

fn str_to_lower(s: string) -> string {
  result = ""
  i = 0
  while i < length(s) {
    ch = s[i]
    code = char_code(ch)
    if code >= 65 and code <= 90 {  # A-Z
      result = result + from_char_code(code + 32)
    } else {
      result = result + ch
    }
    i = i + 1
  }
  return result
}

fn str_capitalize(s: string) -> string {
  if length(s) == 0 { return "" }
  return str_to_upper(s[0]) + str_to_lower(str_slice(s, 1))
}

fn str_title_case(s: string) -> string {
  result = ""
  capitalize_next = true
  i = 0
  while i < length(s) {
    ch = s[i]
    if ch == " " or ch == "\t" or ch == "\n" {
      result = result + ch
      capitalize_next = true
    } else if capitalize_next {
      result = result + str_to_upper(ch)
      capitalize_next = false
    } else {
      result = result + str_to_lower(ch)
    }
    i = i + 1
  }
  return result
}

fn str_swap_case(s: string) -> string {
  result = ""
  i = 0
  while i < length(s) {
    code = char_code(s[i])
    if code >= 65 and code <= 90 {
      result = result + from_char_code(code + 32)
    } else if code >= 97 and code <= 122 {
      result = result + from_char_code(code - 32)
    } else {
      result = result + s[i]
    }
    i = i + 1
  }
  return result
}

# ---- Trimming ----

fn str_trim(s: string) -> string {
  return str_trim_right(str_trim_left(s))
}

fn str_trim_left(s: string) -> string {
  i = 0
  while i < length(s) {
    ch = s[i]
    if ch != " " and ch != "\t" and ch != "\n" and ch != "\r" {
      break
    }
    i = i + 1
  }
  return str_slice(s, i)
}

fn str_trim_right(s: string) -> string {
  i = length(s) - 1
  while i >= 0 {
    ch = s[i]
    if ch != " " and ch != "\t" and ch != "\n" and ch != "\r" {
      break
    }
    i = i - 1
  }
  return str_substring(s, 0, i + 1)
}

# ---- Split and Join ----

fn str_split(s: string, delimiter: string) -> array {
  result = []
  if length(delimiter) == 0 {
    # Split into characters
    i = 0
    while i < length(s) {
      push(result, s[i])
      i = i + 1
    }
    return result
  }

  current = ""
  i = 0
  while i < length(s) {
    # Check for delimiter match
    match = true
    if i + length(delimiter) <= length(s) {
      j = 0
      while j < length(delimiter) {
        if s[i + j] != delimiter[j] {
          match = false
          break
        }
        j = j + 1
      }
    } else {
      match = false
    }

    if match {
      push(result, current)
      current = ""
      i = i + length(delimiter)
    } else {
      current = current + s[i]
      i = i + 1
    }
  }
  push(result, current)
  return result
}

fn str_join(arr: array, separator: string) -> string {
  if length(arr) == 0 { return "" }
  result = to_string(arr[0])
  i = 1
  while i < length(arr) {
    result = result + separator + to_string(arr[i])
    i = i + 1
  }
  return result
}

# ---- Replace ----

fn str_replace(s: string, old: string, new: string) -> string {
  if length(old) == 0 { return s }
  result = ""
  i = 0
  while i < length(s) {
    # Check for match
    match = true
    if i + length(old) <= length(s) {
      j = 0
      while j < length(old) {
        if s[i + j] != old[j] {
          match = false
          break
        }
        j = j + 1
      }
    } else {
      match = false
    }

    if match {
      result = result + new
      i = i + length(old)
    } else {
      result = result + s[i]
      i = i + 1
    }
  }
  return result
}

fn str_replace_first(s: string, old: string, new: string) -> string {
  idx = str_index_of(s, old)
  if idx < 0 { return s }
  return str_substring(s, 0, idx) + new + str_slice(s, idx + length(old))
}

# ---- Padding ----

fn str_pad_left(s: string, width: i32, pad_char: string) -> string {
  if length(s) >= width { return s }
  result = s
  while length(result) < width {
    result = pad_char + result
  }
  return result
}

fn str_pad_right(s: string, width: i32, pad_char: string) -> string {
  if length(s) >= width { return s }
  result = s
  while length(result) < width {
    result = result + pad_char
  }
  return result
}

fn str_center(s: string, width: i32, pad_char: string) -> string {
  if length(s) >= width { return s }
  total_pad = width - length(s)
  left_pad = total_pad / 2
  right_pad = total_pad - left_pad
  result = ""
  i = 0
  while i < left_pad {
    result = result + pad_char
    i = i + 1
  }
  result = result + s
  i = 0
  while i < right_pad {
    result = result + pad_char
    i = i + 1
  }
  return result
}

# ---- Repeat and Reverse ----

fn str_repeat(s: string, count: i32) -> string {
  result = ""
  i = 0
  while i < count {
    result = result + s
    i = i + 1
  }
  return result
}

fn str_reverse(s: string) -> string {
  result = ""
  i = length(s) - 1
  while i >= 0 {
    result = result + s[i]
    i = i - 1
  }
  return result
}

# ---- Character Classification ----

fn str_is_alpha(ch: string) -> bool {
  code = char_code(ch)
  return (code >= 65 and code <= 90) or (code >= 97 and code <= 122)
}

fn str_is_digit(ch: string) -> bool {
  code = char_code(ch)
  return code >= 48 and code <= 57
}

fn str_is_alnum(ch: string) -> bool {
  return str_is_alpha(ch) or str_is_digit(ch)
}

fn str_is_whitespace(ch: string) -> bool {
  return ch == " " or ch == "\t" or ch == "\n" or ch == "\r"
}

fn str_is_upper(ch: string) -> bool {
  code = char_code(ch)
  return code >= 65 and code <= 90
}

fn str_is_lower(ch: string) -> bool {
  code = char_code(ch)
  return code >= 97 and code <= 122
}

fn str_is_all_alpha(s: string) -> bool {
  if length(s) == 0 { return false }
  i = 0
  while i < length(s) {
    if not str_is_alpha(s[i]) { return false }
    i = i + 1
  }
  return true
}

fn str_is_all_digit(s: string) -> bool {
  if length(s) == 0 { return false }
  i = 0
  while i < length(s) {
    if not str_is_digit(s[i]) { return false }
    i = i + 1
  }
  return true
}

# ---- Encoding/Formatting ----

fn str_to_hex(s: string) -> string {
  hex_chars = "0123456789abcdef"
  result = ""
  i = 0
  while i < length(s) {
    code = char_code(s[i])
    result = result + hex_chars[code / 16] + hex_chars[code % 16]
    i = i + 1
  }
  return result
}

fn str_format_number(n: f64, decimals: i32) -> string {
  # Simple number formatting
  if decimals <= 0 { return to_string(n as i32) }
  int_part = n as i32
  frac_part = n - (int_part as f64)
  if frac_part < 0.0 { frac_part = 0.0 - frac_part }

  # Build decimal string
  frac_str = ""
  i = 0
  while i < decimals {
    frac_part = frac_part * 10.0
    digit = (frac_part as i32) % 10
    frac_str = frac_str + to_string(digit)
    i = i + 1
  }

  return to_string(int_part) + "." + frac_str
}

fn str_escape(s: string) -> string {
  result = ""
  i = 0
  while i < length(s) {
    ch = s[i]
    if ch == "\n" { result = result + "\\n" }
    else if ch == "\t" { result = result + "\\t" }
    else if ch == "\r" { result = result + "\\r" }
    else if ch == "\"" { result = result + "\\\"" }
    else if ch == "\\" { result = result + "\\\\" }
    else { result = result + ch }
    i = i + 1
  }
  return result
}

fn str_unescape(s: string) -> string {
  result = ""
  i = 0
  while i < length(s) {
    if s[i] == "\\" and i + 1 < length(s) {
      next = s[i + 1]
      if next == "n" { result = result + "\n"; i = i + 2 }
      else if next == "t" { result = result + "\t"; i = i + 2 }
      else if next == "r" { result = result + "\r"; i = i + 2 }
      else if next == "\"" { result = result + "\""; i = i + 2 }
      else if next == "\\" { result = result + "\\"; i = i + 2 }
      else { result = result + s[i]; i = i + 1 }
    } else {
      result = result + s[i]
      i = i + 1
    }
  }
  return result
}

# ---- StringBuilder (for efficient concatenation) ----

fn string_builder_new() -> any {
  return {
    "parts": [],
    "total_length": 0
  }
}

fn string_builder_append(sb: any, s: string) -> any {
