# ---- HashMap (Open addressing with linear probing) ----

fn hashmap_new(capacity: i32) -> any {
  if capacity < 16 { capacity = 16 }
  buckets = []
  i = 0
  while i < capacity {
    push(buckets, nil)
    i = i + 1
  }
  return {
    "buckets": buckets,
    "capacity": capacity,
    "size": 0,
    "load_factor_limit": 0.75
  }
}

fn hashmap_hash(key: string, capacity: i32) -> i32 {
  h = 5381
  i = 0
  while i < length(key) {
    h = ((h * 33) + char_code(key[i])) % capacity
    i = i + 1
  }
  if h < 0 { h = 0 - h }
  return h % capacity
}

fn hashmap_put(map: any, key: string, value: any) -> any {
  # Check load factor
  if (map["size"] + 1) as f64 / (map["capacity"] as f64) > map["load_factor_limit"] {
    hashmap_resize(map)
  }

  idx = hashmap_hash(key, map["capacity"])
  probe = 0
  while probe < map["capacity"] {
    bucket_idx = (idx + probe) % map["capacity"]
    bucket = map["buckets"][bucket_idx]

    if bucket == nil {
      # Empty slot - insert
      map["buckets"][bucket_idx] = {"key": key, "value": value, "deleted": false}
      map["size"] = map["size"] + 1
      return map
    }
    if bucket["deleted"] {
      # Tombstone - reuse
      map["buckets"][bucket_idx] = {"key": key, "value": value, "deleted": false}
      map["size"] = map["size"] + 1
      return map
    }
    if bucket["key"] == key {
      # Update existing
      bucket["value"] = value
      return map
    }
    probe = probe + 1
  }
  return map
}

fn hashmap_get(map: any, key: string) -> any {
  idx = hashmap_hash(key, map["capacity"])
  probe = 0
  while probe < map["capacity"] {
    bucket_idx = (idx + probe) % map["capacity"]
    bucket = map["buckets"][bucket_idx]

    if bucket == nil { return nil }
    if not bucket["deleted"] and bucket["key"] == key {
      return bucket["value"]
    }
    probe = probe + 1
  }
  return nil
}

fn hashmap_has(map: any, key: string) -> bool {
  idx = hashmap_hash(key, map["capacity"])
  probe = 0
  while probe < map["capacity"] {
    bucket_idx = (idx + probe) % map["capacity"]
    bucket = map["buckets"][bucket_idx]
    if bucket == nil { return false }
    if not bucket["deleted"] and bucket["key"] == key { return true }
    probe = probe + 1
  }
  return false
}

fn hashmap_remove(map: any, key: string) -> any {
  idx = hashmap_hash(key, map["capacity"])
  probe = 0
  while probe < map["capacity"] {
    bucket_idx = (idx + probe) % map["capacity"]
    bucket = map["buckets"][bucket_idx]
    if bucket == nil { return nil }
    if not bucket["deleted"] and bucket["key"] == key {
      bucket["deleted"] = true
      map["size"] = map["size"] - 1
      return bucket["value"]
    }
    probe = probe + 1
  }
  return nil
}

fn hashmap_resize(map: any) {
  old_buckets = map["buckets"]
  old_cap = map["capacity"]
  new_cap = old_cap * 2
  map["buckets"] = []
  map["capacity"] = new_cap
  map["size"] = 0

  i = 0
  while i < new_cap {
    push(map["buckets"], nil)
    i = i + 1
  }

  i = 0
  while i < old_cap {
    bucket = old_buckets[i]
    if bucket != nil and not bucket["deleted"] {
      hashmap_put(map, bucket["key"], bucket["value"])
    }
    i = i + 1
  }
}

fn hashmap_keys(map: any) -> array {
  result = []
  i = 0
  while i < map["capacity"] {
    bucket = map["buckets"][i]
    if bucket != nil and not bucket["deleted"] {
      push(result, bucket["key"])
    }
    i = i + 1
  }
  return result
}

fn hashmap_values(map: any) -> array {
  result = []
  i = 0
  while i < map["capacity"] {
    bucket = map["buckets"][i]
    if bucket != nil and not bucket["deleted"] {
      push(result, bucket["value"])
    }
    i = i + 1
  }
  return result
}

fn hashmap_entries(map: any) -> array {
  result = []
  i = 0
  while i < map["capacity"] {
    bucket = map["buckets"][i]
    if bucket != nil and not bucket["deleted"] {
      push(result, {"key": bucket["key"], "value": bucket["value"]})
    }
    i = i + 1
  }
  return result
}

fn hashmap_clear(map: any) {
  i = 0
  while i < map["capacity"] {
    map["buckets"][i] = nil
    i = i + 1
  }
  map["size"] = 0
}

# ---- LinkedList ----

fn linkedlist_new() -> any {
  return {
    "head": nil,
    "tail": nil,
    "size": 0
  }
}

fn ll_node(value: any) -> any {
  return {"value": value, "next": nil, "prev": nil}
}

fn linkedlist_push_front(list: any, value: any) -> any {
  node = ll_node(value)
  if list["head"] == nil {
    list["head"] = node
    list["tail"] = node
  } else {
    node["next"] = list["head"]
    list["head"]["prev"] = node
    list["head"] = node
  }
  list["size"] = list["size"] + 1
  return list
}

fn linkedlist_push_back(list: any, value: any) -> any {
  node = ll_node(value)
  if list["tail"] == nil {
    list["head"] = node
    list["tail"] = node
  } else {
    node["prev"] = list["tail"]
    list["tail"]["next"] = node
    list["tail"] = node
  }
  list["size"] = list["size"] + 1
  return list
}

fn linkedlist_pop_front(list: any) -> any {
  if list["head"] == nil { return nil }
  value = list["head"]["value"]
  list["head"] = list["head"]["next"]
  if list["head"] != nil {
    list["head"]["prev"] = nil
  } else {
    list["tail"] = nil
  }
  list["size"] = list["size"] - 1
  return value
}

fn linkedlist_pop_back(list: any) -> any {
  if list["tail"] == nil { return nil }
  value = list["tail"]["value"]
  list["tail"] = list["tail"]["prev"]
  if list["tail"] != nil {
    list["tail"]["next"] = nil
  } else {
    list["head"] = nil
  }
  list["size"] = list["size"] - 1
  return value
}

fn linkedlist_peek_front(list: any) -> any {
  if list["head"] == nil { return nil }
  return list["head"]["value"]
}

fn linkedlist_peek_back(list: any) -> any {
  if list["tail"] == nil { return nil }
  return list["tail"]["value"]
}

fn linkedlist_to_array(list: any) -> array {
  result = []
  node = list["head"]
  while node != nil {
    push(result, node["value"])
    node = node["next"]
  }
  return result
}

