# ---- Set ----

fn set_new() -> any {
  return hashmap_new(16)
}

fn set_add(s: any, value: string) -> any {
  hashmap_put(s, value, true)
  return s
}

fn set_has(s: any, value: string) -> bool {
  return hashmap_has(s, value)
}

fn set_remove(s: any, value: string) -> any {
  hashmap_remove(s, value)
  return s
}

fn set_size(s: any) -> i32 {
  return s["size"]
}

fn set_to_array(s: any) -> array {
  return hashmap_keys(s)
}

fn set_union(a: any, b: any) -> any {
  result = set_new()
  keys_a = hashmap_keys(a)
  keys_b = hashmap_keys(b)
  i = 0
  while i < length(keys_a) {
    set_add(result, keys_a[i])
    i = i + 1
  }
  i = 0
  while i < length(keys_b) {
    set_add(result, keys_b[i])
    i = i + 1
  }
  return result
}

fn set_intersection(a: any, b: any) -> any {
  result = set_new()
  keys_a = hashmap_keys(a)
  i = 0
  while i < length(keys_a) {
    if set_has(b, keys_a[i]) {
      set_add(result, keys_a[i])
    }
    i = i + 1
  }
  return result
}

fn set_difference(a: any, b: any) -> any {
  result = set_new()
  keys_a = hashmap_keys(a)
  i = 0
  while i < length(keys_a) {
    if not set_has(b, keys_a[i]) {
      set_add(result, keys_a[i])
    }
    i = i + 1
  }
  return result
}

# ---- PriorityQueue (Min-heap) ----

fn pq_new() -> any {
  return {"heap": [], "size": 0}
}

fn pq_push(pq: any, priority: f64, value: any) -> any {
  push(pq["heap"], {"priority": priority, "value": value})
  pq["size"] = pq["size"] + 1
  pq_sift_up(pq, pq["size"] - 1)
  return pq
}

fn pq_pop(pq: any) -> any {
  if pq["size"] == 0 { return nil }
  result = pq["heap"][0]["value"]
  pq["size"] = pq["size"] - 1
  if pq["size"] > 0 {
    pq["heap"][0] = pq["heap"][pq["size"]]
    pop(pq["heap"])
    pq_sift_down(pq, 0)
  } else {
    pop(pq["heap"])
  }
  return result
}

fn pq_peek(pq: any) -> any {
  if pq["size"] == 0 { return nil }
  return pq["heap"][0]["value"]
}

fn pq_sift_up(pq: any, idx: i32) {
  while idx > 0 {
    parent = (idx - 1) / 2
    if pq["heap"][idx]["priority"] < pq["heap"][parent]["priority"] {
      # Swap
      temp = pq["heap"][idx]
      pq["heap"][idx] = pq["heap"][parent]
      pq["heap"][parent] = temp
      idx = parent
    } else {
      break
    }
  }
}

fn pq_sift_down(pq: any, idx: i32) {
  while true {
    smallest = idx
    left = 2 * idx + 1
    right = 2 * idx + 2

    if left < pq["size"] and pq["heap"][left]["priority"] < pq["heap"][smallest]["priority"] {
      smallest = left
    }
    if right < pq["size"] and pq["heap"][right]["priority"] < pq["heap"][smallest]["priority"] {
      smallest = right
    }

    if smallest != idx {
      temp = pq["heap"][idx]
      pq["heap"][idx] = pq["heap"][smallest]
      pq["heap"][smallest] = temp
      idx = smallest
    } else {
      break
    }
  }
}

fn pq_is_empty(pq: any) -> bool {
  return pq["size"] == 0
}

fn pq_size(pq: any) -> i32 {
  return pq["size"]
}

# ---- Ring Buffer (Circular Buffer) ----

fn ringbuf_new(capacity: i32) -> any {
  items = []
  i = 0
  while i < capacity {
    push(items, nil)
    i = i + 1
  }
  return {
    "items": items,
    "capacity": capacity,
    "head": 0,
    "tail": 0,
    "size": 0
  }
}

fn ringbuf_push(rb: any, value: any) -> bool {
  if rb["size"] >= rb["capacity"] { return false }  # Full
  rb["items"][rb["tail"]] = value
  rb["tail"] = (rb["tail"] + 1) % rb["capacity"]
  rb["size"] = rb["size"] + 1
  return true
}

fn ringbuf_pop(rb: any) -> any {
  if rb["size"] == 0 { return nil }
  value = rb["items"][rb["head"]]
  rb["items"][rb["head"]] = nil
  rb["head"] = (rb["head"] + 1) % rb["capacity"]
  rb["size"] = rb["size"] - 1
  return value
}

fn ringbuf_peek(rb: any) -> any {
  if rb["size"] == 0 { return nil }
  return rb["items"][rb["head"]]
}

fn ringbuf_is_full(rb: any) -> bool {
  return rb["size"] >= rb["capacity"]
}

fn ringbuf_is_empty(rb: any) -> bool {
  return rb["size"] == 0
}

