# ---- File Modes ----

FILE_READ      = "r"
FILE_WRITE     = "w"
FILE_APPEND    = "a"
FILE_READ_WRITE = "rw"
FILE_BINARY    = "b"

# ---- File Handle ----

fn file_open(path: string, mode: string) -> any {
  return {
    "path": path,
    "mode": mode,
    "handle": _native_file_open(path, mode),
    "is_open": true,
    "position": 0,
    "size": _native_file_size(path),
    "buffer": "",
    "buffer_size": 8192,
    "error": nil
  }
}

fn file_close(f: any) -> bool {
  if not f["is_open"] { return false }
  _native_file_close(f["handle"])
  f["is_open"] = false
  return true
}

fn file_read(f: any) -> string {
  if not f["is_open"] {
    f["error"] = "File not open"
    return ""
  }
  content = _native_file_read_all(f["handle"])
  f["position"] = f["size"]
  return content
}

fn file_read_bytes(f: any, count: i32) -> string {
  if not f["is_open"] {
    f["error"] = "File not open"
    return ""
  }
  data = _native_file_read(f["handle"], count)
  f["position"] = f["position"] + length(data)
  return data
}

fn file_read_line(f: any) -> string {
  if not f["is_open"] {
    f["error"] = "File not open"
    return ""
  }
  line = _native_file_read_line(f["handle"])
  f["position"] = f["position"] + length(line)
  return line
}

fn file_read_lines(f: any) -> array {
  content = file_read(f)
  return str_split(content, "\n")
}

fn file_write(f: any, data: string) -> i32 {
  if not f["is_open"] {
    f["error"] = "File not open"
    return -1
  }
  written = _native_file_write(f["handle"], data)
  f["position"] = f["position"] + written
  if f["position"] > f["size"] {
    f["size"] = f["position"]
  }
  return written
}

fn file_write_line(f: any, line: string) -> i32 {
  return file_write(f, line + "\n")
}

fn file_seek(f: any, position: i32) -> bool {
  if not f["is_open"] { return false }
  _native_file_seek(f["handle"], position)
  f["position"] = position
  return true
}

fn file_flush(f: any) -> bool {
  if not f["is_open"] { return false }
  _native_file_flush(f["handle"])
  return true
}

