# ---- Path Utilities ----

fn path_join(parts: array) -> string {
  result = ""
  i = 0
  while i < length(parts) {
    if i > 0 and length(result) > 0 and result[length(result) - 1] != "/" {
      result = result + "/"
    }
    result = result + parts[i]
    i = i + 1
  }
  return result
}

fn path_dirname(path: string) -> string {
  idx = str_last_index_of(path, "/")
  if idx < 0 { return "." }
  if idx == 0 { return "/" }
  return str_substring(path, 0, idx)
}

fn path_basename(path: string) -> string {
  idx = str_last_index_of(path, "/")
  if idx < 0 { return path }
  return str_slice(path, idx + 1)
}

fn path_extension(path: string) -> string {
  base = path_basename(path)
  idx = str_last_index_of(base, ".")
  if idx < 0 { return "" }
  return str_slice(base, idx + 1)
}

fn path_stem(path: string) -> string {
  base = path_basename(path)
  idx = str_last_index_of(base, ".")
  if idx < 0 { return base }
  return str_substring(base, 0, idx)
}

fn path_is_absolute(path: string) -> bool {
  return length(path) > 0 and path[0] == "/"
}

fn path_normalize(path: string) -> string {
  parts = str_split(path, "/")
  result = []
  i = 0
  while i < length(parts) {
    part = parts[i]
    if part == "." or part == "" {
      # Skip
    } else if part == ".." {
      if length(result) > 0 and result[length(result) - 1] != ".." {
        pop(result)
      } else {
        push(result, part)
      }
    } else {
      push(result, part)
    }
    i = i + 1
  }
  normalized = str_join(result, "/")
  if path_is_absolute(path) {
    return "/" + normalized
  }
  if length(normalized) == 0 { return "." }
  return normalized
}

# ---- Console I/O ----

fn console_print(args: array) {
  i = 0
  while i < length(args) {
    if i > 0 { _native_stdout(" ") }
    _native_stdout(to_string(args[i]))
    i = i + 1
  }
}

fn console_println(args: array) {
  console_print(args)
  _native_stdout("\n")
}

fn console_error(msg: string) {
  _native_stderr(msg + "\n")
}

fn console_input(prompt: string) -> string {
  _native_stdout(prompt)
  return _native_stdin_line()
}

# ---- Formatting ----

fn format(template: string, args: array) -> string {
  result = ""
  arg_idx = 0
  i = 0
  while i < length(template) {
    if template[i] == "{" and i + 1 < length(template) and template[i + 1] == "}" {
      # Placeholder {}
      if arg_idx < length(args) {
        result = result + to_string(args[arg_idx])
        arg_idx = arg_idx + 1
      } else {
        result = result + "{}"
      }
      i = i + 2
    } else if template[i] == "{" and i + 2 < length(template) {
      # Check for {0}, {1}, etc.
      if str_is_digit(template[i + 1]) and template[i + 2] == "}" {
        idx = char_code(template[i + 1]) - 48
        if idx >= 0 and idx < length(args) {
          result = result + to_string(args[idx])
        }
        i = i + 3
      } else {
        result = result + template[i]
        i = i + 1
      }
    } else {
      result = result + template[i]
      i = i + 1
    }
  }
  return result
}

fn sprintf(fmt: string, args: array) -> string {
  return format(fmt, args)
}

fn printf(fmt: string, args: array) {
  _native_stdout(format(fmt, args))
}

fn eprintln(fmt: string, args: array) {
  _native_stderr(format(fmt, args) + "\n")
}

# ---- Buffered Reader ----

fn buffered_reader_new(file: any) -> any {
  return {
    "file": file,
    "buffer": "",
    "buffer_pos": 0,
    "buffer_end": 0,
    "buffer_capacity": 8192,
    "eof": false,
    "lines_read": 0
  }
}

fn buffered_reader_fill(reader: any) -> bool {
  if reader["eof"] { return false }
  data = file_read_bytes(reader["file"], reader["buffer_capacity"])
  if length(data) == 0 {
    reader["eof"] = true
    return false
  }
  reader["buffer"] = data
  reader["buffer_pos"] = 0
  reader["buffer_end"] = length(data)
  return true
}

fn buffered_reader_read_line(reader: any) -> string {
  if reader["eof"] and reader["buffer_pos"] >= reader["buffer_end"] {
    return nil
  }

  line = ""
  while true {
    # Search for newline in buffer
    i = reader["buffer_pos"]
    while i < reader["buffer_end"] {
      if reader["buffer"][i] == "\n" {
        line = line + str_substring(reader["buffer"], reader["buffer_pos"], i)
        reader["buffer_pos"] = i + 1
        reader["lines_read"] = reader["lines_read"] + 1
        return line
      }
      i = i + 1
    }

    # No newline found - consume rest of buffer
    line = line + str_substring(reader["buffer"], reader["buffer_pos"], reader["buffer_end"])
    reader["buffer_pos"] = reader["buffer_end"]

    # Refill buffer
    if not buffered_reader_fill(reader) {
      if length(line) > 0 {
        reader["lines_read"] = reader["lines_read"] + 1
        return line
      }
      return nil
    }
  }
  return line
}

# ---- Buffered Writer ----

fn buffered_writer_new(file: any) -> any {
  return {
    "file": file,
    "buffer": "",
    "buffer_capacity": 8192,
    "bytes_written": 0
  }
}

fn buffered_writer_write(writer: any, data: string) -> i32 {
  writer["buffer"] = writer["buffer"] + data
  if length(writer["buffer"]) >= writer["buffer_capacity"] {
    buffered_writer_flush(writer)
  }
  return length(data)
}

fn buffered_writer_write_line(writer: any, line: string) -> i32 {
  return buffered_writer_write(writer, line + "\n")
}

fn buffered_writer_flush(writer: any) -> i32 {
  if length(writer["buffer"]) == 0 { return 0 }
  written = file_write(writer["file"], writer["buffer"])
  writer["bytes_written"] = writer["bytes_written"] + written
  writer["buffer"] = ""
  return written
}

fn buffered_writer_close(writer: any) {
  buffered_writer_flush(writer)
  file_close(writer["file"])
}

# ---- JSON Serialization (Simple) ----

fn json_stringify(value: any) -> string {
  t = type_of(value)

  if value == nil { return "null" }
  if t == "bool" {
    if value { return "true" }
    return "false"
  }
  if t == "i32" or t == "i64" or t == "f64" {
    return to_string(value)
  }
  if t == "string" {
    return "\"" + str_escape(value) + "\""
  }
  if t == "array" {
    parts = []
    i = 0
    while i < length(value) {
      push(parts, json_stringify(value[i]))
      i = i + 1
    }
    return "[" + str_join(parts, ", ") + "]"
  }
  if t == "dict" or t == "struct" {
    # Object serialization
    return "{" + json_stringify_object(value) + "}"
  }

  return "\"[unknown]\""
}

fn json_stringify_object(obj: any) -> string {
  # Simple key-value serialization
  keys = object_keys(obj)
  parts = []
  i = 0
  while i < length(keys) {
    k = keys[i]
    v = obj[k]
    push(parts, "\"" + str_escape(k) + "\": " + json_stringify(v))
    i = i + 1
  }
  return str_join(parts, ", ")
}

fn json_parse(s: string) -> any {
  # Simple JSON parser
  state = {"input": s, "pos": 0}
  return json_parse_value(state)
}

fn json_parse_value(state: any) -> any {
  json_skip_ws(state)
  if state["pos"] >= length(state["input"]) { return nil }

  ch = state["input"][state["pos"]]

  if ch == "\"" { return json_parse_string(state) }
  if ch == "{" { return json_parse_object(state) }
  if ch == "[" { return json_parse_array(state) }
  if ch == "t" { state["pos"] = state["pos"] + 4; return true }
  if ch == "f" { state["pos"] = state["pos"] + 5; return false }
  if ch == "n" { state["pos"] = state["pos"] + 4; return nil }
  if str_is_digit(ch) or ch == "-" { return json_parse_number(state) }

  return nil
}

fn json_skip_ws(state: any) {
  while state["pos"] < length(state["input"]) {
    ch = state["input"][state["pos"]]
    if ch != " " and ch != "\t" and ch != "\n" and ch != "\r" { break }
    state["pos"] = state["pos"] + 1
  }
}

fn json_parse_string(state: any) -> string {
  state["pos"] = state["pos"] + 1  # Skip opening quote
  result = ""
  while state["pos"] < length(state["input"]) {
    ch = state["input"][state["pos"]]
    if ch == "\"" {
      state["pos"] = state["pos"] + 1
      return result
    }
    if ch == "\\" {
      state["pos"] = state["pos"] + 1
      esc = state["input"][state["pos"]]
      if esc == "n" { result = result + "\n" }
      else if esc == "t" { result = result + "\t" }
      else if esc == "\"" { result = result + "\"" }
      else if esc == "\\" { result = result + "\\" }
      else { result = result + esc }
    } else {
      result = result + ch
    }
    state["pos"] = state["pos"] + 1
  }
  return result
}

fn json_parse_number(state: any) -> any {
  start = state["pos"]
  is_float = false
  if state["input"][state["pos"]] == "-" { state["pos"] = state["pos"] + 1 }
  while state["pos"] < length(state["input"]) and str_is_digit(state["input"][state["pos"]]) {
    state["pos"] = state["pos"] + 1
  }
  if state["pos"] < length(state["input"]) and state["input"][state["pos"]] == "." {
    is_float = true
    state["pos"] = state["pos"] + 1
    while state["pos"] < length(state["input"]) and str_is_digit(state["input"][state["pos"]]) {
      state["pos"] = state["pos"] + 1
    }
  }
  num_str = str_substring(state["input"], start, state["pos"])
  if is_float { return to_float(num_str) }
  return to_int(num_str)
}

fn json_parse_object(state: any) -> any {
  state["pos"] = state["pos"] + 1  # Skip {
  result = {}
  json_skip_ws(state)
  if state["input"][state["pos"]] == "}" {
    state["pos"] = state["pos"] + 1
    return result
  }
  while true {
    json_skip_ws(state)
    key = json_parse_string(state)
    json_skip_ws(state)
    state["pos"] = state["pos"] + 1  # Skip :
    value = json_parse_value(state)
    result[key] = value
    json_skip_ws(state)
    if state["pos"] >= length(state["input"]) { break }
    if state["input"][state["pos"]] == "}" {
      state["pos"] = state["pos"] + 1
      break
    }
    state["pos"] = state["pos"] + 1  # Skip ,
  }
  return result
}

fn json_parse_array(state: any) -> array {
  state["pos"] = state["pos"] + 1  # Skip [
  result = []
  json_skip_ws(state)
  if state["input"][state["pos"]] == "]" {
    state["pos"] = state["pos"] + 1
    return result
  }
  while true {
    value = json_parse_value(state)
    push(result, value)
    json_skip_ws(state)
    if state["pos"] >= length(state["input"]) { break }
    if state["input"][state["pos"]] == "]" {
      state["pos"] = state["pos"] + 1
      break
    }
    state["pos"] = state["pos"] + 1  # Skip ,
  }
  return result
}

# ================================================================
# FreeLang v4 Core - Runtime System
# Memory management, error handling, runtime support
# ================================================================

# ---- Runtime Configuration ----

RT_STACK_SIZE       = 65536     # 64KB stack
RT_HEAP_INITIAL     = 1048576   # 1MB initial heap
RT_HEAP_MAX         = 67108864  # 64MB max heap
RT_GC_THRESHOLD     = 0.75      # GC when 75% full
RT_CALL_DEPTH_MAX   = 1024      # Max recursion depth
RT_STRING_INTERN_MAX = 4096     # Max interned strings

# ---- Error Types ----

ERR_NONE            = 0
ERR_TYPE_ERROR      = 1
ERR_REFERENCE_ERROR = 2
ERR_RANGE_ERROR     = 3
ERR_SYNTAX_ERROR    = 4
ERR_RUNTIME_ERROR   = 5
ERR_STACK_OVERFLOW  = 6
ERR_OUT_OF_MEMORY   = 7
ERR_DIVISION_BY_ZERO = 8
ERR_INDEX_OUT_OF_BOUNDS = 9
ERR_NULL_POINTER    = 10
ERR_ASSERTION_FAILED = 11
ERR_IO_ERROR        = 12
ERR_TIMEOUT         = 13

# ---- Runtime Error ----

fn rt_error(code: i32, message: string, location: any) -> any {
  return {
    "code": code,
    "message": message,
    "location": location,
    "stack_trace": [],
    "timestamp": time_now()
  }
}

fn rt_error_name(code: i32) -> string {
  if code == ERR_NONE { return "NoError" }
  if code == ERR_TYPE_ERROR { return "TypeError" }
  if code == ERR_REFERENCE_ERROR { return "ReferenceError" }
  if code == ERR_RANGE_ERROR { return "RangeError" }
  if code == ERR_SYNTAX_ERROR { return "SyntaxError" }
  if code == ERR_RUNTIME_ERROR { return "RuntimeError" }
  if code == ERR_STACK_OVERFLOW { return "StackOverflow" }
  if code == ERR_OUT_OF_MEMORY { return "OutOfMemory" }
  if code == ERR_DIVISION_BY_ZERO { return "DivisionByZero" }
  if code == ERR_INDEX_OUT_OF_BOUNDS { return "IndexOutOfBounds" }
  if code == ERR_NULL_POINTER { return "NullPointer" }
  if code == ERR_ASSERTION_FAILED { return "AssertionFailed" }
  if code == ERR_IO_ERROR { return "IOError" }
  if code == ERR_TIMEOUT { return "Timeout" }
  return "UnknownError"
}

fn rt_error_format(err: any) -> string {
  result = rt_error_name(err["code"]) + ": " + err["message"]
  if err["location"] != nil {
    loc = err["location"]
    if loc["file"] != nil {
      result = result + "\n  at " + loc["file"] + ":" + to_string(loc["line"])
    }
  }
  # Stack trace
  i = 0
  while i < length(err["stack_trace"]) {
    frame = err["stack_trace"][i]
    result = result + "\n  at " + frame["fn_name"]
    if frame["line"] > 0 {
      result = result + " (line " + to_string(frame["line"]) + ")"
    }
    i = i + 1
  }
  return result
}

# ---- Runtime State ----

fn rt_create() -> any {
  return {
    # Memory
    "heap_size": RT_HEAP_INITIAL,
    "heap_used": 0,
    "heap_max": RT_HEAP_MAX,
    "gc_threshold": RT_GC_THRESHOLD,
    "gc_runs": 0,
    "gc_total_collected": 0,
    "gc_total_time": 0,

    # Stack
    "stack_size": RT_STACK_SIZE,
    "stack_depth": 0,
    "max_stack_depth": RT_CALL_DEPTH_MAX,

    # Error handling
    "errors": [],
    "error_count": 0,
    "panic_handler": nil,
    "catch_stack": [],

    # String interning
    "intern_table": {},
    "intern_count": 0,

    # Metrics
    "allocations": 0,
    "deallocations": 0,
    "total_allocated": 0,
    "peak_memory": 0,
    "start_time": time_now(),
    "instructions_executed": 0,

    # Status
    "running": false,
    "paused": false,
    "exit_code": 0
  }
}

# ---- Memory Management ----

fn rt_alloc(rt: any, size: i32) -> any {
  # Check heap capacity
  if rt["heap_used"] + size > rt["heap_size"] {
    # Try GC first
    rt_gc(rt)
    if rt["heap_used"] + size > rt["heap_size"] {
      # Try growing heap
      if rt["heap_size"] < rt["heap_max"] {
        new_size = rt["heap_size"] * 2
        if new_size > rt["heap_max"] { new_size = rt["heap_max"] }
        rt["heap_size"] = new_size
      } else {
        rt_push_error(rt, rt_error(ERR_OUT_OF_MEMORY,
          "Heap exhausted: " + to_string(rt["heap_used"]) + "/" + to_string(rt["heap_size"]),
          nil))
        return nil
      }
    }
  }

  rt["heap_used"] = rt["heap_used"] + size
  rt["allocations"] = rt["allocations"] + 1
  rt["total_allocated"] = rt["total_allocated"] + size
  if rt["heap_used"] > rt["peak_memory"] {
    rt["peak_memory"] = rt["heap_used"]
  }

  return {
    "ptr": rt["allocations"],  # Simulated pointer
    "size": size,
    "marked": false,
    "generation": 0
  }
}

fn rt_free(rt: any, obj: any) {
  if obj == nil { return }
  rt["heap_used"] = rt["heap_used"] - obj["size"]
  rt["deallocations"] = rt["deallocations"] + 1
}

fn rt_gc(rt: any) {
  start = time_now()
  rt["gc_runs"] = rt["gc_runs"] + 1

  # Mark phase (simulated)
  initial_used = rt["heap_used"]

  # Sweep phase: collect unreachable objects
  # In a real implementation, this would traverse the heap
  collected = initial_used / 4  # Estimate: collect ~25%
  rt["heap_used"] = rt["heap_used"] - collected
  if rt["heap_used"] < 0 { rt["heap_used"] = 0 }

  elapsed = time_now() - start
  rt["gc_total_collected"] = rt["gc_total_collected"] + collected
  rt["gc_total_time"] = rt["gc_total_time"] + elapsed

  return {
    "collected": collected,
    "time_ms": elapsed,
    "heap_before": initial_used,
    "heap_after": rt["heap_used"]
  }
}

fn rt_should_gc(rt: any) -> bool {
  return (rt["heap_used"] as f64) / (rt["heap_size"] as f64) > rt["gc_threshold"]
}

# ---- String Interning ----

fn rt_intern_string(rt: any, s: string) -> string {
  if rt["intern_table"][s] != nil {
    return rt["intern_table"][s]
  }
  if rt["intern_count"] >= RT_STRING_INTERN_MAX {
    return s  # Table full, return uninterned
  }
  rt["intern_table"][s] = s
  rt["intern_count"] = rt["intern_count"] + 1
  return s
}

# ---- Error Handling ----

fn rt_push_error(rt: any, err: any) {
  push(rt["errors"], err)
  rt["error_count"] = rt["error_count"] + 1

  # Check for panic
  if err["code"] == ERR_STACK_OVERFLOW or err["code"] == ERR_OUT_OF_MEMORY {
    if rt["panic_handler"] != nil {
      rt["panic_handler"](err)
    }
  }
}

fn rt_pop_error(rt: any) -> any {
  if length(rt["errors"]) == 0 { return nil }
  return pop(rt["errors"])
}

fn rt_has_error(rt: any) -> bool {
  return length(rt["errors"]) > 0
}

fn rt_clear_errors(rt: any) {
  rt["errors"] = []
}

fn rt_try_begin(rt: any) {
  push(rt["catch_stack"], length(rt["errors"]))
}

fn rt_try_end(rt: any) -> any {
  if length(rt["catch_stack"]) == 0 { return nil }
  saved = pop(rt["catch_stack"])
  if length(rt["errors"]) > saved {
    # Errors occurred - collect them
    caught = []
    while length(rt["errors"]) > saved {
      push(caught, pop(rt["errors"]))
    }
    return caught
  }
  return nil
}

# ---- Stack Frame Management ----

fn rt_push_frame(rt: any, fn_name: string, line: i32) -> bool {
  rt["stack_depth"] = rt["stack_depth"] + 1
  if rt["stack_depth"] > rt["max_stack_depth"] {
    rt_push_error(rt, rt_error(ERR_STACK_OVERFLOW,
      "Stack depth exceeded " + to_string(rt["max_stack_depth"]) + " in " + fn_name,
      {"fn": fn_name, "line": line}))
    return false
  }
  return true
}

fn rt_pop_frame(rt: any) {
  if rt["stack_depth"] > 0 {
    rt["stack_depth"] = rt["stack_depth"] - 1
  }
}

# ---- Bounds Checking ----

fn rt_check_index(rt: any, arr: array, index: i32) -> bool {
  if index < 0 or index >= length(arr) {
    rt_push_error(rt, rt_error(ERR_INDEX_OUT_OF_BOUNDS,
      "Index " + to_string(index) + " out of bounds for array of length " + to_string(length(arr)),
      nil))
    return false
  }
  return true
}

fn rt_check_null(rt: any, value: any, name: string) -> bool {
  if value == nil {
    rt_push_error(rt, rt_error(ERR_NULL_POINTER,
      "Null pointer dereference: " + name,
      nil))
    return false
  }
  return true
}

fn rt_check_division(rt: any, divisor: any) -> bool {
  if divisor == 0 or divisor == 0.0 {
    rt_push_error(rt, rt_error(ERR_DIVISION_BY_ZERO,
      "Division by zero",
      nil))
    return false
  }
  return true
}

# ---- Assertions ----

fn rt_assert(rt: any, condition: bool, message: string) {
  if not condition {
    rt_push_error(rt, rt_error(ERR_ASSERTION_FAILED, message, nil))
  }
}

fn rt_assert_eq(rt: any, actual: any, expected: any, message: string) {
  if actual != expected {
    rt_push_error(rt, rt_error(ERR_ASSERTION_FAILED,
      message + ": expected " + to_string(expected) + " but got " + to_string(actual),
      nil))
  }
}

# ---- Runtime Metrics ----

fn rt_metrics(rt: any) -> any {
  elapsed = time_now() - rt["start_time"]
  return {
    # Memory
    "heap_used": rt["heap_used"],
    "heap_size": rt["heap_size"],
    "heap_utilization": (rt["heap_used"] * 100.0) / (rt["heap_size"] as f64),
    "peak_memory": rt["peak_memory"],
    "allocations": rt["allocations"],
    "deallocations": rt["deallocations"],
    "total_allocated": rt["total_allocated"],

    # GC
    "gc_runs": rt["gc_runs"],
    "gc_total_collected": rt["gc_total_collected"],
    "gc_total_time": rt["gc_total_time"],
    "gc_avg_time": if rt["gc_runs"] > 0 { rt["gc_total_time"] / rt["gc_runs"] } else { 0 },

    # Stack
    "stack_depth": rt["stack_depth"],
    "max_stack_depth_used": rt["stack_depth"],

    # Errors
    "error_count": rt["error_count"],
    "errors_active": length(rt["errors"]),

    # Performance
    "uptime_ms": elapsed,
    "instructions_executed": rt["instructions_executed"],
    "instructions_per_sec": if elapsed > 0 { (rt["instructions_executed"] * 1000) / elapsed } else { 0 },

    # String interning
    "interned_strings": rt["intern_count"]
  }
}

fn rt_metrics_report(rt: any) -> string {
  m = rt_metrics(rt)
  sb = string_builder_new()
  string_builder_append_line(sb, "=== FreeLang v4 Runtime Metrics ===")
  string_builder_append_line(sb, "Heap: " + to_string(m["heap_used"]) + "/" + to_string(m["heap_size"]) + " bytes (" + str_format_number(m["heap_utilization"], 1) + "%)")
  string_builder_append_line(sb, "Peak: " + to_string(m["peak_memory"]) + " bytes")
  string_builder_append_line(sb, "Alloc: " + to_string(m["allocations"]) + " / Free: " + to_string(m["deallocations"]))
  string_builder_append_line(sb, "GC runs: " + to_string(m["gc_runs"]) + " (collected " + to_string(m["gc_total_collected"]) + " bytes)")
  string_builder_append_line(sb, "Errors: " + to_string(m["error_count"]))
  string_builder_append_line(sb, "Uptime: " + to_string(m["uptime_ms"]) + "ms")
  string_builder_append_line(sb, "Instructions: " + to_string(m["instructions_executed"]))
  return string_builder_to_string(sb)
}

# ---- Timeout Support ----

fn rt_with_timeout(rt: any, timeout_ms: i32, callback: any) -> any {
  start = time_now()
  result = callback()
  elapsed = time_now() - start

  if elapsed > timeout_ms {
    rt_push_error(rt, rt_error(ERR_TIMEOUT,
      "Operation exceeded timeout of " + to_string(timeout_ms) + "ms (took " + to_string(elapsed) + "ms)",
      nil))
    return nil
  }
  return result
}

# ---- Graceful Shutdown ----

fn rt_shutdown(rt: any) -> any {
  rt["running"] = false

  # Final GC
  gc_result = rt_gc(rt)

  # Generate final report
  metrics = rt_metrics(rt)

  return {
    "exit_code": rt["exit_code"],
    "metrics": metrics,
    "gc_final": gc_result,
    "errors": rt["errors"],
    "clean_shutdown": rt["error_count"] == 0
  }
}

# ================================================================
# FreeLang v4 Core - Optimization Passes
# Dead code elimination, constant propagation, strength reduction,
# loop optimization, inlining
# ================================================================

# ---- Optimization Level Configuration ----

OPT_LEVEL_O0 = 0  # No optimization
OPT_LEVEL_O1 = 1  # Basic: constant folding, dead code elimination
OPT_LEVEL_O2 = 2  # Moderate: + strength reduction, loop optimization
OPT_LEVEL_O3 = 3  # Aggressive: + inlining, vectorization hints

# ---- Optimization Pass Registry ----

fn create_pass_manager(opt_level: i32) -> any {
  pm = {
    "level": opt_level,
    "passes": [],
    "stats": {
      "total_passes": 0,
      "instructions_removed": 0,
      "constants_folded": 0,
      "branches_eliminated": 0,
      "functions_inlined": 0,
      "strength_reduced": 0,
      "loops_optimized": 0,
      "total_time": 0
    }
  }

  # Register passes based on level
  if opt_level >= 1 {
    push(pm["passes"], {"name": "constant_propagation", "fn": pass_constant_propagation})
    push(pm["passes"], {"name": "constant_folding", "fn": pass_constant_folding})
    push(pm["passes"], {"name": "dead_code_elimination", "fn": pass_dead_code_elimination})
    push(pm["passes"], {"name": "copy_propagation", "fn": pass_copy_propagation})
  }
  if opt_level >= 2 {
    push(pm["passes"], {"name": "strength_reduction", "fn": pass_strength_reduction})
    push(pm["passes"], {"name": "common_subexpr_elimination", "fn": pass_cse})
    push(pm["passes"], {"name": "loop_invariant_motion", "fn": pass_licm})
    push(pm["passes"], {"name": "loop_unrolling", "fn": pass_loop_unrolling})
  }
  if opt_level >= 3 {
    push(pm["passes"], {"name": "function_inlining", "fn": pass_inlining})
    push(pm["passes"], {"name": "tail_call_optimization", "fn": pass_tco})
    push(pm["passes"], {"name": "peephole", "fn": pass_peephole})
  }

  return pm
}

fn run_passes(pm: any, ir_mod: any) -> any {
  i = 0
  while i < length(pm["passes"]) {
    pass = pm["passes"][i]
    start = time_now()
    ir_mod = pass["fn"](ir_mod, pm["stats"])
    elapsed = time_now() - start
    pm["stats"]["total_passes"] = pm["stats"]["total_passes"] + 1
    pm["stats"]["total_time"] = pm["stats"]["total_time"] + elapsed
    i = i + 1
  }
  return ir_mod
}

# ---- Pass 1: Constant Propagation ----

fn pass_constant_propagation(ir_mod: any, stats: any) -> any {
  # Track known constant values for each variable
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    constants = {}  # variable -> constant value

    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]

        # If we're storing a constant, record it
        if instr["op"] == IR_CONST_INT or instr["op"] == IR_CONST_FLOAT or
           instr["op"] == IR_CONST_BOOL or instr["op"] == IR_CONST_STR {
          if instr["dest"] != nil {
            constants[instr["dest"]] = {"op": instr["op"], "value": instr["src1"]}
          }
        }

        # Replace uses of known constants
        if instr["src1"] != nil and constants[instr["src1"]] != nil {
          const_info = constants[instr["src1"]]
          instr["src1"] = const_info["value"]
          stats["constants_folded"] = stats["constants_folded"] + 1
        }
        if instr["src2"] != nil and constants[instr["src2"]] != nil {
          const_info = constants[instr["src2"]]
          instr["src2"] = const_info["value"]
          stats["constants_folded"] = stats["constants_folded"] + 1
        }

        # Kill constant when variable is reassigned
        if instr["dest"] != nil and instr["op"] != IR_CONST_INT and
           instr["op"] != IR_CONST_FLOAT and instr["op"] != IR_CONST_BOOL {
          constants[instr["dest"]] = nil
        }

        k = k + 1
      }
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

# ---- Pass 2: Constant Folding ----

fn pass_constant_folding(ir_mod: any, stats: any) -> any {
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      new_instrs = []
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]
        folded = try_fold_constant(instr)
        if folded != nil {
          push(new_instrs, folded)
          stats["constants_folded"] = stats["constants_folded"] + 1
        } else {
          push(new_instrs, instr)
        }
        k = k + 1
      }
      bb["instructions"] = new_instrs
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

fn try_fold_constant(instr: any) -> any {
  op = instr["op"]
  s1 = instr["src1"]
  s2 = instr["src2"]

  # Both operands must be literal values
  if type_of(s1) != "i32" and type_of(s1) != "f64" { return nil }
  if s2 != nil and type_of(s2) != "i32" and type_of(s2) != "f64" { return nil }

  result = nil

  if op == IR_ADD and s2 != nil { result = s1 + s2 }
  else if op == IR_SUB and s2 != nil { result = s1 - s2 }
  else if op == IR_MUL and s2 != nil { result = s1 * s2 }
  else if op == IR_DIV and s2 != nil and s2 != 0 { result = s1 / s2 }
  else if op == IR_MOD and s2 != nil and s2 != 0 { result = s1 % s2 }
  else if op == IR_NEG { result = 0 - s1 }
  else if op == IR_EQ and s2 != nil { result = s1 == s2 }
  else if op == IR_NEQ and s2 != nil { result = s1 != s2 }
  else if op == IR_LT and s2 != nil { result = s1 < s2 }
  else if op == IR_GT and s2 != nil { result = s1 > s2 }
  else if op == IR_LTE and s2 != nil { result = s1 <= s2 }
  else if op == IR_GTE and s2 != nil { result = s1 >= s2 }
  else { return nil }

  if result == nil { return nil }

  # Determine const type
  const_op = IR_CONST_INT
  if type_of(result) == "f64" { const_op = IR_CONST_FLOAT }
  if type_of(result) == "bool" { const_op = IR_CONST_BOOL }

  return ir_const(instr["dest"], const_op, result)
}

# ---- Pass 3: Dead Code Elimination ----

fn pass_dead_code_elimination(ir_mod: any, stats: any) -> any {
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]

    # Build use set
    used_vars = {}
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]
        if instr["src1"] != nil and type_of(instr["src1"]) == "string" {
          used_vars[instr["src1"]] = true
        }
        if instr["src2"] != nil and type_of(instr["src2"]) == "string" {
          used_vars[instr["src2"]] = true
        }
        # Arguments
        if instr["args"] != nil {
          a = 0
          while a < length(instr["args"]) {
            if type_of(instr["args"][a]) == "string" {
              used_vars[instr["args"][a]] = true
            }
            a = a + 1
          }
        }
        k = k + 1
      }
      j = j + 1
    }

    # Remove instructions whose dest is never used
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      new_instrs = []
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]

        # Keep instructions with side effects or used results
        keep = true
        if instr["dest"] != nil and used_vars[instr["dest"]] != true {
          # No one uses this result
          op = instr["op"]
          # Keep side-effect ops
          if op != IR_CALL and op != IR_STORE and op != IR_STORE_FIELD and
             op != IR_STORE_INDEX and op != IR_RET and op != IR_JMP and
             op != IR_JMP_IF and op != IR_JMP_NIF and op != IR_HALT {
            keep = false
            stats["instructions_removed"] = stats["instructions_removed"] + 1
          }
        }

        if keep {
          push(new_instrs, instr)
        }
        k = k + 1
      }
      bb["instructions"] = new_instrs
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

# ---- Pass 4: Copy Propagation ----

fn pass_copy_propagation(ir_mod: any, stats: any) -> any {
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    copies = {}  # dest -> source (for MOVE instructions)

    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]

        # Track copies
        if instr["op"] == IR_MOVE and instr["dest"] != nil {
          copies[instr["dest"]] = instr["src1"]
        }

        # Replace uses with original source
        if instr["src1"] != nil and copies[instr["src1"]] != nil {
          instr["src1"] = copies[instr["src1"]]
        }
        if instr["src2"] != nil and copies[instr["src2"]] != nil {
          instr["src2"] = copies[instr["src2"]]
        }

        k = k + 1
      }
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

# ---- Pass 5: Strength Reduction ----

fn pass_strength_reduction(ir_mod: any, stats: any) -> any {
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]
        reduced = try_strength_reduce(instr)
        if reduced != nil {
          bb["instructions"][k] = reduced
          stats["strength_reduced"] = stats["strength_reduced"] + 1
        }
        k = k + 1
      }
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

fn try_strength_reduce(instr: any) -> any {
  op = instr["op"]
  s2 = instr["src2"]

  # x * 2 -> x + x (shift left by 1)
  if op == IR_MUL and s2 == 2 {
    return ir_instr(IR_ADD, instr["dest"], instr["src1"], instr["src1"])
  }

  # x * 1 -> x (identity)
  if op == IR_MUL and s2 == 1 {
    return ir_instr(IR_MOVE, instr["dest"], instr["src1"], nil)
  }

  # x * 0 -> 0
  if op == IR_MUL and s2 == 0 {
    return ir_const(instr["dest"], IR_CONST_INT, 0)
  }

  # x + 0 -> x
  if op == IR_ADD and s2 == 0 {
    return ir_instr(IR_MOVE, instr["dest"], instr["src1"], nil)
  }

  # x - 0 -> x
  if op == IR_SUB and s2 == 0 {
    return ir_instr(IR_MOVE, instr["dest"], instr["src1"], nil)
  }

  # x / 1 -> x
  if op == IR_DIV and s2 == 1 {
    return ir_instr(IR_MOVE, instr["dest"], instr["src1"], nil)
  }

  # x * power_of_2 -> x << log2(power)
  if op == IR_MUL and type_of(s2) == "i32" and s2 > 0 {
    shift = is_power_of_two(s2)
    if shift > 0 {
      return ir_instr(IR_SHL, instr["dest"], instr["src1"], shift)
    }
  }

  # x / power_of_2 -> x >> log2(power)
  if op == IR_DIV and type_of(s2) == "i32" and s2 > 0 {
    shift = is_power_of_two(s2)
    if shift > 0 {
      return ir_instr(IR_SHR, instr["dest"], instr["src1"], shift)
    }
  }

  return nil
}

fn is_power_of_two(n: i32) -> i32 {
  if n <= 0 { return -1 }
  if n == 1 { return 0 }
  shift = 0
  val = n
  while val > 1 {
    if val % 2 != 0 { return -1 }
    val = val / 2
    shift = shift + 1
  }
  return shift
}

# ---- Pass 6: Common Subexpression Elimination ----

fn pass_cse(ir_mod: any, stats: any) -> any {
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      # Track computed expressions: "op|src1|src2" -> dest register
      computed = {}
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]
        op = instr["op"]

        # Only CSE pure operations
        if op == IR_ADD or op == IR_SUB or op == IR_MUL or op == IR_DIV or
           op == IR_MOD or op == IR_EQ or op == IR_NEQ or op == IR_LT or
           op == IR_GT or op == IR_LTE or op == IR_GTE {

          key = op + "|" + to_string(instr["src1"]) + "|" + to_string(instr["src2"])
          if computed[key] != nil {
            # Already computed - replace with copy
            bb["instructions"][k] = ir_instr(IR_MOVE, instr["dest"], computed[key], nil)
            stats["instructions_removed"] = stats["instructions_removed"] + 1
          } else {
            computed[key] = instr["dest"]
          }
        }
        k = k + 1
      }
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

# ---- Pass 7: Loop Invariant Code Motion ----

fn pass_licm(ir_mod: any, stats: any) -> any {
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      if bb["loop_header"] {
        # Find invariant instructions in loop body
        loop_vars = collect_loop_defs(func, bb)
        invariants = []

        k = 0
        while k < length(bb["instructions"]) {
          instr = bb["instructions"][k]
          if is_loop_invariant(instr, loop_vars) {
            push(invariants, instr)
            stats["loops_optimized"] = stats["loops_optimized"] + 1
          }
          k = k + 1
        }
        # Move invariants to preheader (in practice)
      }
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

fn collect_loop_defs(func: any, header: any) -> any {
  defs = {}
  # Collect all variables defined in the loop
  i = 0
  while i < length(header["instructions"]) {
    if header["instructions"][i]["dest"] != nil {
      defs[header["instructions"][i]["dest"]] = true
    }
    i = i + 1
  }
  return defs
}

fn is_loop_invariant(instr: any, loop_vars: any) -> bool {
  # An instruction is loop-invariant if its operands are not defined in the loop
  if instr["src1"] != nil and loop_vars[instr["src1"]] == true { return false }
  if instr["src2"] != nil and loop_vars[instr["src2"]] == true { return false }
  # Must be a pure operation (no side effects)
  op = instr["op"]
  if op == IR_CALL or op == IR_STORE or op == IR_STORE_FIELD or
     op == IR_STORE_INDEX or op == IR_ALLOC or op == IR_FREE { return false }
  return true
}

# ---- Pass 8: Loop Unrolling ----

fn pass_loop_unrolling(ir_mod: any, stats: any) -> any {
  # Simple loop unrolling for small loops with known bounds
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      if bb["loop_header"] and length(bb["instructions"]) <= 10 {
        # Small loop - candidate for unrolling
        stats["loops_optimized"] = stats["loops_optimized"] + 1
      }
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

# ---- Pass 9: Function Inlining ----

fn pass_inlining(ir_mod: any, stats: any) -> any {
  # Inline small functions (< 20 instructions)
  inline_threshold = 20

  # Build function size map
  func_sizes = {}
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    size = 0
    j = 0
    while j < length(func["blocks"]) {
      size = size + length(func["blocks"][j]["instructions"])
      j = j + 1
    }
    func_sizes[func["name"]] = size
    i = i + 1
  }

  # Find and mark inlining candidates
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]
        if instr["op"] == IR_CALL and instr["src1"] != nil {
          callee = instr["src1"]
          if func_sizes[callee] != nil and func_sizes[callee] < inline_threshold {
            instr["comment"] = "INLINE_CANDIDATE: " + callee
            stats["functions_inlined"] = stats["functions_inlined"] + 1
          }
        }
        k = k + 1
      }
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

# ---- Pass 10: Tail Call Optimization ----

fn pass_tco(ir_mod: any, stats: any) -> any {
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      instrs = bb["instructions"]
      if length(instrs) >= 2 {
        last = instrs[length(instrs) - 1]
        second_last = instrs[length(instrs) - 2]

        # Pattern: CALL %r = fn(...); RET %r -> tail call
        if last["op"] == IR_RET and second_last["op"] == IR_CALL {
          if last["src1"] == second_last["dest"] {
            # This is a tail call - mark it
            second_last["comment"] = "TAIL_CALL"
            stats["loops_optimized"] = stats["loops_optimized"] + 1
          }
        }
      }
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

# ---- Pass 11: Peephole Optimization ----

fn pass_peephole(ir_mod: any, stats: any) -> any {
  i = 0
  while i < length(ir_mod["functions"]) {
    func = ir_mod["functions"][i]
    j = 0
    while j < length(func["blocks"]) {
      bb = func["blocks"][j]
      new_instrs = []
      k = 0
      while k < length(bb["instructions"]) {
        instr = bb["instructions"][k]
        keep = true

        # Remove NOP instructions
        if instr["op"] == IR_NOP {
          keep = false
          stats["instructions_removed"] = stats["instructions_removed"] + 1
        }

        # Remove self-assignments (MOVE %r0, %r0)
        if instr["op"] == IR_MOVE and instr["dest"] == instr["src1"] {
          keep = false
          stats["instructions_removed"] = stats["instructions_removed"] + 1
        }

        # Double negation: NEG(NEG(x)) -> x
        if instr["op"] == IR_NEG and k + 1 < length(bb["instructions"]) {
          next = bb["instructions"][k + 1]
          if next["op"] == IR_NEG and next["src1"] == instr["dest"] {
            # Replace both with MOVE
            push(new_instrs, ir_instr(IR_MOVE, next["dest"], instr["src1"], nil))
            k = k + 2
            stats["instructions_removed"] = stats["instructions_removed"] + 1
            continue
          }
        }

        if keep {
          push(new_instrs, instr)
        }
        k = k + 1
      }
      bb["instructions"] = new_instrs
      j = j + 1
    }
    i = i + 1
  }
  return ir_mod
}

# ---- Optimization Report ----

fn optimizer_report(pm: any) -> string {
  s = pm["stats"]
  sb = string_builder_new()
  string_builder_append_line(sb, "=== Optimization Report (O" + to_string(pm["level"]) + ") ===")
  string_builder_append_line(sb, "Passes run: " + to_string(s["total_passes"]))
  string_builder_append_line(sb, "Instructions removed: " + to_string(s["instructions_removed"]))
  string_builder_append_line(sb, "Constants folded: " + to_string(s["constants_folded"]))
  string_builder_append_line(sb, "Branches eliminated: " + to_string(s["branches_eliminated"]))
  string_builder_append_line(sb, "Functions inlined: " + to_string(s["functions_inlined"]))
  string_builder_append_line(sb, "Strength reduced: " + to_string(s["strength_reduced"]))
  string_builder_append_line(sb, "Loops optimized: " + to_string(s["loops_optimized"]))
  string_builder_append_line(sb, "Total time: " + to_string(s["total_time"]) + "ms")
  return string_builder_to_string(sb)
}

# ================================================================
# FreeLang v4 Core - Standard Library: Array Utilities
# Functional array operations, sorting, searching
# ================================================================

# ---- Basic Operations ----

fn arr_length(arr: array) -> i32 {
  return length(arr)
}

fn arr_is_empty(arr: array) -> bool {
  return length(arr) == 0
}

fn arr_first(arr: array) -> any {
  if length(arr) == 0 { return nil }
  return arr[0]
}

fn arr_last(arr: array) -> any {
  if length(arr) == 0 { return nil }
  return arr[length(arr) - 1]
}

fn arr_get(arr: array, index: i32) -> any {
  if index < 0 { index = length(arr) + index }
  if index < 0 or index >= length(arr) { return nil }
  return arr[index]
}

# ---- Creation ----

fn arr_range(start: i32, end: i32) -> array {
  result = []
  i = start
  while i < end {
    push(result, i)
    i = i + 1
  }
  return result
}

fn arr_range_step(start: i32, end: i32, step: i32) -> array {
  result = []
  if step == 0 { return result }
  i = start
  if step > 0 {
    while i < end {
      push(result, i)
      i = i + step
    }
  } else {
    while i > end {
      push(result, i)
      i = i + step
    }
  }
  return result
}

fn arr_repeat(value: any, count: i32) -> array {
  result = []
  i = 0
  while i < count {
    push(result, value)
    i = i + 1
  }
  return result
}

fn arr_from(iterable: any) -> array {
  result = []
  if type_of(iterable) == "array" {
    i = 0
    while i < length(iterable) {
      push(result, iterable[i])
      i = i + 1
    }
  }
  return result
}

# ---- Functional Operations ----

fn arr_map(arr: array, fn_map: any) -> array {
  result = []
  i = 0
  while i < length(arr) {
    push(result, fn_map(arr[i]))
    i = i + 1
  }
  return result
}

fn arr_map_indexed(arr: array, fn_map: any) -> array {
  result = []
  i = 0
  while i < length(arr) {
    push(result, fn_map(arr[i], i))
    i = i + 1
  }
  return result
}

fn arr_filter(arr: array, predicate: any) -> array {
  result = []
  i = 0
  while i < length(arr) {
    if predicate(arr[i]) {
      push(result, arr[i])
    }
    i = i + 1
  }
  return result
}

fn arr_reduce(arr: array, initial: any, reducer: any) -> any {
  acc = initial
  i = 0
  while i < length(arr) {
    acc = reducer(acc, arr[i])
    i = i + 1
  }
  return acc
}

fn arr_reduce_right(arr: array, initial: any, reducer: any) -> any {
  acc = initial
  i = length(arr) - 1
  while i >= 0 {
    acc = reducer(acc, arr[i])
    i = i - 1
  }
  return acc
}

fn arr_for_each(arr: array, callback: any) {
  i = 0
  while i < length(arr) {
    callback(arr[i])
    i = i + 1
  }
}

fn arr_flat_map(arr: array, fn_map: any) -> array {
  result = []
  i = 0
  while i < length(arr) {
    mapped = fn_map(arr[i])
    if type_of(mapped) == "array" {
      j = 0
      while j < length(mapped) {
        push(result, mapped[j])
        j = j + 1
      }
    } else {
      push(result, mapped)
    }
    i = i + 1
  }
  return result
}

fn arr_find(arr: array, predicate: any) -> any {
  i = 0
  while i < length(arr) {
    if predicate(arr[i]) {
      return arr[i]
    }
    i = i + 1
  }
  return nil
}

fn arr_find_index(arr: array, predicate: any) -> i32 {
  i = 0
  while i < length(arr) {
    if predicate(arr[i]) {
      return i
    }
    i = i + 1
  }
  return -1
}

fn arr_every(arr: array, predicate: any) -> bool {
  i = 0
  while i < length(arr) {
    if not predicate(arr[i]) {
      return false
    }
    i = i + 1
  }
  return true
}

fn arr_some(arr: array, predicate: any) -> bool {
  i = 0
  while i < length(arr) {
    if predicate(arr[i]) {
      return true
    }
    i = i + 1
  }
  return false
}

fn arr_none(arr: array, predicate: any) -> bool {
  return not arr_some(arr, predicate)
}

fn arr_count(arr: array, predicate: any) -> i32 {
  count = 0
  i = 0
  while i < length(arr) {
    if predicate(arr[i]) {
      count = count + 1
    }
    i = i + 1
  }
  return count
}

# ---- Transformation ----

fn arr_reverse(arr: array) -> array {
  result = []
  i = length(arr) - 1
  while i >= 0 {
    push(result, arr[i])
    i = i - 1
  }
  return result
}

fn arr_flatten(arr: array) -> array {
  result = []
  i = 0
  while i < length(arr) {
    if type_of(arr[i]) == "array" {
      flat = arr_flatten(arr[i])
      j = 0
      while j < length(flat) {
        push(result, flat[j])
        j = j + 1
      }
    } else {
      push(result, arr[i])
    }
    i = i + 1
  }
  return result
}

fn arr_unique(arr: array) -> array {
  result = []
  seen = {}
  i = 0
  while i < length(arr) {
    key = to_string(arr[i])
    if seen[key] == nil {
      push(result, arr[i])
      seen[key] = true
    }
    i = i + 1
  }
  return result
}

fn arr_compact(arr: array) -> array {
  result = []
  i = 0
  while i < length(arr) {
    if arr[i] != nil {
      push(result, arr[i])
    }
    i = i + 1
  }
  return result
}

fn arr_zip(a: array, b: array) -> array {
  result = []
  len = length(a)
  if length(b) < len { len = length(b) }
  i = 0
  while i < len {
    push(result, [a[i], b[i]])
    i = i + 1
  }
  return result
}

fn arr_unzip(arr: array) -> array {
  a = []
  b = []
  i = 0
  while i < length(arr) {
    pair = arr[i]
    push(a, pair[0])
    push(b, pair[1])
    i = i + 1
  }
  return [a, b]
}

fn arr_chunk(arr: array, size: i32) -> array {
  if size <= 0 { return [arr] }
  result = []
  i = 0
  while i < length(arr) {
    chunk = []
    j = 0
    while j < size and i + j < length(arr) {
      push(chunk, arr[i + j])
      j = j + 1
    }
    push(result, chunk)
    i = i + size
  }
  return result
}

fn arr_window(arr: array, size: i32) -> array {
  if size <= 0 or size > length(arr) { return [] }
  result = []
  i = 0
  while i <= length(arr) - size {
    window = []
    j = 0
    while j < size {
      push(window, arr[i + j])
      j = j + 1
    }
    push(result, window)
    i = i + 1
  }
  return result
}

fn arr_take(arr: array, n: i32) -> array {
  result = []
  i = 0
  while i < n and i < length(arr) {
    push(result, arr[i])
    i = i + 1
  }
  return result
}

fn arr_drop(arr: array, n: i32) -> array {
  result = []
  i = n
  while i < length(arr) {
    push(result, arr[i])
    i = i + 1
  }
  return result
}

fn arr_take_while(arr: array, predicate: any) -> array {
  result = []
  i = 0
  while i < length(arr) {
    if not predicate(arr[i]) { break }
    push(result, arr[i])
    i = i + 1
  }
  return result
}

fn arr_drop_while(arr: array, predicate: any) -> array {
  result = []
  dropping = true
  i = 0
  while i < length(arr) {
    if dropping and not predicate(arr[i]) {
      dropping = false
    }
    if not dropping {
      push(result, arr[i])
    }
    i = i + 1
  }
  return result
}

fn arr_partition(arr: array, predicate: any) -> array {
  pass_arr = []
  fail_arr = []
  i = 0
  while i < length(arr) {
    if predicate(arr[i]) {
      push(pass_arr, arr[i])
    } else {
      push(fail_arr, arr[i])
    }
    i = i + 1
  }
  return [pass_arr, fail_arr]
}

fn arr_group_by(arr: array, key_fn: any) -> any {
  groups = {}
  i = 0
  while i < length(arr) {
    key = to_string(key_fn(arr[i]))
    if groups[key] == nil {
      groups[key] = []
    }
    push(groups[key], arr[i])
    i = i + 1
  }
  return groups
}

# ---- Sorting ----

fn arr_sort(arr: array, comparator: any) -> array {
  # Copy the array
  result = arr_from(arr)
  if length(result) <= 1 { return result }

  # Merge sort for stability
  return merge_sort(result, comparator)
}

fn merge_sort(arr: array, cmp: any) -> array {
  n = length(arr)
  if n <= 1 { return arr }

  mid = n / 2
  left = arr_take(arr, mid)
  right = arr_drop(arr, mid)

  left = merge_sort(left, cmp)
  right = merge_sort(right, cmp)

  return merge(left, right, cmp)
}

fn merge(left: array, right: array, cmp: any) -> array {
  result = []
  i = 0
  j = 0
  while i < length(left) and j < length(right) {
    if cmp(left[i], right[j]) <= 0 {
      push(result, left[i])
      i = i + 1
    } else {
      push(result, right[j])
      j = j + 1
    }
  }
  while i < length(left) {
    push(result, left[i])
    i = i + 1
  }
  while j < length(right) {
    push(result, right[j])
    j = j + 1
  }
  return result
}

fn arr_sort_by(arr: array, key_fn: any) -> array {
  return arr_sort(arr, |a, b| {
    ka = key_fn(a)
    kb = key_fn(b)
    if ka < kb { return -1 }
    if ka > kb { return 1 }
    return 0
  })
}

fn arr_sort_asc(arr: array) -> array {
  return arr_sort(arr, |a, b| {
    if a < b { return -1 }
    if a > b { return 1 }
    return 0
  })
}

fn arr_sort_desc(arr: array) -> array {
  return arr_sort(arr, |a, b| {
    if a > b { return -1 }
    if a < b { return 1 }
    return 0
  })
}

# ---- Searching ----

fn arr_binary_search(arr: array, target: any) -> i32 {
  lo = 0
  hi = length(arr) - 1
  while lo <= hi {
    mid = (lo + hi) / 2
    if arr[mid] == target { return mid }
    if arr[mid] < target { lo = mid + 1 }
    else { hi = mid - 1 }
  }
  return -1
}

fn arr_index_of(arr: array, value: any) -> i32 {
  i = 0
  while i < length(arr) {
    if arr[i] == value { return i }
    i = i + 1
  }
  return -1
}

fn arr_last_index_of(arr: array, value: any) -> i32 {
  i = length(arr) - 1
  while i >= 0 {
    if arr[i] == value { return i }
    i = i - 1
  }
  return -1
}

fn arr_includes(arr: array, value: any) -> bool {
  return arr_index_of(arr, value) >= 0
}

fn arr_min(arr: array) -> any {
  if length(arr) == 0 { return nil }
  result = arr[0]
  i = 1
  while i < length(arr) {
    if arr[i] < result { result = arr[i] }
    i = i + 1
  }
  return result
}

fn arr_max(arr: array) -> any {
  if length(arr) == 0 { return nil }
  result = arr[0]
  i = 1
  while i < length(arr) {
    if arr[i] > result { result = arr[i] }
    i = i + 1
  }
  return result
}

fn arr_sum(arr: array) -> f64 {
  result = 0.0
  i = 0
  while i < length(arr) {
    result = result + (arr[i] as f64)
    i = i + 1
  }
  return result
}

fn arr_product(arr: array) -> f64 {
  if length(arr) == 0 { return 0.0 }
  result = 1.0
  i = 0
  while i < length(arr) {
    result = result * (arr[i] as f64)
    i = i + 1
  }
  return result
}

fn arr_average(arr: array) -> f64 {
  if length(arr) == 0 { return 0.0 }
  return arr_sum(arr) / (length(arr) as f64)
}

# ---- Set-like Operations ----

fn arr_union(a: array, b: array) -> array {
  result = arr_from(a)
  i = 0
  while i < length(b) {
    if not arr_includes(result, b[i]) {
      push(result, b[i])
    }
    i = i + 1
  }
  return result
}

fn arr_intersection(a: array, b: array) -> array {
  result = []
  i = 0
  while i < length(a) {
    if arr_includes(b, a[i]) {
      push(result, a[i])
    }
    i = i + 1
  }
  return result
}

fn arr_difference(a: array, b: array) -> array {
  result = []
  i = 0
  while i < length(a) {
    if not arr_includes(b, a[i]) {
      push(result, a[i])
    }
    i = i + 1
  }
  return result
}

fn arr_symmetric_difference(a: array, b: array) -> array {
  return arr_union(arr_difference(a, b), arr_difference(b, a))
}

# ---- String Conversion ----

fn arr_join(arr: array, separator: string) -> string {
  if length(arr) == 0 { return "" }
  result = to_string(arr[0])
  i = 1
  while i < length(arr) {
    result = result + separator + to_string(arr[i])
    i = i + 1
  }
  return result
}

fn arr_to_string(arr: array) -> string {
  return "[" + arr_join(arr, ", ") + "]"
}

# ---- Slice Operations ----

fn arr_slice(arr: array, start: i32, end: i32) -> array {
  if start < 0 { start = length(arr) + start }
  if end < 0 { end = length(arr) + end }
  if start < 0 { start = 0 }
  if end > length(arr) { end = length(arr) }
  result = []
  i = start
  while i < end {
    push(result, arr[i])
    i = i + 1
  }
  return result
}

fn arr_splice(arr: array, start: i32, delete_count: i32, items: array) -> array {
  result = []
  # Before splice point
  i = 0
  while i < start and i < length(arr) {
    push(result, arr[i])
    i = i + 1
  }
  # Insert items
  j = 0
  while j < length(items) {
    push(result, items[j])
    j = j + 1
  }
  # After splice point + deleted
  i = start + delete_count
  while i < length(arr) {
    push(result, arr[i])
    i = i + 1
  }
  return result
}

fn arr_concat(arrays: array) -> array {
  result = []
  i = 0
  while i < length(arrays) {
    arr = arrays[i]
    j = 0
    while j < length(arr) {
      push(result, arr[j])
      j = j + 1
    }
    i = i + 1
  }
  return result
}

# ---- Shuffle ----

fn arr_shuffle(arr: array) -> array {
  result = arr_from(arr)
  i = length(result) - 1
  while i > 0 {
    j = math_rand_int(0, i)
    temp = result[i]
    result[i] = result[j]
    result[j] = temp
    i = i - 1
  }
  return result
}

fn arr_sample(arr: array, n: i32) -> array {
  shuffled = arr_shuffle(arr)
  return arr_take(shuffled, n)
}

