# ---- Concurrency Constants ----

CHAN_UNBUFFERED    = 0
CHAN_BUFFERED      = 1
CHAN_DEFAULT_CAP   = 64

MUTEX_UNLOCKED     = 0
MUTEX_LOCKED       = 1
MUTEX_RECURSIVE    = 2

FUTURE_PENDING     = 0
FUTURE_RESOLVED    = 1
FUTURE_REJECTED    = 2

POOL_DEFAULT_SIZE  = 4
POOL_MAX_SIZE      = 64

TASK_READY         = 0
TASK_RUNNING       = 1
TASK_BLOCKED       = 2
TASK_COMPLETED     = 3
TASK_FAILED        = 4

SCHEDULER_FIFO     = 0
SCHEDULER_PRIORITY = 1
SCHEDULER_ROUND_ROBIN = 2

# ---- Channel ----

fn channel_create(capacity: i32) -> any {
  return {
    "type": if capacity == 0 { CHAN_UNBUFFERED } else { CHAN_BUFFERED },
    "capacity": if capacity == 0 { 1 } else { capacity },
    "buffer": [],
    "closed": false,
    "senders_waiting": [],
    "receivers_waiting": [],
    "send_count": 0,
    "recv_count": 0,
    "created_at": time_now()
  }
}

fn channel_send(ch: any, value: any) -> bool {
  if ch["closed"] {
    return false
  }

  # Check if receiver is waiting (rendezvous)
  if length(ch["receivers_waiting"]) > 0 {
    receiver = pop_front(ch["receivers_waiting"])
    receiver["value"] = value
    receiver["ready"] = true
    ch["send_count"] = ch["send_count"] + 1
    return true
  }

  # Buffered: add to buffer if space
  if ch["type"] == CHAN_BUFFERED and length(ch["buffer"]) < ch["capacity"] {
    push(ch["buffer"], value)
    ch["send_count"] = ch["send_count"] + 1
    return true
  }

  # Block sender (simulated)
  waiter = { "value": value, "ready": false }
  push(ch["senders_waiting"], waiter)
  ch["send_count"] = ch["send_count"] + 1
  return true
}

fn channel_recv(ch: any) -> any {
  # Check buffer first
  if length(ch["buffer"]) > 0 {
    value = pop_front(ch["buffer"])

    # Unblock a waiting sender
    if length(ch["senders_waiting"]) > 0 {
      sender = pop_front(ch["senders_waiting"])
      push(ch["buffer"], sender["value"])
      sender["ready"] = true
    }

    ch["recv_count"] = ch["recv_count"] + 1
    return { "value": value, "ok": true }
  }

  # Check for waiting sender (rendezvous)
  if length(ch["senders_waiting"]) > 0 {
    sender = pop_front(ch["senders_waiting"])
    sender["ready"] = true
    ch["recv_count"] = ch["recv_count"] + 1
    return { "value": sender["value"], "ok": true }
  }

  # Channel closed and empty
  if ch["closed"] {
    return { "value": nil, "ok": false }
  }

  # Block receiver (simulated)
  waiter = { "value": nil, "ready": false }
  push(ch["receivers_waiting"], waiter)
  ch["recv_count"] = ch["recv_count"] + 1
  return { "value": nil, "ok": true }
}

fn channel_try_recv(ch: any) -> any {
  if length(ch["buffer"]) > 0 {
    value = pop_front(ch["buffer"])
    ch["recv_count"] = ch["recv_count"] + 1
    return { "value": value, "ok": true }
  }
  if ch["closed"] {
    return { "value": nil, "ok": false }
  }
  return { "value": nil, "ok": false, "would_block": true }
}

fn channel_close(ch: any) {
  ch["closed"] = true
  # Wake all waiting receivers with nil
  i = 0
  while i < length(ch["receivers_waiting"]) {
    ch["receivers_waiting"][i]["ready"] = true
    ch["receivers_waiting"][i]["value"] = nil
    i = i + 1
  }
  ch["receivers_waiting"] = []
}

fn channel_is_closed(ch: any) -> bool {
  return ch["closed"]
}

fn channel_len(ch: any) -> i32 {
  return length(ch["buffer"])
}

fn channel_stats(ch: any) -> any {
  return {
    "capacity": ch["capacity"],
    "buffered": length(ch["buffer"]),
    "senders_waiting": length(ch["senders_waiting"]),
    "receivers_waiting": length(ch["receivers_waiting"]),
    "total_sent": ch["send_count"],
    "total_received": ch["recv_count"],
    "closed": ch["closed"]
  }
}

# ---- Select (multi-channel) ----

fn select_create() -> any {
  return {
    "cases": [],
    "default": nil,
    "has_default": false
  }
}

fn select_add_recv(sel: any, ch: any, handler: any) {
  push(sel["cases"], {
    "type": "recv",
    "channel": ch,
    "handler": handler
  })
}

fn select_add_send(sel: any, ch: any, value: any, handler: any) {
  push(sel["cases"], {
    "type": "send",
    "channel": ch,
    "value": value,
    "handler": handler
  })
}

fn select_set_default(sel: any, handler: any) {
  sel["default"] = handler
  sel["has_default"] = true
}

fn select_execute(sel: any) -> any {
  # Try each case
  i = 0
  while i < length(sel["cases"]) {
    case = sel["cases"][i]
    if case["type"] == "recv" {
      result = channel_try_recv(case["channel"])
      if result["ok"] {
        if case["handler"] != nil {
          case["handler"](result["value"])
        }
        return { "case": i, "type": "recv", "value": result["value"] }
      }
    } else if case["type"] == "send" {
      ch = case["channel"]
      if not ch["closed"] and length(ch["buffer"]) < ch["capacity"] {
        channel_send(ch, case["value"])
        if case["handler"] != nil {
          case["handler"]()
        }
        return { "case": i, "type": "send" }
      }
    }
    i = i + 1
  }

  # Execute default if no case ready
  if sel["has_default"] {
    if sel["default"] != nil {
      sel["default"]()
    }
    return { "case": -1, "type": "default" }
  }

  return { "case": -1, "type": "blocked" }
}

# ---- Mutex ----

fn mutex_create() -> any {
  return {
    "state": MUTEX_UNLOCKED,
    "owner": nil,
    "waiters": [],
    "lock_count": 0,
    "contention_count": 0,
    "total_lock_time": 0,
    "last_lock_time": 0
  }
}

fn mutex_lock(m: any, owner_id: any) -> bool {
  if m["state"] == MUTEX_UNLOCKED {
    m["state"] = MUTEX_LOCKED
    m["owner"] = owner_id
    m["lock_count"] = m["lock_count"] + 1
    m["last_lock_time"] = time_now()
    return true
  }

  # Already locked
  m["contention_count"] = m["contention_count"] + 1
  push(m["waiters"], { "id": owner_id, "time": time_now() })
  return false
}

fn mutex_try_lock(m: any, owner_id: any) -> bool {
  if m["state"] == MUTEX_UNLOCKED {
    m["state"] = MUTEX_LOCKED
    m["owner"] = owner_id
    m["lock_count"] = m["lock_count"] + 1
    m["last_lock_time"] = time_now()
    return true
  }
  return false
}

fn mutex_unlock(m: any, owner_id: any) -> bool {
  if m["state"] != MUTEX_LOCKED or m["owner"] != owner_id {
    return false  # Not the owner
  }

  elapsed = time_now() - m["last_lock_time"]
  m["total_lock_time"] = m["total_lock_time"] + elapsed

  # Wake next waiter
  if length(m["waiters"]) > 0 {
    next = pop_front(m["waiters"])
    m["owner"] = next["id"]
    m["lock_count"] = m["lock_count"] + 1
    m["last_lock_time"] = time_now()
  } else {
    m["state"] = MUTEX_UNLOCKED
    m["owner"] = nil
  }

  return true
}

fn mutex_is_locked(m: any) -> bool {
  return m["state"] == MUTEX_LOCKED
}

fn mutex_stats(m: any) -> any {
  return {
    "locked": m["state"] == MUTEX_LOCKED,
    "owner": m["owner"],
    "waiters": length(m["waiters"]),
    "total_locks": m["lock_count"],
    "contention": m["contention_count"],
    "total_lock_time_ms": m["total_lock_time"]
  }
}

# ---- RWLock ----

fn rwlock_create() -> any {
  return {
    "readers": 0,
    "writer": nil,
    "write_locked": false,
    "read_waiters": [],
    "write_waiters": [],
    "read_count": 0,
    "write_count": 0
  }
}

fn rwlock_read_lock(rw: any, reader_id: any) -> bool {
  if not rw["write_locked"] and length(rw["write_waiters"]) == 0 {
    rw["readers"] = rw["readers"] + 1
    rw["read_count"] = rw["read_count"] + 1
    return true
  }
  push(rw["read_waiters"], reader_id)
  return false
}

fn rwlock_read_unlock(rw: any) {
  rw["readers"] = rw["readers"] - 1
  if rw["readers"] == 0 and length(rw["write_waiters"]) > 0 {
    # Wake a writer
    writer = pop_front(rw["write_waiters"])
    rw["write_locked"] = true
    rw["writer"] = writer
    rw["write_count"] = rw["write_count"] + 1
  }
}

fn rwlock_write_lock(rw: any, writer_id: any) -> bool {
  if not rw["write_locked"] and rw["readers"] == 0 {
    rw["write_locked"] = true
    rw["writer"] = writer_id
    rw["write_count"] = rw["write_count"] + 1
    return true
  }
  push(rw["write_waiters"], writer_id)
  return false
}

fn rwlock_write_unlock(rw: any) {
  rw["write_locked"] = false
  rw["writer"] = nil

  # Prefer waking readers over writers for fairness
  if length(rw["read_waiters"]) > 0 {
    i = 0
    while i < length(rw["read_waiters"]) {
      rw["readers"] = rw["readers"] + 1
      rw["read_count"] = rw["read_count"] + 1
      i = i + 1
    }
    rw["read_waiters"] = []
  } else if length(rw["write_waiters"]) > 0 {
    writer = pop_front(rw["write_waiters"])
    rw["write_locked"] = true
    rw["writer"] = writer
    rw["write_count"] = rw["write_count"] + 1
  }
}

# ---- Semaphore ----

fn semaphore_create(permits: i32) -> any {
  return {
    "permits": permits,
    "max_permits": permits,
    "waiters": [],
    "acquire_count": 0,
    "release_count": 0
  }
}

fn semaphore_acquire(sem: any) -> bool {
  if sem["permits"] > 0 {
    sem["permits"] = sem["permits"] - 1
    sem["acquire_count"] = sem["acquire_count"] + 1
    return true
  }
  push(sem["waiters"], { "time": time_now() })
  return false
}

fn semaphore_try_acquire(sem: any) -> bool {
  if sem["permits"] > 0 {
    sem["permits"] = sem["permits"] - 1
    sem["acquire_count"] = sem["acquire_count"] + 1
    return true
  }
  return false
}

fn semaphore_release(sem: any) {
  if length(sem["waiters"]) > 0 {
    pop_front(sem["waiters"])
    sem["release_count"] = sem["release_count"] + 1
    sem["acquire_count"] = sem["acquire_count"] + 1
  } else {
    sem["permits"] = sem["permits"] + 1
    if sem["permits"] > sem["max_permits"] {
      sem["permits"] = sem["max_permits"]
    }
  }
  sem["release_count"] = sem["release_count"] + 1
}

fn semaphore_available(sem: any) -> i32 {
  return sem["permits"]
}

# ---- Future / Promise ----

fn future_create() -> any {
  return {
    "state": FUTURE_PENDING,
    "value": nil,
    "error": nil,
    "callbacks": [],
    "error_callbacks": [],
    "finally_callbacks": [],
    "created_at": time_now(),
    "resolved_at": nil
  }
}

fn future_resolve(f: any, value: any) {
  if f["state"] != FUTURE_PENDING { return }
  f["state"] = FUTURE_RESOLVED
  f["value"] = value
  f["resolved_at"] = time_now()

  # Execute callbacks
  i = 0
  while i < length(f["callbacks"]) {
    f["callbacks"][i](value)
    i = i + 1
  }
  # Finally
  i = 0
  while i < length(f["finally_callbacks"]) {
    f["finally_callbacks"][i]()
    i = i + 1
  }
}

fn future_reject(f: any, error: any) {
  if f["state"] != FUTURE_PENDING { return }
  f["state"] = FUTURE_REJECTED
  f["error"] = error
  f["resolved_at"] = time_now()

  # Execute error callbacks
  i = 0
  while i < length(f["error_callbacks"]) {
    f["error_callbacks"][i](error)
    i = i + 1
  }
  # Finally
  i = 0
  while i < length(f["finally_callbacks"]) {
    f["finally_callbacks"][i]()
    i = i + 1
  }
}

fn future_then(f: any, callback: any) -> any {
  next = future_create()
  handler = fn(value) {
    result = callback(value)
    future_resolve(next, result)
  }
  if f["state"] == FUTURE_RESOLVED {
    handler(f["value"])
  } else if f["state"] == FUTURE_PENDING {
    push(f["callbacks"], handler)
  }
  return next
}

fn future_catch(f: any, callback: any) -> any {
  next = future_create()
  handler = fn(error) {
    result = callback(error)
    future_resolve(next, result)
  }
  if f["state"] == FUTURE_REJECTED {
    handler(f["error"])
  } else if f["state"] == FUTURE_PENDING {
    push(f["error_callbacks"], handler)
  }
  return next
}

fn future_finally(f: any, callback: any) {
  if f["state"] != FUTURE_PENDING {
    callback()
  } else {
    push(f["finally_callbacks"], callback)
  }
}

fn future_is_pending(f: any) -> bool {
  return f["state"] == FUTURE_PENDING
}

fn future_is_resolved(f: any) -> bool {
  return f["state"] == FUTURE_RESOLVED
}

fn future_is_rejected(f: any) -> bool {
  return f["state"] == FUTURE_REJECTED
}

fn future_get(f: any) -> any {
  return f["value"]
}

fn future_get_error(f: any) -> any {
  return f["error"]
}

# ---- Future combinators ----

fn future_all(futures: array) -> any {
  combined = future_create()
  results = []
  remaining = length(futures)

  if remaining == 0 {
    future_resolve(combined, [])
    return combined
  }

  i = 0
  while i < length(futures) {
    push(results, nil)
    idx = i
    future_then(futures[i], fn(value) {
      results[idx] = value
      remaining = remaining - 1
      if remaining == 0 {
        future_resolve(combined, results)
      }
    })
    future_catch(futures[i], fn(error) {
      future_reject(combined, error)
    })
    i = i + 1
  }

  return combined
}

fn future_race(futures: array) -> any {
  result = future_create()
  settled = false

  i = 0
  while i < length(futures) {
    future_then(futures[i], fn(value) {
      if not settled {
        settled = true
        future_resolve(result, value)
      }
    })
    future_catch(futures[i], fn(error) {
      if not settled {
        settled = true
        future_reject(result, error)
      }
    })
    i = i + 1
  }

  return result
}

fn future_any(futures: array) -> any {
  result = future_create()
  errors = []
  remaining = length(futures)

  i = 0
  while i < length(futures) {
    future_then(futures[i], fn(value) {
      future_resolve(result, value)
    })
    future_catch(futures[i], fn(error) {
      push(errors, error)
      remaining = remaining - 1
      if remaining == 0 {
        future_reject(result, errors)
      }
    })
    i = i + 1
  }

  return result
}

fn future_from_value(value: any) -> any {
  f = future_create()
  future_resolve(f, value)
  return f
}

fn future_from_error(error: any) -> any {
  f = future_create()
  future_reject(f, error)
  return f
}

# ---- Task Scheduler ----

fn scheduler_create(policy: i32) -> any {
  return {
    "policy": policy,
    "ready_queue": [],
    "blocked_queue": [],
    "completed": [],
    "current_task": nil,
    "task_count": 0,
    "tick": 0,
    "round_robin_index": 0,
    "metrics": {
      "tasks_created": 0,
      "tasks_completed": 0,
      "tasks_failed": 0,
      "total_wait_time": 0,
      "total_run_time": 0
    }
  }
}

fn task_create(scheduler: any, name: string, priority: i32, callback: any) -> any {
  scheduler["task_count"] = scheduler["task_count"] + 1
  task = {
    "id": scheduler["task_count"],
    "name": name,
    "priority": priority,
    "state": TASK_READY,
    "callback": callback,
    "result": nil,
    "error": nil,
    "created_at": time_now(),
    "started_at": nil,
    "completed_at": nil,
    "blocked_on": nil
  }
  push(scheduler["ready_queue"], task)
  scheduler["metrics"]["tasks_created"] = scheduler["metrics"]["tasks_created"] + 1
  return task
}

fn scheduler_next_task(scheduler: any) -> any {
  if length(scheduler["ready_queue"]) == 0 {
    return nil
  }

  if scheduler["policy"] == SCHEDULER_FIFO {
    return pop_front(scheduler["ready_queue"])
  }

  if scheduler["policy"] == SCHEDULER_PRIORITY {
    # Find highest priority task
    best_idx = 0
    best_pri = scheduler["ready_queue"][0]["priority"]
    i = 1
    while i < length(scheduler["ready_queue"]) {
      if scheduler["ready_queue"][i]["priority"] > best_pri {
        best_pri = scheduler["ready_queue"][i]["priority"]
        best_idx = i
      }
      i = i + 1
    }
    task = scheduler["ready_queue"][best_idx]
    # Remove from queue
    new_queue = []
    i = 0
    while i < length(scheduler["ready_queue"]) {
      if i != best_idx {
        push(new_queue, scheduler["ready_queue"][i])
      }
      i = i + 1
    }
    scheduler["ready_queue"] = new_queue
    return task
  }

  if scheduler["policy"] == SCHEDULER_ROUND_ROBIN {
    idx = scheduler["round_robin_index"] % length(scheduler["ready_queue"])
    task = scheduler["ready_queue"][idx]
    new_queue = []
    i = 0
    while i < length(scheduler["ready_queue"]) {
      if i != idx {
        push(new_queue, scheduler["ready_queue"][i])
      }
      i = i + 1
    }
    scheduler["ready_queue"] = new_queue
    scheduler["round_robin_index"] = scheduler["round_robin_index"] + 1
    return task
  }

  return pop_front(scheduler["ready_queue"])
}

fn scheduler_run_task(scheduler: any, task: any) -> any {
  task["state"] = TASK_RUNNING
  task["started_at"] = time_now()
  scheduler["current_task"] = task

  # Execute the task callback
  result = task["callback"]()

  task["result"] = result
  task["state"] = TASK_COMPLETED
  task["completed_at"] = time_now()
  scheduler["current_task"] = nil

  push(scheduler["completed"], task)
  scheduler["metrics"]["tasks_completed"] = scheduler["metrics"]["tasks_completed"] + 1

  run_time = task["completed_at"] - task["started_at"]
  wait_time = task["started_at"] - task["created_at"]
  scheduler["metrics"]["total_run_time"] = scheduler["metrics"]["total_run_time"] + run_time
  scheduler["metrics"]["total_wait_time"] = scheduler["metrics"]["total_wait_time"] + wait_time

  return result
}

fn scheduler_block_task(scheduler: any, task: any, reason: any) {
  task["state"] = TASK_BLOCKED
  task["blocked_on"] = reason
  push(scheduler["blocked_queue"], task)
}

fn scheduler_unblock_task(scheduler: any, task_id: i32) {
  new_blocked = []
  i = 0
  while i < length(scheduler["blocked_queue"]) {
    t = scheduler["blocked_queue"][i]
    if t["id"] == task_id {
      t["state"] = TASK_READY
      t["blocked_on"] = nil
      push(scheduler["ready_queue"], t)
    } else {
      push(new_blocked, t)
    }
    i = i + 1
  }
  scheduler["blocked_queue"] = new_blocked
}

fn scheduler_tick(scheduler: any) -> any {
  scheduler["tick"] = scheduler["tick"] + 1
  task = scheduler_next_task(scheduler)
  if task == nil {
    return { "idle": true, "tick": scheduler["tick"] }
  }
  result = scheduler_run_task(scheduler, task)
  return {
    "idle": false,
    "tick": scheduler["tick"],
    "task_id": task["id"],
    "task_name": task["name"],
    "result": result
  }
}

fn scheduler_run_all(scheduler: any) -> any {
  results = []
  while length(scheduler["ready_queue"]) > 0 {
    r = scheduler_tick(scheduler)
    push(results, r)
  }
  return results
}

fn scheduler_metrics(scheduler: any) -> any {
  m = scheduler["metrics"]
  avg_wait = 0
  avg_run = 0
  if m["tasks_completed"] > 0 {
    avg_wait = m["total_wait_time"] / m["tasks_completed"]
    avg_run = m["total_run_time"] / m["tasks_completed"]
  }
  return {
    "tasks_created": m["tasks_created"],
    "tasks_completed": m["tasks_completed"],
    "tasks_failed": m["tasks_failed"],
    "ready": length(scheduler["ready_queue"]),
    "blocked": length(scheduler["blocked_queue"]),
    "avg_wait_ms": avg_wait,
    "avg_run_ms": avg_run,
    "total_ticks": scheduler["tick"]
  }
}

# ---- WaitGroup ----

fn waitgroup_create() -> any {
  return {
    "count": 0,
    "waiters": [],
    "done_count": 0
  }
}

fn waitgroup_add(wg: any, delta: i32) {
  wg["count"] = wg["count"] + delta
}

fn waitgroup_done(wg: any) {
  wg["count"] = wg["count"] - 1
  wg["done_count"] = wg["done_count"] + 1
  if wg["count"] <= 0 {
    # Notify all waiters
    i = 0
    while i < length(wg["waiters"]) {
      wg["waiters"][i]["ready"] = true
      i = i + 1
    }
    wg["waiters"] = []
  }
}

fn waitgroup_wait(wg: any) -> bool {
  if wg["count"] <= 0 {
    return true
  }
  waiter = { "ready": false }
  push(wg["waiters"], waiter)
  return false  # Would block
}

# ---- Once (execute exactly once) ----

fn once_create() -> any {
  return {
    "executed": false,
    "result": nil
  }
}

fn once_do(o: any, callback: any) -> any {
  if not o["executed"] {
    o["executed"] = true
    o["result"] = callback()
  }
  return o["result"]
}

# ---- Barrier ----

fn barrier_create(parties: i32) -> any {
  return {
    "parties": parties,
    "count": 0,
    "generation": 0,
    "waiters": []
  }
}

fn barrier_arrive(b: any) -> any {
  b["count"] = b["count"] + 1
  if b["count"] >= b["parties"] {
    # All arrived - release all
    gen = b["generation"]
    b["count"] = 0
    b["generation"] = b["generation"] + 1
    i = 0
    while i < length(b["waiters"]) {
      b["waiters"][i]["ready"] = true
      i = i + 1
    }
    b["waiters"] = []
    return { "released": true, "generation": gen }
  }
  waiter = { "ready": false }
  push(b["waiters"], waiter)
  return { "released": false, "generation": b["generation"] }
}

# ---- Atomic Operations ----

fn atomic_create(initial: i32) -> any {
  return {
    "value": initial,
    "version": 0
  }
}

fn atomic_load(a: any) -> i32 {
  return a["value"]
}

fn atomic_store(a: any, value: i32) {
  a["value"] = value
  a["version"] = a["version"] + 1
}

fn atomic_add(a: any, delta: i32) -> i32 {
  old = a["value"]
  a["value"] = a["value"] + delta
  a["version"] = a["version"] + 1
  return old
}

fn atomic_sub(a: any, delta: i32) -> i32 {
  old = a["value"]
  a["value"] = a["value"] - delta
  a["version"] = a["version"] + 1
  return old
}

fn atomic_cas(a: any, expected: i32, desired: i32) -> bool {
  if a["value"] == expected {
    a["value"] = desired
    a["version"] = a["version"] + 1
    return true
  }
  return false
}

fn atomic_swap(a: any, value: i32) -> i32 {
  old = a["value"]
  a["value"] = value
  a["version"] = a["version"] + 1
  return old
}

# ---- Condition Variable ----

fn condvar_create() -> any {
  return {
    "waiters": [],
    "signal_count": 0,
    "broadcast_count": 0
  }
}

fn condvar_wait(cv: any, m: any, owner_id: any) {
  mutex_unlock(m, owner_id)
  waiter = { "ready": false, "id": owner_id }
  push(cv["waiters"], waiter)
  # In simulation: immediately re-lock
  mutex_lock(m, owner_id)
}

fn condvar_signal(cv: any) {
  cv["signal_count"] = cv["signal_count"] + 1
  if length(cv["waiters"]) > 0 {
    waiter = pop_front(cv["waiters"])
    waiter["ready"] = true
  }
}

fn condvar_broadcast(cv: any) {
  cv["broadcast_count"] = cv["broadcast_count"] + 1
  i = 0
  while i < length(cv["waiters"]) {
    cv["waiters"][i]["ready"] = true
    i = i + 1
  }
  cv["waiters"] = []
}

# ---- Thread Pool ----

fn threadpool_create(size: i32) -> any {
  if size < 1 { size = POOL_DEFAULT_SIZE }
  if size > POOL_MAX_SIZE { size = POOL_MAX_SIZE }

  workers = []
  i = 0
  while i < size {
    push(workers, {
      "id": i,
      "busy": false,
      "tasks_completed": 0,
      "total_time": 0
    })
    i = i + 1
  }

  return {
    "size": size,
    "workers": workers,
    "task_queue": [],
    "total_submitted": 0,
    "total_completed": 0,
    "shutdown": false
  }
}

fn threadpool_submit(pool: any, task: any) -> any {
  if pool["shutdown"] {
    return future_from_error("Pool is shut down")
  }

  f = future_create()
  push(pool["task_queue"], {
    "callback": task,
    "future": f,
    "submitted_at": time_now()
  })
  pool["total_submitted"] = pool["total_submitted"] + 1

  # Try to assign to idle worker
  threadpool_dispatch(pool)

  return f
}

fn threadpool_dispatch(pool: any) {
  i = 0
  while i < length(pool["workers"]) and length(pool["task_queue"]) > 0 {
    worker = pool["workers"][i]
    if not worker["busy"] {
      task = pop_front(pool["task_queue"])
      worker["busy"] = true
      start = time_now()

      # Execute task
      result = task["callback"]()
      future_resolve(task["future"], result)

      elapsed = time_now() - start
      worker["busy"] = false
      worker["tasks_completed"] = worker["tasks_completed"] + 1
      worker["total_time"] = worker["total_time"] + elapsed
      pool["total_completed"] = pool["total_completed"] + 1
    }
    i = i + 1
  }
}

fn threadpool_shutdown(pool: any) {
  pool["shutdown"] = true
  # Process remaining tasks
  while length(pool["task_queue"]) > 0 {
    threadpool_dispatch(pool)
  }
}

fn threadpool_stats(pool: any) -> any {
  busy_count = 0
  i = 0
  while i < length(pool["workers"]) {
    if pool["workers"][i]["busy"] {
      busy_count = busy_count + 1
    }
    i = i + 1
  }
  return {
    "pool_size": pool["size"],
    "busy_workers": busy_count,
    "idle_workers": pool["size"] - busy_count,
    "queued_tasks": length(pool["task_queue"]),
    "total_submitted": pool["total_submitted"],
    "total_completed": pool["total_completed"],
    "shutdown": pool["shutdown"]
  }
}

# ================================================================
# FreeLang v4 Core - Result/Option Monad Library
# Functional error handling without exceptions
# ================================================================

# ---- Result Type ----
# Result represents either a success (Ok) or failure (Err)

RESULT_OK  = "ok"
RESULT_ERR = "err"

fn ok(value: any) -> any {
  return {
    "_type": RESULT_OK,
    "_value": value
  }
}

fn err(error: any) -> any {
  return {
    "_type": RESULT_ERR,
    "_error": error
  }
}

fn is_ok(result: any) -> bool {
  return result["_type"] == RESULT_OK
}

fn is_err(result: any) -> bool {
  return result["_type"] == RESULT_ERR
}

fn unwrap(result: any) -> any {
  if result["_type"] == RESULT_ERR {
    # Panic on unwrap of Err
    panic("unwrap called on Err: " + to_string(result["_error"]))
  }
  return result["_value"]
}

fn unwrap_or(result: any, default_val: any) -> any {
  if result["_type"] == RESULT_OK {
    return result["_value"]
  }
  return default_val
}

fn unwrap_or_else(result: any, f: any) -> any {
  if result["_type"] == RESULT_OK {
    return result["_value"]
  }
  return f(result["_error"])
}

fn unwrap_err(result: any) -> any {
  if result["_type"] == RESULT_OK {
    panic("unwrap_err called on Ok: " + to_string(result["_value"]))
  }
  return result["_error"]
}

fn expect(result: any, message: string) -> any {
  if result["_type"] == RESULT_ERR {
    panic(message + ": " + to_string(result["_error"]))
  }
  return result["_value"]
}

fn expect_err(result: any, message: string) -> any {
  if result["_type"] == RESULT_OK {
    panic(message + ": " + to_string(result["_value"]))
  }
  return result["_error"]
}

# ---- Result Combinators ----

fn result_map(result: any, f: any) -> any {
  if result["_type"] == RESULT_OK {
    return ok(f(result["_value"]))
  }
  return result
}

fn result_map_err(result: any, f: any) -> any {
  if result["_type"] == RESULT_ERR {
    return err(f(result["_error"]))
  }
  return result
}

fn result_and_then(result: any, f: any) -> any {
  if result["_type"] == RESULT_OK {
    return f(result["_value"])
  }
  return result
}

fn result_or_else(result: any, f: any) -> any {
  if result["_type"] == RESULT_ERR {
    return f(result["_error"])
  }
  return result
}

fn result_and(r1: any, r2: any) -> any {
  if r1["_type"] == RESULT_OK {
    return r2
  }
  return r1
}

fn result_or(r1: any, r2: any) -> any {
  if r1["_type"] == RESULT_OK {
    return r1
  }
  return r2
}

fn result_flatten(result: any) -> any {
  if result["_type"] == RESULT_OK {
    inner = result["_value"]
    if inner["_type"] == RESULT_OK or inner["_type"] == RESULT_ERR {
      return inner
    }
  }
  return result
}

fn result_inspect(result: any, f: any) -> any {
  if result["_type"] == RESULT_OK {
    f(result["_value"])
  }
  return result
}

fn result_inspect_err(result: any, f: any) -> any {
  if result["_type"] == RESULT_ERR {
    f(result["_error"])
  }
  return result
}

# ---- Result Collection Operations ----

fn result_collect(results: array) -> any {
  # Collect array of Results into Result of array
  values = []
  i = 0
  while i < length(results) {
    if results[i]["_type"] == RESULT_ERR {
      return results[i]
    }
    push(values, results[i]["_value"])
    i = i + 1
  }
  return ok(values)
}

fn result_partition(results: array) -> any {
  # Split results into (oks, errs)
  oks = []
  errs = []
  i = 0
  while i < length(results) {
    if results[i]["_type"] == RESULT_OK {
      push(oks, results[i]["_value"])
    } else {
      push(errs, results[i]["_error"])
    }
    i = i + 1
  }
  return { "oks": oks, "errs": errs }
}

fn result_filter_ok(results: array) -> array {
  oks = []
  i = 0
  while i < length(results) {
    if results[i]["_type"] == RESULT_OK {
      push(oks, results[i]["_value"])
    }
    i = i + 1
  }
  return oks
}

fn result_filter_err(results: array) -> array {
  errs = []
  i = 0
  while i < length(results) {
    if results[i]["_type"] == RESULT_ERR {
      push(errs, results[i]["_error"])
    }
    i = i + 1
  }
  return errs
}

# ---- Result to/from Conversions ----

fn result_to_option(result: any) -> any {
  if result["_type"] == RESULT_OK {
    return some(result["_value"])
  }
  return none()
}

fn result_from_option(opt: any, err_val: any) -> any {
  if opt["_type"] == OPTION_SOME {
    return ok(opt["_value"])
  }
  return err(err_val)
}

fn result_to_string(result: any) -> string {
  if result["_type"] == RESULT_OK {
    return "Ok(" + to_string(result["_value"]) + ")"
  }
  return "Err(" + to_string(result["_error"]) + ")"
}

# ---- Result Try Macro ----

fn result_try(callback: any) -> any {
  # Execute callback, catch errors and return Result
  result = callback()
  if result == nil {
    return err("nil returned")
  }
  return ok(result)
}

fn result_try_catch(callback: any) -> any {
  # Try/catch style error handling
  success = true
  value = nil
  error_msg = nil

  value = callback()
  if value == nil {
    return err("Operation returned nil")
  }
  return ok(value)
}

# ---- Option Type ----
# Option represents either a value (Some) or nothing (None)

OPTION_SOME = "some"
OPTION_NONE = "none"

fn some(value: any) -> any {
  return {
    "_type": OPTION_SOME,
    "_value": value
  }
}

fn none() -> any {
  return {
    "_type": OPTION_NONE,
    "_value": nil
  }
}

fn is_some(opt: any) -> bool {
  return opt["_type"] == OPTION_SOME
}

fn is_none(opt: any) -> bool {
  return opt["_type"] == OPTION_NONE
}

fn option_unwrap(opt: any) -> any {
  if opt["_type"] == OPTION_NONE {
    panic("unwrap called on None")
  }
  return opt["_value"]
}

fn option_unwrap_or(opt: any, default_val: any) -> any {
  if opt["_type"] == OPTION_SOME {
    return opt["_value"]
  }
  return default_val
}

fn option_unwrap_or_else(opt: any, f: any) -> any {
  if opt["_type"] == OPTION_SOME {
    return opt["_value"]
  }
  return f()
}

fn option_expect(opt: any, message: string) -> any {
  if opt["_type"] == OPTION_NONE {
    panic(message)
  }
  return opt["_value"]
}

# ---- Option Combinators ----

fn option_map(opt: any, f: any) -> any {
  if opt["_type"] == OPTION_SOME {
    return some(f(opt["_value"]))
  }
  return opt
}

fn option_and_then(opt: any, f: any) -> any {
  if opt["_type"] == OPTION_SOME {
    return f(opt["_value"])
  }
  return opt
}

fn option_or_else(opt: any, f: any) -> any {
  if opt["_type"] == OPTION_SOME {
    return opt
  }
  return f()
}

fn option_filter(opt: any, predicate: any) -> any {
  if opt["_type"] == OPTION_SOME and predicate(opt["_value"]) {
    return opt
  }
  return none()
}

fn option_and(o1: any, o2: any) -> any {
  if o1["_type"] == OPTION_SOME {
    return o2
  }
  return none()
}

fn option_or(o1: any, o2: any) -> any {
  if o1["_type"] == OPTION_SOME {
    return o1
  }
  return o2
}

fn option_xor(o1: any, o2: any) -> any {
  s1 = o1["_type"] == OPTION_SOME
  s2 = o2["_type"] == OPTION_SOME
  if s1 and not s2 { return o1 }
  if not s1 and s2 { return o2 }
  return none()
}

fn option_flatten(opt: any) -> any {
  if opt["_type"] == OPTION_SOME {
    inner = opt["_value"]
    if inner["_type"] == OPTION_SOME or inner["_type"] == OPTION_NONE {
      return inner
    }
  }
  return opt
}

fn option_zip(o1: any, o2: any) -> any {
  if o1["_type"] == OPTION_SOME and o2["_type"] == OPTION_SOME {
    return some([o1["_value"], o2["_value"]])
  }
  return none()
}

fn option_zip_with(o1: any, o2: any, f: any) -> any {
  if o1["_type"] == OPTION_SOME and o2["_type"] == OPTION_SOME {
    return some(f(o1["_value"], o2["_value"]))
  }
  return none()
}

fn option_to_result(opt: any, err_val: any) -> any {
  if opt["_type"] == OPTION_SOME {
    return ok(opt["_value"])
  }
  return err(err_val)
}

fn option_to_string(opt: any) -> string {
  if opt["_type"] == OPTION_SOME {
    return "Some(" + to_string(opt["_value"]) + ")"
  }
  return "None"
}

fn option_contains(opt: any, value: any) -> bool {
  if opt["_type"] == OPTION_SOME {
    return opt["_value"] == value
  }
  return false
}

# ---- Option Collection Operations ----

fn option_collect(options: array) -> any {
  # Collect array of Options into Option of array
  values = []
  i = 0
  while i < length(options) {
    if options[i]["_type"] == OPTION_NONE {
      return none()
    }
    push(values, options[i]["_value"])
    i = i + 1
  }
  return some(values)
}

fn option_filter_some(options: array) -> array {
  values = []
  i = 0
  while i < length(options) {
    if options[i]["_type"] == OPTION_SOME {
      push(values, options[i]["_value"])
    }
    i = i + 1
  }
  return values
}

fn option_first_some(options: array) -> any {
  i = 0
  while i < length(options) {
    if options[i]["_type"] == OPTION_SOME {
      return options[i]
    }
    i = i + 1
  }
  return none()
}

# ---- Either Type ----

EITHER_LEFT  = "left"
EITHER_RIGHT = "right"

fn left(value: any) -> any {
  return {
    "_type": EITHER_LEFT,
    "_value": value
  }
}

fn right(value: any) -> any {
  return {
    "_type": EITHER_RIGHT,
    "_value": value
  }
}

fn is_left(e: any) -> bool {
  return e["_type"] == EITHER_LEFT
}

fn is_right(e: any) -> bool {
  return e["_type"] == EITHER_RIGHT
}

fn either_map_left(e: any, f: any) -> any {
  if e["_type"] == EITHER_LEFT {
    return left(f(e["_value"]))
  }
  return e
}

fn either_map_right(e: any, f: any) -> any {
  if e["_type"] == EITHER_RIGHT {
    return right(f(e["_value"]))
  }
  return e
}

fn either_fold(e: any, left_fn: any, right_fn: any) -> any {
  if e["_type"] == EITHER_LEFT {
    return left_fn(e["_value"])
  }
  return right_fn(e["_value"])
}

fn either_swap(e: any) -> any {
  if e["_type"] == EITHER_LEFT {
    return right(e["_value"])
  }
  return left(e["_value"])
}

fn either_to_string(e: any) -> string {
  if e["_type"] == EITHER_LEFT {
    return "Left(" + to_string(e["_value"]) + ")"
  }
  return "Right(" + to_string(e["_value"]) + ")"
}

# ---- Validation (accumulating errors) ----

fn validation_ok(value: any) -> any {
  return {
    "_type": "valid",
    "_value": value,
    "_errors": []
  }
}

fn validation_fail(error: any) -> any {
  return {
    "_type": "invalid",
    "_value": nil,
    "_errors": [error]
  }
}

fn validation_is_valid(v: any) -> bool {
  return v["_type"] == "valid"
}

fn validation_is_invalid(v: any) -> bool {
  return v["_type"] == "invalid"
}

fn validation_map(v: any, f: any) -> any {
  if v["_type"] == "valid" {
    return validation_ok(f(v["_value"]))
  }
  return v
}

fn validation_combine(v1: any, v2: any) -> any {
  if v1["_type"] == "valid" and v2["_type"] == "valid" {
    return validation_ok([v1["_value"], v2["_value"]])
  }
  errors = []
  i = 0
  while i < length(v1["_errors"]) {
    push(errors, v1["_errors"][i])
    i = i + 1
  }
  i = 0
  while i < length(v2["_errors"]) {
    push(errors, v2["_errors"][i])
    i = i + 1
  }
  return {
    "_type": "invalid",
    "_value": nil,
    "_errors": errors
  }
}

fn validation_get_errors(v: any) -> array {
  return v["_errors"]
}

fn validation_to_result(v: any) -> any {
  if v["_type"] == "valid" {
    return ok(v["_value"])
  }
  return err(v["_errors"])
}

fn validation_collect(validations: array) -> any {
  values = []
  errors = []
  i = 0
  while i < length(validations) {
    if validations[i]["_type"] == "valid" {
      push(values, validations[i]["_value"])
    } else {
      j = 0
      while j < length(validations[i]["_errors"]) {
        push(errors, validations[i]["_errors"][j])
        j = j + 1
      }
    }
    i = i + 1
  }
  if length(errors) > 0 {
    return { "_type": "invalid", "_value": nil, "_errors": errors }
  }
  return validation_ok(values)
}

# ================================================================
# FreeLang v4 Core - Iterator Protocol Library
# Lazy iterators with chaining, transformations, and collectors
# ================================================================

# ---- Iterator Types ----

ITER_ARRAY     = "array"
ITER_RANGE     = "range"
ITER_MAP       = "map_iter"
ITER_FILTER    = "filter_iter"
ITER_TAKE      = "take_iter"
ITER_DROP      = "drop_iter"
ITER_ZIP       = "zip_iter"
ITER_CHAIN     = "chain_iter"
ITER_FLAT_MAP  = "flat_map_iter"
ITER_ENUMERATE = "enumerate_iter"
ITER_CHUNK     = "chunk_iter"
ITER_WINDOW    = "window_iter"
ITER_REPEAT    = "repeat_iter"
ITER_CYCLE     = "cycle_iter"
ITER_SCAN      = "scan_iter"
ITER_STEP_BY   = "step_by_iter"
ITER_PEEKABLE  = "peekable_iter"
ITER_EMPTY     = "empty_iter"
ITER_ONCE      = "once_iter"
ITER_GENERATE  = "generate_iter"

# ---- Sentinel ----

ITER_DONE = { "_sentinel": "iter_done" }

fn is_done(value: any) -> bool {
  if value == nil { return true }
  if value["_sentinel"] == "iter_done" { return true }
  return false
}

# ---- Base Iterator ----

fn iter_from_array(arr: array) -> any {
  return {
    "_type": ITER_ARRAY,
    "_source": arr,
    "_index": 0,
    "_len": length(arr)
  }
}

fn iter_range(start: i32, end: i32) -> any {
  return {
    "_type": ITER_RANGE,
    "_current": start,
    "_end": end,
    "_step": 1
  }
}

fn iter_range_step(start: i32, end: i32, step: i32) -> any {
  return {
    "_type": ITER_RANGE,
    "_current": start,
    "_end": end,
    "_step": step
  }
}

fn iter_empty() -> any {
  return { "_type": ITER_EMPTY }
}

fn iter_once(value: any) -> any {
  return {
    "_type": ITER_ONCE,
    "_value": value,
    "_consumed": false
  }
}

fn iter_repeat(value: any) -> any {
  return {
    "_type": ITER_REPEAT,
    "_value": value
  }
}

fn iter_repeat_n(value: any, n: i32) -> any {
  return {
    "_type": ITER_TAKE,
    "_source": iter_repeat(value),
    "_remaining": n
  }
}

fn iter_generate(f: any) -> any {
  return {
    "_type": ITER_GENERATE,
    "_generator": f,
    "_index": 0
  }
}

# ---- Core: next() ----

fn iter_next(it: any) -> any {
  t = it["_type"]

  if t == ITER_ARRAY {
    if it["_index"] >= it["_len"] {
      return ITER_DONE
    }
    value = it["_source"][it["_index"]]
    it["_index"] = it["_index"] + 1
    return value
  }

  if t == ITER_RANGE {
    if it["_step"] > 0 and it["_current"] >= it["_end"] {
      return ITER_DONE
    }
    if it["_step"] < 0 and it["_current"] <= it["_end"] {
      return ITER_DONE
    }
    value = it["_current"]
    it["_current"] = it["_current"] + it["_step"]
    return value
  }

  if t == ITER_MAP {
    value = iter_next(it["_source"])
    if is_done(value) { return ITER_DONE }
    return it["_fn"](value)
  }

  if t == ITER_FILTER {
    while true {
      value = iter_next(it["_source"])
      if is_done(value) { return ITER_DONE }
      if it["_predicate"](value) {
        return value
      }
    }
  }

  if t == ITER_TAKE {
    if it["_remaining"] <= 0 { return ITER_DONE }
    value = iter_next(it["_source"])
    if is_done(value) { return ITER_DONE }
    it["_remaining"] = it["_remaining"] - 1
    return value
  }

  if t == ITER_DROP {
    while it["_remaining"] > 0 {
      v = iter_next(it["_source"])
      if is_done(v) { return ITER_DONE }
      it["_remaining"] = it["_remaining"] - 1
    }
    return iter_next(it["_source"])
  }

  if t == ITER_ZIP {
    v1 = iter_next(it["_left"])
    v2 = iter_next(it["_right"])
    if is_done(v1) or is_done(v2) { return ITER_DONE }
    return [v1, v2]
  }

  if t == ITER_CHAIN {
    if not it["_first_done"] {
      value = iter_next(it["_first"])
      if not is_done(value) { return value }
      it["_first_done"] = true
    }
    return iter_next(it["_second"])
  }

  if t == ITER_FLAT_MAP {
    # Try current inner iterator
    if it["_inner"] != nil {
      value = iter_next(it["_inner"])
      if not is_done(value) { return value }
    }
    # Get next inner iterator from outer
    while true {
      outer_val = iter_next(it["_source"])
      if is_done(outer_val) { return ITER_DONE }
      it["_inner"] = it["_fn"](outer_val)
      value = iter_next(it["_inner"])
      if not is_done(value) { return value }
    }
  }

  if t == ITER_ENUMERATE {
    value = iter_next(it["_source"])
    if is_done(value) { return ITER_DONE }
    idx = it["_index"]
    it["_index"] = it["_index"] + 1
    return [idx, value]
  }

  if t == ITER_SCAN {
    value = iter_next(it["_source"])
    if is_done(value) { return ITER_DONE }
    it["_state"] = it["_fn"](it["_state"], value)
    return it["_state"]
  }

  if t == ITER_STEP_BY {
    value = iter_next(it["_source"])
    if is_done(value) { return ITER_DONE }
    # Skip (step - 1) elements
    skip = it["_step"] - 1
    i = 0
    while i < skip {
      s = iter_next(it["_source"])
      if is_done(s) { break }
      i = i + 1
    }
    return value
  }

  if t == ITER_PEEKABLE {
    if it["_has_peeked"] {
      it["_has_peeked"] = false
      return it["_peeked"]
    }
    return iter_next(it["_source"])
  }

  if t == ITER_EMPTY {
    return ITER_DONE
  }

  if t == ITER_ONCE {
    if it["_consumed"] { return ITER_DONE }
    it["_consumed"] = true
    return it["_value"]
  }

  if t == ITER_REPEAT {
    return it["_value"]
  }

  if t == ITER_GENERATE {
    value = it["_generator"](it["_index"])
    it["_index"] = it["_index"] + 1
    return value
  }

  if t == ITER_CHUNK {
    chunk = []
    i = 0
    while i < it["_size"] {
      value = iter_next(it["_source"])
      if is_done(value) {
        if length(chunk) > 0 { return chunk }
        return ITER_DONE
      }
      push(chunk, value)
      i = i + 1
    }
    return chunk
  }

  if t == ITER_WINDOW {
    if it["_buffer"] == nil {
      # Initialize buffer
      it["_buffer"] = []
      i = 0
      while i < it["_size"] {
        value = iter_next(it["_source"])
        if is_done(value) { return ITER_DONE }
        push(it["_buffer"], value)
        i = i + 1
      }
      # Return copy of buffer
      result = []
      i = 0
      while i < length(it["_buffer"]) {
        push(result, it["_buffer"][i])
        i = i + 1
      }
      return result
    }
    # Slide window
    value = iter_next(it["_source"])
    if is_done(value) { return ITER_DONE }
    pop_front(it["_buffer"])
    push(it["_buffer"], value)
    result = []
    i = 0
    while i < length(it["_buffer"]) {
      push(result, it["_buffer"][i])
      i = i + 1
    }
    return result
  }

  if t == ITER_CYCLE {
    value = iter_next(it["_source"])
    if not is_done(value) {
      push(it["_saved"], value)
      return value
    }
    # Reset to saved values
    if length(it["_saved"]) == 0 { return ITER_DONE }
    it["_cycle_index"] = it["_cycle_index"] % length(it["_saved"])
    value = it["_saved"][it["_cycle_index"]]
    it["_cycle_index"] = it["_cycle_index"] + 1
    return value
  }

  return ITER_DONE
}

# ---- Adapter Methods (return new iterators) ----

fn iter_map(it: any, f: any) -> any {
  return {
    "_type": ITER_MAP,
    "_source": it,
    "_fn": f
  }
}

fn iter_filter(it: any, predicate: any) -> any {
  return {
    "_type": ITER_FILTER,
    "_source": it,
    "_predicate": predicate
  }
}

fn iter_take(it: any, n: i32) -> any {
  return {
    "_type": ITER_TAKE,
    "_source": it,
    "_remaining": n
  }
}

fn iter_drop(it: any, n: i32) -> any {
  return {
    "_type": ITER_DROP,
    "_source": it,
    "_remaining": n
  }
}

fn iter_zip(left: any, right: any) -> any {
  return {
    "_type": ITER_ZIP,
    "_left": left,
    "_right": right
  }
}

fn iter_chain(first: any, second: any) -> any {
  return {
    "_type": ITER_CHAIN,
    "_first": first,
    "_second": second,
    "_first_done": false
  }
}

fn iter_flat_map(it: any, f: any) -> any {
  return {
    "_type": ITER_FLAT_MAP,
    "_source": it,
    "_fn": f,
    "_inner": nil
  }
}

fn iter_enumerate(it: any) -> any {
  return {
    "_type": ITER_ENUMERATE,
    "_source": it,
    "_index": 0
  }
}

fn iter_scan(it: any, initial: any, f: any) -> any {
  return {
    "_type": ITER_SCAN,
    "_source": it,
    "_state": initial,
    "_fn": f
  }
}

fn iter_step_by(it: any, step: i32) -> any {
  return {
    "_type": ITER_STEP_BY,
    "_source": it,
    "_step": if step < 1 { 1 } else { step }
  }
}

fn iter_peekable(it: any) -> any {
  return {
    "_type": ITER_PEEKABLE,
    "_source": it,
    "_peeked": nil,
    "_has_peeked": false
  }
}

fn iter_peek(it: any) -> any {
  if it["_type"] != ITER_PEEKABLE {
    return nil
  }
  if not it["_has_peeked"] {
    it["_peeked"] = iter_next(it["_source"])
    it["_has_peeked"] = true
  }
  return it["_peeked"]
}

fn iter_chunks(it: any, size: i32) -> any {
  return {
    "_type": ITER_CHUNK,
    "_source": it,
    "_size": if size < 1 { 1 } else { size }
  }
}

fn iter_windows(it: any, size: i32) -> any {
  return {
    "_type": ITER_WINDOW,
    "_source": it,
    "_size": if size < 1 { 1 } else { size },
    "_buffer": nil
  }
}

fn iter_cycle(it: any) -> any {
  return {
    "_type": ITER_CYCLE,
    "_source": it,
    "_saved": [],
    "_cycle_index": 0
  }
}

# ---- Consuming Methods (consume iterator, return value) ----

fn iter_collect(it: any) -> array {
  result = []
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    push(result, value)
  }
  return result
}

fn iter_collect_to_map(it: any) -> any {
  # Expects iterator of [key, value] pairs
  result = {}
  while true {
    pair = iter_next(it)
    if is_done(pair) { break }
    result[pair[0]] = pair[1]
  }
  return result
}

fn iter_count(it: any) -> i32 {
  count = 0
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    count = count + 1
  }
  return count
}

fn iter_sum(it: any) -> any {
  total = 0
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    total = total + value
  }
  return total
}

fn iter_product(it: any) -> any {
  result = 1
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    result = result * value
  }
  return result
}

fn iter_min(it: any) -> any {
  result = nil
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    if result == nil or value < result {
      result = value
    }
  }
  return result
}

fn iter_max(it: any) -> any {
  result = nil
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    if result == nil or value > result {
      result = value
    }
  }
  return result
}

fn iter_min_by(it: any, compare: any) -> any {
  result = nil
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    if result == nil or compare(value, result) < 0 {
      result = value
    }
  }
  return result
}

fn iter_max_by(it: any, compare: any) -> any {
  result = nil
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    if result == nil or compare(value, result) > 0 {
      result = value
    }
  }
  return result
}

fn iter_reduce(it: any, f: any) -> any {
  acc = iter_next(it)
  if is_done(acc) { return nil }
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    acc = f(acc, value)
  }
  return acc
}

fn iter_fold(it: any, initial: any, f: any) -> any {
  acc = initial
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    acc = f(acc, value)
  }
  return acc
}

fn iter_for_each(it: any, f: any) {
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    f(value)
  }
}

fn iter_find(it: any, predicate: any) -> any {
  while true {
    value = iter_next(it)
    if is_done(value) { return nil }
    if predicate(value) { return value }
  }
}

fn iter_find_map(it: any, f: any) -> any {
  while true {
    value = iter_next(it)
    if is_done(value) { return nil }
    mapped = f(value)
    if mapped != nil { return mapped }
  }
}

fn iter_position(it: any, predicate: any) -> i32 {
  idx = 0
  while true {
    value = iter_next(it)
    if is_done(value) { return -1 }
    if predicate(value) { return idx }
    idx = idx + 1
  }
}

fn iter_any(it: any, predicate: any) -> bool {
  while true {
    value = iter_next(it)
    if is_done(value) { return false }
    if predicate(value) { return true }
  }
}

fn iter_all(it: any, predicate: any) -> bool {
  while true {
    value = iter_next(it)
    if is_done(value) { return true }
    if not predicate(value) { return false }
  }
}

fn iter_none_match(it: any, predicate: any) -> bool {
  while true {
    value = iter_next(it)
    if is_done(value) { return true }
    if predicate(value) { return false }
  }
}

fn iter_nth(it: any, n: i32) -> any {
  i = 0
  while true {
    value = iter_next(it)
    if is_done(value) { return nil }
    if i == n { return value }
    i = i + 1
  }
}

fn iter_last(it: any) -> any {
  result = nil
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    result = value
  }
  return result
}

fn iter_first(it: any) -> any {
  return iter_next(it)
}

fn iter_join(it: any, separator: string) -> string {
  result = ""
  first = true
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    if not first {
      result = result + separator
    }
    result = result + to_string(value)
    first = false
  }
  return result
}

fn iter_partition(it: any, predicate: any) -> any {
  yes = []
  no = []
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    if predicate(value) {
      push(yes, value)
    } else {
      push(no, value)
    }
  }
  return [yes, no]
}

fn iter_group_by(it: any, key_fn: any) -> any {
  groups = {}
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    key = key_fn(value)
    k = to_string(key)
    if groups[k] == nil {
      groups[k] = []
    }
    push(groups[k], value)
  }
  return groups
}

fn iter_uniq(it: any) -> any {
  seen = {}
  return iter_filter(it, fn(value) {
    key = to_string(value)
    if seen[key] != nil { return false }
    seen[key] = true
    return true
  })
}

fn iter_uniq_by(it: any, key_fn: any) -> any {
  seen = {}
  return iter_filter(it, fn(value) {
    key = to_string(key_fn(value))
    if seen[key] != nil { return false }
    seen[key] = true
    return true
  })
}

fn iter_flatten(it: any) -> any {
  return iter_flat_map(it, fn(arr) {
    return iter_from_array(arr)
  })
}

fn iter_intersperse(it: any, separator: any) -> any {
  first = true
  return iter_flat_map(it, fn(value) {
    if first {
      first = false
      return iter_once(value)
    }
    return iter_chain(iter_once(separator), iter_once(value))
  })
}

fn iter_take_while(it: any, predicate: any) -> any {
  done = false
  return iter_filter(it, fn(value) {
    if done { return false }
    if not predicate(value) {
      done = true
      return false
    }
    return true
  })
}

fn iter_skip_while(it: any, predicate: any) -> any {
  skipping = true
  return iter_filter(it, fn(value) {
    if not skipping { return true }
    if not predicate(value) {
      skipping = false
      return true
    }
    return false
  })
}

# ---- Statistics on Iterators ----

fn iter_average(it: any) -> f64 {
  total = 0.0
  count = 0
  while true {
    value = iter_next(it)
    if is_done(value) { break }
    total = total + (value as f64)
    count = count + 1
  }
  if count == 0 { return 0.0 }
  return total / (count as f64)
}

fn iter_variance(it: any) -> f64 {
  values = iter_collect(it)
  n = length(values)
  if n == 0 { return 0.0 }

  # Mean
  sum = 0.0
  i = 0
  while i < n {
    sum = sum + (values[i] as f64)
    i = i + 1
  }
  mean = sum / (n as f64)

  # Variance
  sq_diff = 0.0
  i = 0
  while i < n {
    diff = (values[i] as f64) - mean
    sq_diff = sq_diff + diff * diff
    i = i + 1
  }
  return sq_diff / (n as f64)
}

# ---- Iterator Combinators (create from multiple) ----

fn iter_merge(it1: any, it2: any, compare: any) -> any {
  # Merge two sorted iterators
  return iter_generate(fn(idx) {
    # Simplified: alternate between iterators
    if idx % 2 == 0 {
      return iter_next(it1)
    }
    return iter_next(it2)
  })
}

fn iter_product_cross(it1: any, it2_arr: array) -> any {
  # Cartesian product
  arr1 = iter_collect(it1)
  pairs = []
  i = 0
  while i < length(arr1) {
    j = 0
    while j < length(it2_arr) {
      push(pairs, [arr1[i], it2_arr[j]])
      j = j + 1
    }
    i = i + 1
  }
  return iter_from_array(pairs)
}

fn iter_interleave(it1: any, it2: any) -> any {
  turn = true
  done1 = false
  done2 = false
  return iter_generate(fn(idx) {
    if done1 and done2 { return ITER_DONE }
    if turn and not done1 {
      v = iter_next(it1)
      turn = false
      if is_done(v) {
        done1 = true
        if done2 { return ITER_DONE }
        v = iter_next(it2)
        if is_done(v) { done2 = true; return ITER_DONE }
        return v
      }
      return v
    }
    if not done2 {
      v = iter_next(it2)
      turn = true
      if is_done(v) {
        done2 = true
        if done1 { return ITER_DONE }
        v = iter_next(it1)
        if is_done(v) { done1 = true; return ITER_DONE }
        return v
      }
      return v
    }
    return ITER_DONE
  })
}

