# FreeLang v4 Example: Data Structures Showcase
# Demonstrates HashMap, LinkedList, Queue, Stack, Set usage
# ================================================================

# ---- Binary Search Tree ----

fn bst_node(key: i32, value: any) -> any {
  return {
    "key": key,
    "value": value,
    "left": nil,
    "right": nil,
    "height": 1
  }
}

fn bst_height(node: any) -> i32 {
  if node == nil { return 0 }
  return node["height"]
}

fn bst_update_height(node: any) {
  lh = bst_height(node["left"])
  rh = bst_height(node["right"])
  node["height"] = 1 + (if lh > rh { lh } else { rh })
}

fn bst_insert(root: any, key: i32, value: any) -> any {
  if root == nil {
    return bst_node(key, value)
  }

  if key < root["key"] {
    root["left"] = bst_insert(root["left"], key, value)
  } else if key > root["key"] {
    root["right"] = bst_insert(root["right"], key, value)
  } else {
    root["value"] = value  # Update existing key
  }

  bst_update_height(root)
  return root
}

fn bst_search(root: any, key: i32) -> any {
  if root == nil { return nil }
  if key == root["key"] { return root["value"] }
  if key < root["key"] { return bst_search(root["left"], key) }
  return bst_search(root["right"], key)
}

fn bst_min(root: any) -> any {
  if root == nil { return nil }
  current = root
  while current["left"] != nil {
    current = current["left"]
  }
  return current
}

fn bst_max(root: any) -> any {
  if root == nil { return nil }
  current = root
  while current["right"] != nil {
    current = current["right"]
  }
  return current
}

fn bst_inorder(root: any) -> array {
  if root == nil { return [] }
  result = []
  left = bst_inorder(root["left"])
  i = 0
  while i < length(left) {
    push(result, left[i])
    i = i + 1
  }
  push(result, { "key": root["key"], "value": root["value"] })
  right = bst_inorder(root["right"])
  i = 0
  while i < length(right) {
    push(result, right[i])
    i = i + 1
  }
  return result
}

fn bst_size(root: any) -> i32 {
  if root == nil { return 0 }
  return 1 + bst_size(root["left"]) + bst_size(root["right"])
}

fn bst_contains(root: any, key: i32) -> bool {
  return bst_search(root, key) != nil
}

# ---- Trie (Prefix Tree) ----

fn trie_create() -> any {
  return {
    "children": {},
    "is_end": false,
    "value": nil,
    "count": 0
  }
}

fn trie_insert(root: any, word: string, value: any) {
  node = root
  i = 0
  while i < length(word) {
    ch = char_at(word, i)
    if node["children"][ch] == nil {
      node["children"][ch] = trie_create()
    }
    node = node["children"][ch]
    i = i + 1
  }
  node["is_end"] = true
  node["value"] = value
  root["count"] = root["count"] + 1
}

fn trie_search(root: any, word: string) -> any {
  node = root
  i = 0
  while i < length(word) {
    ch = char_at(word, i)
    if node["children"][ch] == nil {
      return nil
    }
    node = node["children"][ch]
    i = i + 1
  }
  if node["is_end"] { return node["value"] }
  return nil
}

fn trie_starts_with(root: any, prefix: string) -> bool {
  node = root
  i = 0
  while i < length(prefix) {
    ch = char_at(prefix, i)
    if node["children"][ch] == nil {
      return false
    }
    node = node["children"][ch]
    i = i + 1
  }
  return true
}

fn trie_words_with_prefix(root: any, prefix: string) -> array {
  # Find prefix node
  node = root
  i = 0
  while i < length(prefix) {
    ch = char_at(prefix, i)
    if node["children"][ch] == nil {
      return []
    }
    node = node["children"][ch]
    i = i + 1
  }
  # Collect all words from this node
  results = []
  trie_collect_words(node, prefix, results)
  return results
}

fn trie_collect_words(node: any, current: string, results: array) {
  if node["is_end"] {
    push(results, current)
  }
  # Iterate children (simplified: check common chars)
  chars = "abcdefghijklmnopqrstuvwxyz"
  i = 0
  while i < length(chars) {
    ch = char_at(chars, i)
    if node["children"][ch] != nil {
      trie_collect_words(node["children"][ch], current + ch, results)
    }
    i = i + 1
  }
}

# ---- Graph (Adjacency List) ----

fn graph_create(directed: bool) -> any {
  return {
    "vertices": {},
    "vertex_count": 0,
    "edge_count": 0,
    "directed": directed
  }
}

fn graph_add_vertex(g: any, id: string) {
  if g["vertices"][id] == nil {
    g["vertices"][id] = {
      "id": id,
      "edges": [],
      "data": nil
    }
    g["vertex_count"] = g["vertex_count"] + 1
  }
}

fn graph_add_edge(g: any, from: string, to: string, weight: f64) {
  graph_add_vertex(g, from)
  graph_add_vertex(g, to)

  push(g["vertices"][from]["edges"], { "to": to, "weight": weight })

  if not g["directed"] {
    push(g["vertices"][to]["edges"], { "to": from, "weight": weight })
  }

  g["edge_count"] = g["edge_count"] + 1
}

fn graph_has_edge(g: any, from: string, to: string) -> bool {
  if g["vertices"][from] == nil { return false }
  edges = g["vertices"][from]["edges"]
  i = 0
  while i < length(edges) {
    if edges[i]["to"] == to { return true }
    i = i + 1
  }
  return false
}

fn graph_neighbors(g: any, id: string) -> array {
  if g["vertices"][id] == nil { return [] }
  result = []
  edges = g["vertices"][id]["edges"]
  i = 0
  while i < length(edges) {
    push(result, edges[i]["to"])
    i = i + 1
  }
  return result
}

fn graph_bfs(g: any, start: string) -> array {
  visited = {}
  queue = [start]
  result = []
  visited[start] = true

  while length(queue) > 0 {
    current = pop_front(queue)
    push(result, current)

    neighbors = graph_neighbors(g, current)
    i = 0
    while i < length(neighbors) {
      n = neighbors[i]
      if visited[n] == nil {
        visited[n] = true
        push(queue, n)
      }
      i = i + 1
    }
  }

  return result
}

fn graph_dfs(g: any, start: string) -> array {
  visited = {}
  result = []
  graph_dfs_visit(g, start, visited, result)
  return result
}

fn graph_dfs_visit(g: any, vertex: string, visited: any, result: array) {
  if visited[vertex] != nil { return }
  visited[vertex] = true
  push(result, vertex)

  neighbors = graph_neighbors(g, vertex)
  i = 0
  while i < length(neighbors) {
    graph_dfs_visit(g, neighbors[i], visited, result)
    i = i + 1
  }
}

fn graph_shortest_path(g: any, start: string, end: string) -> any {
  # Dijkstra's algorithm (simplified)
  dist = {}
  prev = {}
  visited = {}

  # Initialize distances
  dist[start] = 0.0

  while true {
    # Find unvisited vertex with minimum distance
    min_vertex = nil
    min_dist = 999999999.0

    # Check all vertices
    keys = graph_vertex_ids(g)
    i = 0
    while i < length(keys) {
      v = keys[i]
      if visited[v] == nil and dist[v] != nil and dist[v] < min_dist {
        min_dist = dist[v]
        min_vertex = v
      }
      i = i + 1
    }

    if min_vertex == nil { break }
    if min_vertex == end { break }

    visited[min_vertex] = true

    # Update neighbors
    if g["vertices"][min_vertex] != nil {
      edges = g["vertices"][min_vertex]["edges"]
      i = 0
      while i < length(edges) {
        e = edges[i]
        alt = dist[min_vertex] + e["weight"]
        if dist[e["to"]] == nil or alt < dist[e["to"]] {
          dist[e["to"]] = alt
          prev[e["to"]] = min_vertex
        }
        i = i + 1
      }
    }
  }

  # Reconstruct path
  path = []
  current = end
  while current != nil {
    push(path, current)
    current = prev[current]
  }

  # Reverse path
  reversed = []
  i = length(path) - 1
  while i >= 0 {
    push(reversed, path[i])
    i = i - 1
  }

  return {
    "path": reversed,
    "distance": if dist[end] != nil { dist[end] } else { -1 },
    "found": dist[end] != nil
  }
}

